@app.route('/api/takserver/two-server/migration-database-deb-status', methods=['GET'])
@login_required
def takserver_migration_database_deb_status():
    """Report whether uploads include takserver-database .deb (same dir as deploy/upgrade). Uses dpkg-deb locally; no SSH."""
    uploaded = [f for f in os.listdir(UPLOAD_DIR) if f.endswith('.deb') or f.endswith('.rpm')]
    db_pkg = next((f for f in uploaded if 'database' in f.lower()), '')
    out = {
        'has_database_deb': False,
        'filename': None,
        'deb_version': None,
        'file_missing': False,
    }
    if not db_pkg:
        return jsonify(out)
    local_path = os.path.join(UPLOAD_DIR, db_pkg)
    out['filename'] = db_pkg
    if not os.path.isfile(local_path):
        out['file_missing'] = True
        return jsonify(out)
    out['has_database_deb'] = True
    _pkg, ver = _local_deb_control_fields(local_path)
    out['deb_version'] = ver
    return jsonify(out)


@app.route('/api/takserver/pin-packages', methods=['POST'])
@login_required
def takserver_pin_packages():
    """Add takserver* and postgresql* to the unattended-upgrades blacklist on both Server Two (local) and Server One (SSH).
    Prevents automatic apt upgrades from breaking the DB connection or regenerating credentials."""
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    is_two_server = cfg.get('mode') == 'two_server'
    results = {}

    pin_snippet = (
        'UA_CONF="/etc/apt/apt.conf.d/50unattended-upgrades"; '
        'if [ ! -f "$UA_CONF" ]; then echo NO_UA; '
        'elif grep -q "takserver" "$UA_CONF" 2>/dev/null; then echo ALREADY_PINNED; '
        'else '
        'sudo sed -i \'/Unattended-Upgrade::Package-Blacklist/a\\        "takserver*";\\n        "postgresql*";\' "$UA_CONF" 2>/dev/null && echo PINNED || echo FAILED; '
        'fi'
    )

    try:
        r = subprocess.run(pin_snippet, shell=True, capture_output=True, text=True, timeout=15)
        out = (r.stdout or '').strip()
        if 'PINNED' in out:
            results['server_two'] = 'pinned'
        elif 'ALREADY_PINNED' in out:
            results['server_two'] = 'already_pinned'
        elif 'NO_UA' in out:
            results['server_two'] = 'no_unattended_upgrades'
        else:
            results['server_two'] = 'failed'
    except Exception as e:
        results['server_two'] = f'error: {str(e)[:100]}'

    if is_two_server:
        s1 = cfg.get('server_one', {})
        if (s1.get('host') or '').strip():
            try:
                ok, out = _ssh_probe(s1, pin_snippet, timeout=15)
                out_s = (out or '').strip()
                if ok and 'PINNED' in out_s:
                    results['server_one'] = 'pinned'
                elif ok and 'ALREADY_PINNED' in out_s:
                    results['server_one'] = 'already_pinned'
                elif ok and 'NO_UA' in out_s:
                    results['server_one'] = 'no_unattended_upgrades'
                else:
                    results['server_one'] = f'failed: {out_s[:100]}'
            except Exception as e:
                results['server_one'] = f'error: {str(e)[:100]}'
        else:
            results['server_one'] = 'no_host_configured'

    all_ok = all(v in ('pinned', 'already_pinned', 'no_unattended_upgrades') for v in results.values())
    msgs = []
    for server, status in results.items():
        label = 'Server One (DB)' if server == 'server_one' else 'This host'
        if status == 'pinned':
            msgs.append(f'{label}: packages pinned')
        elif status == 'already_pinned':
            msgs.append(f'{label}: already pinned')
        elif status == 'no_unattended_upgrades':
            # v10.1.37: this used to read "(safe)". On RHEL/Rocky the apt config
            # file is ALWAYS absent, so every EL box was told it was safe on the
            # strength of a file we never expected to find — a guess, not a check.
            # The EL analogue is dnf-automatic; report what we actually observed.
            if _pkg_mgr() == 'dnf':
                _p = _auto_update_posture()
                if not _p.get('installed'):
                    msgs.append(f'{label}: dnf-automatic not installed — nothing updates this host automatically')
                elif _p.get('enabled'):
                    msgs.append(f'{label}: ⚠ dnf-automatic is ENABLED and has no package allowlist — it can update TAK components')
                else:
                    msgs.append(f'{label}: dnf-automatic installed but not enabled')
            else:
                msgs.append(f'{label}: unattended-upgrades not installed')
        else:
            msgs.append(f'{label}: {status}')

    return jsonify({'success': all_ok, 'results': results, 'message': '; '.join(msgs)})


def _pin_status_short(s):
    """Short label for pin status for UI breakdown."""
    return {'pinned': 'locked', 'not_pinned': 'unlocked', 'safe': 'unlocked (no UA)', 'unknown': '?'}.get(s, s)


@app.route('/api/takserver/pin-packages/status')
@login_required
def takserver_pin_packages_status():
    """Check if takserver/postgresql packages are already pinned on both hosts."""
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    is_two_server = cfg.get('mode') == 'two_server'
    results = {}

    check_cmd = (
        'UA_CONF="/etc/apt/apt.conf.d/50unattended-upgrades"; '
        'if [ ! -f "$UA_CONF" ]; then echo NO_UA; '
        'elif grep -q "takserver" "$UA_CONF" 2>/dev/null; then echo PINNED; '
        'else echo NOT_PINNED; fi'
    )

    try:
        r = subprocess.run(check_cmd, shell=True, capture_output=True, text=True, timeout=10)
        out = (r.stdout or '').strip()
        results['server_two'] = 'pinned' if 'PINNED' in out else ('safe' if 'NO_UA' in out else 'not_pinned')
    except Exception:
        results['server_two'] = 'unknown'

    if is_two_server:
        s1 = cfg.get('server_one', {})
        if (s1.get('host') or '').strip():
            try:
                ok, out = _ssh_probe(s1, check_cmd, timeout=10)
                out_s = (out or '').strip()
                if ok and 'PINNED' in out_s:
                    results['server_one'] = 'pinned'
                elif ok and 'NO_UA' in out_s:
                    results['server_one'] = 'safe'
                elif ok:
                    results['server_one'] = 'not_pinned'
                else:
                    results['server_one'] = 'unknown'
            except Exception:
                results['server_one'] = 'unknown'

    # Only show "Locked" when blacklist is actually present. 'safe' (no UA file) = show Unlocked.
    all_pinned = all(v == 'pinned' for v in results.values())
    # Per-host breakdown for two-server so UI can show which host is still pinned.
    breakdown = []
    if results.get('server_two') is not None:
        breakdown.append('This host: ' + _pin_status_short(results['server_two']))
    if results.get('server_one') is not None:
        breakdown.append('DB host: ' + _pin_status_short(results['server_one']))
    return jsonify({'pinned': all_pinned, 'results': results, 'breakdown': ' · '.join(breakdown) if breakdown else None})


def _recommended_takserver_heap_gb(total_ram_gb):
    """Suggest -Xmx heap in GB from total system RAM (TAK Server core runs on this host)."""
    if total_ram_gb is None or total_ram_gb <= 0:
        return 4
    if total_ram_gb >= 32:
        return 12
    if total_ram_gb >= 16:
        return 8
    if total_ram_gb >= 8:
        return 4
    return 2


def _get_current_takserver_heap_gb():
    """Return current total JVM heap in GB from /etc/default/takserver or setenv.sh, else None."""
    import re
    defaults_file = '/etc/default/takserver'
    for path in [defaults_file]:
        content = None
        try:
            with open(path, 'r') as f:
                content = f.read()
        except (OSError, IOError):
            try:
                content = _read_priv(path) or content  # v10.0.5 non-root: broker read (literal `sudo cat` bypassed the broker)
            except Exception:
                pass
        if content:
            m = re.search(r'# infra-TAK total heap: (\d+)g', content)
            if m:
                return int(m.group(1))
    setenv = '/opt/tak/setenv.sh'
    content = None
    try:
        with open(setenv, 'r') as f:
            content = f.read()
    except (OSError, IOError):
        try:
            content = _read_priv(setenv) or content  # v10.0.5 non-root: broker read (literal `sudo cat` bypassed the broker)
        except Exception:
            pass
    if content:
        m = re.search(r'-Xmx(\d+)g', content, re.IGNORECASE)
        if m:
            return int(m.group(1))
    return None


@app.route('/api/takserver/heap-info')
@login_required
def takserver_heap_info():
    """Return total RAM, recommended heap, and current heap (if set via drop-in) for this host."""
    total = _get_total_ram_gb_local()
    recommended = _recommended_takserver_heap_gb(total)
    current = _get_current_takserver_heap_gb()
    return jsonify({'total_ram_gb': total, 'recommended_heap_gb': recommended, 'current_heap_gb': current})


@app.route('/api/takserver/set-heap', methods=['POST'])
@login_required
def takserver_set_heap():
    """Set TAK Server JVM heap via /etc/default/takserver (individual MAX_HEAP vars) and restart."""
    data = request.get_json() or {}
    heap_gb = data.get('heap_gb')
    total_ram_gb = _get_total_ram_gb_local()
    if heap_gb is None:
        heap_gb = _recommended_takserver_heap_gb(total_ram_gb)
    try:
        heap_gb = int(heap_gb)
        if heap_gb < 2 or heap_gb > 64:
            return jsonify({'success': False, 'error': 'heap_gb must be between 2 and 64'}), 400
    except (TypeError, ValueError):
        return jsonify({'success': False, 'error': 'heap_gb must be an integer'}), 400

    import re as _re
    total_mb = heap_gb * 1024
    w_config = 1.0 / 35000
    w_api = 1.0 / 6300
    w_msg = 1.0 / 6300
    w_plugin = 1.0 / 30000
    w_retain = 1.0 / 30000
    w_total = w_config + w_api + w_msg + w_plugin + w_retain
    config_mb = int(total_mb * w_config / w_total)
    api_mb = int(total_mb * w_api / w_total)
    msg_mb = int(total_mb * w_msg / w_total)
    plugin_mb = int(total_mb * w_plugin / w_total)
    retain_mb = int(total_mb * w_retain / w_total)

    defaults_content = (
        f"# infra-TAK total heap: {heap_gb}g\n"
        f"# Proportional split across TAK Server processes (same ratios as setenv.sh defaults)\n"
        f"export CONFIG_MAX_HEAP={config_mb}\n"
        f"export API_MAX_HEAP={api_mb}\n"
        f"export MESSAGING_MAX_HEAP={msg_mb}\n"
        f"export PLUGIN_MANAGER_MAX_HEAP={plugin_mb}\n"
        f"export RETENTION_MAX_HEAP={retain_mb}\n"
    )
    defaults_file = '/etc/default/takserver'
    try:
        # v10.0.5 non-root: /etc/default/takserver + /opt/tak/setenv.sh are root-owned;
        # was bare `sudo tee`/`sudo cat` (bypass broker → EPERM non-root). Route via broker.
        try:
            _write_priv(defaults_file, defaults_content)
        except Exception as _we:
            return jsonify({'success': False, 'error': f'Failed to write {defaults_file}: {str(_we)[:200]}'}), 500

        setenv = '/opt/tak/setenv.sh'
        try:
            _setenv_cur = _read_priv(setenv)
        except Exception:
            _setenv_cur = ''
        if _setenv_cur:
            cleaned = _re.sub(r'\n*export JAVA_OPTS="\$JAVA_OPTS\s+-Xms\d+[gGmM]\s+-Xmx\d+[gGmM]"\n*', '\n', _setenv_cur)
            # v10.0.5 container TAK: the container does NOT mount or read /etc/default/takserver
            # (no systemd unit) — its entrypoint sources ONLY /opt/tak/setenv.sh, which RAM-auto-
            # computes the per-process heaps UNLESS *_MAX_HEAP is already set (`if [ -z … ]`). So on
            # container we must inject the operator's values into setenv.sh itself, or set-heap
            # silently no-ops (confirmed on aws-arm: 8g written to /etc/default was ignored; the
            # container kept the RAM-auto -Xmx). Idempotent managed block, prepended so it is in
            # scope before setenv.sh's own `if [ -z ]` guards run.
            if _tak_is_container():
                _hm_a = '# >>> infra-TAK managed heap >>>'
                _hm_b = '# <<< infra-TAK managed heap <<<'
                cleaned = _re.sub(rf'{_re.escape(_hm_a)}.*?{_re.escape(_hm_b)}\n?', '', cleaned, flags=_re.DOTALL)
                _hm_block = (f"{_hm_a}\n"
                             f"# total {heap_gb}g via console — delete this block to revert to RAM-auto\n"
                             f"export CONFIG_MAX_HEAP={config_mb}\n"
                             f"export API_MAX_HEAP={api_mb}\n"
                             f"export MESSAGING_MAX_HEAP={msg_mb}\n"
                             f"export PLUGIN_MANAGER_MAX_HEAP={plugin_mb}\n"
                             f"export RETENTION_MAX_HEAP={retain_mb}\n"
                             f"{_hm_b}\n")
                cleaned = _hm_block + cleaned
            if cleaned != _setenv_cur:
                _write_priv(setenv, cleaned)

        rr = subprocess.run(_tak_systemctl('restart'), shell=True, capture_output=True, text=True, timeout=120)  # v10.0.1: container-aware
        if rr.returncode != 0:
            return jsonify({'success': False, 'error': f'Restart failed: {(rr.stderr or rr.stdout or "unknown").strip()[:200]}'}), 500
    except subprocess.TimeoutExpired:
        return jsonify({'success': False, 'error': 'Command timed out'}), 500
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:200]}), 500
    return jsonify({
        'success': True,
        'message': f'TAK Server heap set to {heap_gb} GB total across 5 processes and restarted.',
        'heap_gb': heap_gb,
        'current_heap_gb': heap_gb,
        'total_ram_gb': total_ram_gb,
    })


@app.route('/api/takserver/unpin-packages', methods=['POST'])
@login_required
def takserver_unpin_packages():
    """Remove takserver* and postgresql* from unattended-upgrades blacklist on both servers."""
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    is_two_server = cfg.get('mode') == 'two_server'
    results = {}

    # Remove blacklist lines; verify after so we only report UNPINNED when "takserver" is really gone.
    unpin_script = (
        'UA_CONF="/etc/apt/apt.conf.d/50unattended-upgrades"; '
        'if [ ! -f "$UA_CONF" ]; then echo NO_UA; exit 0; fi; '
        'if ! grep -q "takserver" "$UA_CONF" 2>/dev/null; then echo ALREADY_UNPINNED; exit 0; fi; '
        'sudo sed -i -e \'/"takserver\\*"/d\' -e \'/"postgresql\\*"/d\' "$UA_CONF" 2>/dev/null; '
        'if grep -q "takserver" "$UA_CONF" 2>/dev/null; then echo FAILED; else echo UNPINNED; fi'
    )

    try:
        r = subprocess.run(unpin_script, shell=True, capture_output=True, text=True, timeout=15)
        out = (r.stdout or '').strip()
        if 'UNPINNED' in out:
            results['server_two'] = 'unpinned'
        elif 'ALREADY_UNPINNED' in out:
            results['server_two'] = 'already_unpinned'
        elif 'NO_UA' in out:
            results['server_two'] = 'no_unattended_upgrades'
        else:
            results['server_two'] = 'failed'
    except Exception as e:
        results['server_two'] = f'error: {str(e)[:100]}'

    if is_two_server:
        s1 = cfg.get('server_one', {})
        if (s1.get('host') or '').strip():
            try:
                ok, out = _ssh_probe(s1, unpin_script, timeout=15)
                out_s = (out or '').strip()
                if ok and 'UNPINNED' in out_s:
                    results['server_one'] = 'unpinned'
                elif ok and 'ALREADY_UNPINNED' in out_s:
                    results['server_one'] = 'already_unpinned'
                elif ok and 'NO_UA' in out_s:
                    results['server_one'] = 'no_unattended_upgrades'
                else:
                    results['server_one'] = f'failed: {out_s[:100]}'
            except Exception as e:
                results['server_one'] = f'error: {str(e)[:100]}'

    all_ok = all(v in ('unpinned', 'already_unpinned', 'no_unattended_upgrades') for v in results.values())
    msgs = []
    for server, status in results.items():
        label = 'Server One (DB)' if server == 'server_one' else 'This host'
        if status in ('unpinned', 'already_unpinned', 'no_unattended_upgrades'):
            continue
        msgs.append(f'{label}: {status}')
    message = '; '.join(msgs) if msgs else ('Unlocked on all hosts' if all_ok else 'Unlock failed')
    return jsonify({'success': all_ok, 'results': results, 'message': message})


@app.route('/mediamtx')
@login_required
def mediamtx_page():
    settings = load_settings()
    modules = detect_modules()
    mtx = modules.get('mediamtx', {})
    cloudtak_installed = modules.get('cloudtak', {}).get('installed', False)
    mediamtx_deploy_cfg = _get_module_deployment_config(settings, 'mediamtx_deployment')
    if mtx.get('installed') and not mediamtx_deploy_status.get('running', False):
        mediamtx_deploy_status.update({'complete': False, 'error': False})
    mtx_vinfo = _get_mediamtx_version_info() if mtx.get('installed') else {}
    return render_template('mediamtx.html',
        settings=settings, mtx=mtx, version=VERSION,
        cloudtak_installed=cloudtak_installed,
        mediamtx_deploy_cfg=mediamtx_deploy_cfg,
        deploying=mediamtx_deploy_status.get('running', False),
        deploy_done=mediamtx_deploy_status.get('complete', False),
        mediamtx_version=mtx_vinfo.get('version') or '',
        mediamtx_update_available=mtx_vinfo.get('binary_update_available', False),
        mediamtx_latest=mtx_vinfo.get('latest') or '',
        editor_version=mtx_vinfo.get('editor_version') or '',
        editor_update_available=mtx_vinfo.get('editor_update_available', False),
        editor_latest=mtx_vinfo.get('editor_latest') or '',
        # The page states the installed version and, when upstream is newer, points at
        # the web editor. No vetted/channel badges: the operator cannot act on the pin
        # from here, and a console that advertises a version it will not install is the
        # defect this replaced.
        mediamtx_upstream_latest=mtx_vinfo.get('upstream_latest') or '',
        mediamtx_upstream_url=mtx_vinfo.get('upstream_url') or '')


