@app.route('/api/firewall/restrict-source', methods=['POST'])
@login_required
def firewall_restrict_source_api():
    data = request.json if request.is_json else {}
    source = str(data.get('source') or '').strip()
    port = data.get('port')
    proto = (data.get('protocol') or 'tcp').strip().lower()
    action = (data.get('action') or 'allow').strip().lower()
    if not source:
        return jsonify({'success': False, 'error': 'Source IP/CIDR is required'}), 400
    try:
        ipaddress.ip_network(source, strict=False)
    except Exception:
        return jsonify({'success': False, 'error': 'Invalid source IP/CIDR'}), 400
    if not isinstance(port, int) or port < 1 or port > 65535:
        return jsonify({'success': False, 'error': 'Invalid port (1-65535 required)'}), 400
    if proto not in ('tcp', 'udp'):
        return jsonify({'success': False, 'error': 'Protocol must be tcp or udp'}), 400
    if action not in ('allow', 'deny'):
        return jsonify({'success': False, 'error': 'Action must be allow or deny'}), 400
    st = _firewall_status_local()
    if not st.get('supported'):
        return jsonify({'success': False, 'error': st.get('error') or 'No supported firewall (UFW/firewalld) available'}), 400
    try:
        be = _fw_backend()
        if be == 'firewalld':
            # ufw `allow/deny from X to any port Y` ↔ firewalld rich rule (accept/reject).
            fam = 'ipv6' if ':' in source else 'ipv4'
            verb = 'accept' if action == 'allow' else 'reject'
            rule = (f'rule family="{fam}" source address="{source}" '
                    f'port port="{port}" protocol="{proto}" {verb}')
            subprocess.run(_sudo_wrap(['firewall-cmd', '--zone=public', '--permanent',
                                       f'--add-rich-rule={rule}']),
                           capture_output=True, text=True, timeout=15)
            subprocess.run(_sudo_wrap(['firewall-cmd', '--reload']),
                           capture_output=True, text=True, timeout=15)
        else:
            # v10.0.5 non-root: literal `sudo ufw` fails (takwerx not in sudoers) and `|| true`
            # masked it as success — route through the broker shim.
            subprocess.run(_sudo_wrap(['ufw', action, 'from', source, 'to', 'any', 'port', str(port), 'proto', proto]),
                           capture_output=True, text=True, timeout=12)
        st2 = _firewall_status_local()
        return jsonify({'success': True, 'message': f'{action.upper()} from {source} to {port}/{proto}', 'status': st2})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:160]}), 500


@app.route('/api/firewall/delete-rule', methods=['POST'])
@login_required
def firewall_delete_rule_api():
    data = request.json if request.is_json else {}
    number = data.get('number')
    if not isinstance(number, int) or number < 1:
        return jsonify({'success': False, 'error': 'Rule number must be a positive integer'}), 400
    st = _firewall_status_local()
    if not st.get('supported'):
        return jsonify({'success': False, 'error': st.get('error') or 'No supported firewall (UFW/firewalld) available'}), 400
    try:
        be = _fw_backend()
        if be == 'firewalld':
            # firewalld has no rule numbering — map the displayed [ N] to the Nth entry
            # of rules_meta (same order as the rendered rows) and remove the precise
            # firewalld object (port / service / rich-rule).
            meta = st.get('rules_meta') or []
            if number > len(meta):
                return jsonify({'success': False, 'error': f'No rule #{number} (only {len(meta)} present)'}), 400
            m = meta[number - 1]
            if m['kind'] == 'rich':
                arg = f"--remove-rich-rule={m['value']}"
            elif m['kind'] == 'service':
                arg = f"--remove-service={m['value']}"
            else:
                arg = f"--remove-port={m['value']}"
            subprocess.run(_sudo_wrap(['firewall-cmd', '--zone=public', '--permanent', arg]),
                           capture_output=True, text=True, timeout=15)
            subprocess.run(_sudo_wrap(['firewall-cmd', '--reload']),
                           capture_output=True, text=True, timeout=15)
        else:
            # v10.0.5 non-root: literal `sudo ufw` failed (not in sudoers) — route via broker shim.
            subprocess.run(_sudo_wrap(['ufw', '--force', 'delete', str(number)]), capture_output=True, text=True, timeout=12)
        st2 = _firewall_status_local()
        return jsonify({'success': True, 'message': f'Deleted rule #{number}', 'status': st2})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:160]}), 500

@app.route('/fail2ban')
@login_required
def fail2ban_page():
    """Fail2ban: brute-force protection dashboard."""
    settings = load_settings()
    from flask import make_response
    r = make_response(render_template('fail2ban.html',
        settings=settings, version=VERSION,
        installed=os.path.exists('/etc/fail2ban'),
        setup=settings.get('fail2ban_setup', {})))
    r.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate'
    return r

def _f2b_is_available():
    """Return True if fail2ban is actually installed. v10.0.5: `which fail2ban-client` is
    POISONED by the broker shim — a fail2ban-client shim sits on the console PATH even when
    fail2ban isn't installed, so `which` returned 0 and the installer falsely refused with
    'fail2ban is already installed'. Check /etc/fail2ban (created by the package, never by
    the shim) — matches the detect_modules card's `installed` logic."""
    return os.path.exists('/etc/fail2ban')

def _f2b_parse_status(raw):
    """Parse fail2ban-client status authentik output into a dict."""
    result = {'currently_failed': 0, 'total_failed': 0, 'currently_banned': 0,
              'total_banned': 0, 'banned_ips': []}
    if not raw:
        return result
    for line in raw.splitlines():
        line = line.strip()
        if 'Currently failed:' in line:
            try: result['currently_failed'] = int(line.split(':')[1].strip())
            except Exception: pass
        elif 'Total failed:' in line:
            try: result['total_failed'] = int(line.split(':')[1].strip())
            except Exception: pass
        elif 'Currently banned:' in line:
            try: result['currently_banned'] = int(line.split(':')[1].strip())
            except Exception: pass
        elif 'Total banned:' in line:
            try: result['total_banned'] = int(line.split(':')[1].strip())
            except Exception: pass
        elif 'Banned IP list:' in line:
            ips_raw = line.split(':', 1)[1].strip()
            result['banned_ips'] = [ip.strip() for ip in ips_raw.split() if ip.strip()]
    return result

# Virtual / container / overlay interface prefixes that are NOT a gateway LAN: docker
# bridges (172.17-31/16), libvirt, k8s CNIs, VPN/mesh links. These are RFC1918 but are NOT
# the LAN/VNet a real upstream gateway lives on, so _f2b_local_subnets() skips them — only
# the physical NIC's subnet is the one a proxy/gateway shares. (Found during v0.9.58 #6
# field test: the test fleet's jails would have picked up 9 docker bridges each.)
#
# v10.1.11: skipping them HERE is still right, but they are no longer untrusted overall —
# our own containers live on the docker bridges and _f2b_container_subnets() trusts those
# deliberately. See that function for why the "just noise" reasoning was wrong.
_F2B_VIRTUAL_IFACE_PREFIXES = ('lo', 'docker', 'br-', 'br0', 'veth', 'virbr', 'vnet',
                               'flannel', 'cni', 'cali', 'kube', 'tailscale', 'nb-',
                               'wg', 'zt', 'tun', 'tap', 'cilium', 'ovs', 'weave')

def _f2b_local_subnets():
    """Derive the box's directly-attached *private* IPv4 subnets (CIDR) from the
    global-scope addresses on its PHYSICAL NICs. On a gateway/proxy/VNet-fronted deploy
    the upstream gateway usually lives on the box's own attached subnet, so trusting that
    subnet keeps the gateway from ever being banned — the CORAZ total-outage failure mode
    ([[fail2ban-bans-azure-gateway]]). Two guards: RFC1918 only (a direct-public box's
    attached subnet is public — never whitelist public neighbours), and virtual/container
    interfaces are skipped (docker bridges, CNIs, VPN links — noise, not a gateway LAN).
    Best-effort; returns [] on any failure (so the jail still gets localhost)."""
    subnets = []
    try:
        r = subprocess.run(['ip', '-o', '-4', 'addr', 'show', 'scope', 'global'],
                           capture_output=True, text=True, timeout=5)
        for line in r.stdout.splitlines():
            parts = line.split()
            if len(parts) < 4:
                continue
            ifname = parts[1].split('@')[0]  # strip veth peer suffix (eth0@if5)
            if ifname.startswith(_F2B_VIRTUAL_IFACE_PREFIXES):
                continue
            for i, tok in enumerate(parts):
                if tok == 'inet' and i + 1 < len(parts):
                    try:
                        net = ipaddress.ip_network(parts[i + 1], strict=False)
                        if net.is_private and str(net) not in subnets:
                            subnets.append(str(net))
                    except Exception:
                        pass
    except Exception:
        pass
    return subnets


# Overlay interfaces infra-TAK ITSELF brings up to manage a box: the WireGuard
# relay/anchor from the Connectivity Wizard, and NetBird. These are EXCLUDED from
# _f2b_local_subnets() above (they match _F2B_VIRTUAL_IFACE_PREFIXES), which is
# right for docker/CNI noise and WRONG here — see _f2b_mgmt_tunnel_subnets().
_F2B_MGMT_TUNNEL_PREFIXES = ('wg', 'nb-', 'netbird')
# NetBird hands out 100.64.0.0/10 (RFC 6598 shared space). Python's is_private is
# False for it, so the RFC1918 test in _f2b_local_subnets() would reject it twice
# over — once on the interface name, once on the address.
_F2B_CGNAT = ipaddress.ip_network('100.64.0.0/10')


def _f2b_mgmt_tunnel_subnets():
    """Subnets of the management tunnels infra-TAK itself creates — never bannable.

    A box behind CGNAT or without a static IP is reached ONLY through its tunnel
    (the Oracle-relay strategy). fail2ban's `iptables-allports` action blocks EVERY
    port from a banned address, so one ban on the tunnel gateway locks the operator
    out of a machine they cannot walk up to — and `recidive` escalates repeats from
    an hour to far longer. Field-hit 2026-07-26: the sshd jail banned the relay's
    172.31.99.1 and the box went dark to the relay while still answering ping.

    This became reachable because the no-rsyslog fix (469f2a2) made the sshd jail
    actually run on boxes where it had been dead — the jail working is the point,
    but it must not eat the road in.

    Scope is deliberately narrow: ONLY interfaces we bring up ourselves. A
    third-party VPN (tailscale/zt/tun/tap) may carry users we do not vouch for, so
    those stay excluded and the operator can add them via `fail2ban_ignore_cidrs`.
    Accepts RFC1918 or CGNAT. Best-effort; [] on any failure."""
    subnets = []
    try:
        r = subprocess.run(['ip', '-o', '-4', 'addr', 'show', 'scope', 'global'],
                           capture_output=True, text=True, timeout=5)
        for line in r.stdout.splitlines():
            parts = line.split()
            if len(parts) < 4:
                continue
            ifname = parts[1].split('@')[0]
            if not ifname.startswith(_F2B_MGMT_TUNNEL_PREFIXES):
                continue
            for i, tok in enumerate(parts):
                if tok == 'inet' and i + 1 < len(parts):
                    try:
                        net = ipaddress.ip_network(parts[i + 1], strict=False)
                    except Exception:
                        continue
                    if (net.is_private or net.subnet_of(_F2B_CGNAT)) and str(net) not in subnets:
                        subnets.append(str(net))
    except Exception:
        pass
    return subnets


# Bridges that carry OUR OWN containers. Deliberately narrow: docker0, docker's
# user-defined networks (`br-<12 hex>` — note this does NOT match a host bridge named
# `br0`), and podman's equivalents. A third-party CNI/VPN bridge is NOT in here.
_F2B_CONTAINER_IFACE_PREFIXES = ('docker', 'br-', 'podman', 'cni-podman')


def _f2b_container_subnets():
    """Subnets of the container bridges infra-TAK itself brings up — never bannable.

    TAK Portal, Node-RED and CloudTAK all run as containers and reach TAK Server at
    its PUBLIC FQDN (`TAK_URL = https://takserver.<fqdn>:8443/Marti`), so TAK logs
    their docker-bridge address as the remote peer. The takserver jail bans on ANY
    TLS handshake rejection (`NioNettyServerHandler error ... Remote address: <HOST>`)
    at 20 hits / 300 s — and the portal's dashboard poll runs every 15 s, i.e. exactly
    20 attempts per 300 s. One handshake fault (expired client cert, rotated CA, TAK
    restarting) therefore bans our own service in ~5 minutes, deterministically. The
    ban is `iptables-allports`/`ufw`, so it severs that container from the host on
    EVERY port, and `recidive` (bantime -1) escalates a repeat to permanent.

    Field-hit 2026-07-25: the takserver jail banned 172.21.0.2 — the nodered container
    — on test8 and test12 within two seconds of each other, with recidive already
    counting. Operators were "fixing" the resulting API failures by disabling fail2ban
    outright, which is a far worse trade than trusting our own bridges.

    This reverses the v0.9.58 judgement that docker bridges are "just noise" in
    ignoreip. That call weighed a ~10-token-longer ignoreip against nothing, because
    the ban-our-own-services failure mode had not been seen yet. The residual risk is
    narrow: these bridges are host-local and not routable from off-box, so an external
    attacker cannot source an address into them; and fail2ban was never the control
    containing a compromised container. Best-effort; [] on any failure."""
    subnets = []
    try:
        r = subprocess.run(['ip', '-o', '-4', 'addr', 'show', 'scope', 'global'],
                           capture_output=True, text=True, timeout=5)
        for line in r.stdout.splitlines():
            parts = line.split()
            if len(parts) < 4:
                continue
            ifname = parts[1].split('@')[0]
            if not ifname.startswith(_F2B_CONTAINER_IFACE_PREFIXES):
                continue
            for i, tok in enumerate(parts):
                if tok == 'inet' and i + 1 < len(parts):
                    try:
                        net = ipaddress.ip_network(parts[i + 1], strict=False)
                    except Exception:
                        continue
                    # RFC1918 only — never whitelist a public range off a bridge name.
                    if net.is_private and str(net) not in subnets:
                        subnets.append(str(net))
    except Exception:
        pass
    return subnets


def _f2b_own_addresses():
    """The box's OWN addresses — never bannable. A machine must not ban itself.

    Hit for real on test8, 2026-07-27: five failed logins driven from the box itself
    made the Authentik jail ban 63.250.55.132 — the box's own public IP — and ufw
    duly installed rules dropping it on EVERY port. Anything that reaches the box via
    its own public address is then severed: a service dialling its own FQDN, a
    health check, a loopback-through-the-edge path. Nothing in the ignore list
    prevented it, because _f2b_local_subnets() is RFC1918-only by design and a public
    address is not private.

    Two sources, because neither alone is complete:
      - addresses actually on the physical NICs (covers bare metal / direct-public),
      - settings['server_ip'], which on AWS/Azure is the NAT'd public address that
        never appears in `ip addr` at all.
    Emitted as bare host addresses, deliberately NOT the surrounding subnet — on a
    direct-public box that would whitelist unrelated neighbours."""
    out = []

    def _add(a):
        if a and a not in out:
            out.append(a)

    try:
        r = subprocess.run(['ip', '-o', 'addr', 'show', 'scope', 'global'],
                           capture_output=True, text=True, timeout=5)
        for line in r.stdout.splitlines():
            parts = line.split()
            if len(parts) < 4:
                continue
            ifname = parts[1].split('@')[0]
            if ifname.startswith(_F2B_VIRTUAL_IFACE_PREFIXES):
                continue                  # container/VPN bridges are trusted as subnets
            for i, tok in enumerate(parts):
                if tok in ('inet', 'inet6') and i + 1 < len(parts):
                    try:
                        _add(str(ipaddress.ip_interface(parts[i + 1]).ip))
                    except Exception:
                        pass
    except Exception:
        pass

    try:
        sip = (load_settings().get('server_ip') or '')
        sip = sip.strip() if isinstance(sip, str) else ''
        if sip:
            _add(str(ipaddress.ip_address(sip)))
    except Exception:
        pass
    return out


def _f2b_fleet_ignore_cidrs():
    """Operator-configured fleet-wide trusted CIDRs (settings 'fail2ban_ignore_cidrs').
    Use this for an upstream gateway/proxy/LB that does NOT share the box's attached
    subnet (e.g. Azure App Gateway backends on a sibling /24). Survives a jail regen
    because every writer re-derives ignoreip from settings on each write."""
    try:
        raw = load_settings().get('fail2ban_ignore_cidrs', '') or ''
    except Exception:
        raw = ''
    return [c.strip() for c in raw.replace(',', ' ').split() if c.strip()]

def _f2b_trusted_ignoreip(extra=''):
    """Build the full ignoreip whitelist for ANY infra-TAK jail, fleet-uniform:
    localhost + the box's attached private subnet(s) + our own container bridges +
    operator fleet CIDRs + the per-jail operator whitelist (extra). Identical code
    path on every box; dedups so it is idempotent even if `extra` still carries the
    localhost tokens."""
    parts, seen = [], set()
    candidates = ['127.0.0.1/8', '::1']
    candidates += _f2b_local_subnets()
    candidates += _f2b_mgmt_tunnel_subnets()   # never ban the road in
    candidates += _f2b_container_subnets()     # never ban our own services
    candidates += _f2b_own_addresses()         # never ban ourselves
    candidates += _f2b_fleet_ignore_cidrs()
    candidates += str(extra or '').replace(',', ' ').split()
    for c in candidates:
        c = c.strip()
        if c and c not in seen:
            seen.add(c)
            parts.append(c)
    return ' '.join(parts)

def _f2b_operator_extra(stored):
    """Strip the fleet-computed tokens (localhost + attached private subnets + fleet CIDRs)
    from a jail's stored ignoreip, leaving ONLY the per-jail operator entries. Lets a
    re-write re-derive the fleet part fresh each time, so a REMOVED fleet/gateway CIDR
    actually propagates out of every jail instead of staying baked into the stored line."""
    fleet = {'127.0.0.1/8', '::1'}
    fleet.update(_f2b_local_subnets())
    fleet.update(_f2b_mgmt_tunnel_subnets())
    fleet.update(_f2b_container_subnets())
    fleet.update(_f2b_own_addresses())
    fleet.update(_f2b_fleet_ignore_cidrs())
    return ' '.join(t for t in str(stored or '').split() if t not in fleet)

def _f2b_read_jail_config():
    """Read current thresholds and ignoreip from the infratak-authentik jail config file."""
    jail_path = '/etc/fail2ban/jail.d/infratak-authentik.conf'
    cfg = {'maxretry': 5, 'findtime': 600, 'bantime': 3600, 'ignoreip': ''}
    if not os.path.exists(jail_path):
        return cfg
    try:
        with open(jail_path) as _f:
            for line in _f:
                line = line.strip()
                for key in ('maxretry', 'findtime', 'bantime'):
                    if line.startswith(key):
                        try: cfg[key] = int(line.split('=')[1].strip())
                        except Exception: pass
                if line.startswith('ignoreip'):
                    cfg['ignoreip'] = line.split('=', 1)[1].strip()
    except Exception:
        pass
    return cfg

def _f2b_banaction():
    """fail2ban ban action per host firewall family. Debian → 'ufw' (bans the IP on
    ALL traffic). RHEL has no ufw → 'iptables-allports', the all-ports equivalent
    (NOT iptables-multiport — that needs a port list and only blocks specific ports).
    Works on Rocky 9 via nft-backed iptables, with OR without firewalld active
    (firewalld is off on cloud boxes that rely on the security group). The
    infratak-guarddog notify action is appended on top by each jail. (Firewalld-
    native banaction — firewallcmd-* — is part of the broader firewall-parity work.)"""
    return 'iptables-allports' if _distro_family() == 'rhel' else 'ufw'


# MediaMTX / TAK Video Restreamer listeners, from the mediamtx.yml we generate
# (~line 28620) plus the TVR ports in _FW_PORTS. Kept beside the writer that uses
# them so a new listener in the config is an obvious two-line change here too.
_F2B_MEDIA_PORTS_TCP = '1935,8322,8554,8555,8888,8889,8892'  # rtmp, rtsps, rtsp, tvr-rtsp, hls, webrtc, aux
_F2B_MEDIA_PORTS_UDP = '8000,8001,8189,8890'                 # rtp, rtcp, webrtc-ice, srt


def _f2b_banaction_media():
    """Ban action for the mediamtx-rtsp jail ONLY: block the media ports, nothing else.

    Deliberate exception to the fleet-uniform all-ports `_f2b_banaction()`, taken
    2026-08-11 after a field ban (Ryan F., NY) severed an operator's TAK Server
    connection during a live SWAT exercise. `ufw`/`iptables-allports` drop the IP on
    EVERY port, so one strike on a video listener also cuts 8089/8443/8446 and the
    console at 5001 — and `recidive` escalates a repeat to a permanent ban. Video
    abuse must never be able to take away command and control.

    The blast radius that remains is exactly the surface the jail watches. An attacker
    brute-forcing RTSP credentials is stopped from streaming; they are not handed a
    lever on the TAK stack. iptables-multiport is available on both families (it is
    Debian fail2ban's own default banaction, and RHEL already runs the iptables-*
    actions via nft-backed iptables), so this needs no per-family branch.

    Two action instances because one iptables-multiport instance carries a single
    protocol — UDP matters here (SRT 8890, RTP/RTCP, WebRTC ICE), so a TCP-only ban
    would leave a banned publisher still pushing media."""
    return (f'iptables-multiport[name=mediamtx-tcp, port="{_F2B_MEDIA_PORTS_TCP}", protocol=tcp]\n'
            f'         iptables-multiport[name=mediamtx-udp, port="{_F2B_MEDIA_PORTS_UDP}", protocol=udp]')


def _f2b_sshd_logpath():
    """sshd auth log path, or '' when this box has no syslog file to tail.

    Debian → /var/log/auth.log; RHEL → /var/log/secure. BUT plenty of real
    installs have no rsyslog at all — minimal/on-prem install profiles, images
    that strip it, or rsyslog present but disabled — and then neither file
    exists and sshd logs only to the systemd journal. Do NOT assume this is a
    new-distro problem: the field report came from Ubuntu 22.04.5 LTS on-prem,
    which ships rsyslog by default. Never infer the log file from the OS
    version; check whether it is actually there.

    Pointing a jail at a logpath that does not exist makes fail2ban fail during
    CONFIG PARSING, which takes down the ENTIRE daemon — every jail, not just
    sshd, so the box silently ends up with no protection at all:
        ERROR Failed during configuration: Have not found any log file for sshd jail
        ERROR Async configuration of server failed
    Field-reported on a fresh install by an operator (Josh, VA — 2026-07-25),
    who root-caused it correctly and worked around it with `backend = systemd`.
    Our own fleet never hit it because every box happens to run rsyslog.

    Returning '' tells the caller to write `backend = systemd` and NO logpath.
    Checks the other family's path too — the box's reality beats our guess."""
    preferred = '/var/log/secure' if _distro_family() == 'rhel' else '/var/log/auth.log'
    for p in (preferred, '/var/log/auth.log', '/var/log/secure'):
        try:
            if os.path.exists(p):
                return p
        except Exception:
            pass
    return ''


def _f2b_selfheal_sshd_backend(plog=None):
    """Repair an sshd jail pointing at a syslog file this box does not have.

    Field-reported 2026-07-25 on Ubuntu 22.04.5 LTS on-prem: where rsyslog is
    absent or disabled, neither /var/log/auth.log nor /var/log/secure exists,
    sshd logs only to the journal, and a jail carrying
    `logpath = /var/log/auth.log` makes fail2ban abort while PARSING config:
        ERROR Failed during configuration: Have not found any log file for sshd jail
    That kills the whole daemon, so EVERY jail stops — the box looks protected
    and is not. Swap the dead logpath for `backend = systemd`.

    Deliberately narrow: only `[sshd]` jails, and only when the referenced file
    is genuinely missing. Other jails (authentik, takserver) tail real files that
    may legitimately be absent until that module is deployed, and rewriting them
    to the journal would be wrong. Both families, idempotent, no-op when healthy.
    """
    _log = plog or (lambda m: None)
    jaild = '/etc/fail2ban/jail.d'
    if not os.path.isdir(jaild) or not _f2b_is_available():
        return False
    import glob as _glob
    changed = []
    for path in sorted(_glob.glob(os.path.join(jaild, '*.conf'))):
        try:
            with open(path) as f:
                text = f.read()
        except OSError:
            continue
        if '[sshd]' not in text:
            continue
        out, hit = [], False
        for line in text.splitlines(True):
            m = re.match(r'^\s*logpath\s*=\s*(\S+)\s*$', line)
            if m and not os.path.exists(m.group(1)):
                out.append('backend  = systemd\n')   # journal instead of a dead file
                hit = True
            else:
                out.append(line)
        if hit:
            try:
                _write_priv(path, ''.join(out))
                changed.append(os.path.basename(path))
            except Exception as e:
                _log(f"fail2ban self-heal: could not rewrite {path}: {e}")
    if not changed:
        return False
    _log('fail2ban: sshd jail pointed at a syslog file this box does not have '
         '(no rsyslog) — switched to the systemd journal in ' + ', '.join(changed) +
         '. That misconfiguration stops the WHOLE daemon, so no jail was running.')
    try:
        subprocess.run(_sudo_wrap(['systemctl', 'restart', 'fail2ban']),
                       capture_output=True, timeout=60)
        st = subprocess.run(['systemctl', 'is-active', 'fail2ban'],
                            capture_output=True, text=True, timeout=15).stdout.strip()
        _log(f'fail2ban: restarted after self-heal — now {st}')
    except Exception as e:
        _log(f'fail2ban: restart after self-heal failed ({e}) — check `systemctl status fail2ban`')
    return True


# ── Filters infra-TAK owns ────────────────────────────────────────────────────
# SINGLE SOURCE OF TRUTH. Every writer below pulls from here, and
# _f2b_selfheal_filters() repairs a box that is missing one. Distro-shipped
# filters (sshd, recidive) are deliberately absent — we never overwrite those.
#
# Why this exists (found 2026-07-27): jail configs were self-healed at startup
# but filter files were NOT — the only code that wrote them was the one-shot
# Marketplace install path. So a box could end up with `enabled = true` and no
# filter, which makes fail2ban skip the jail on EVERY reload and fail
# `fail2ban-client -t` outright. test6 sat like that from ≥2026-06-29 with
# Authentik brute-force protection silently absent, while the console showed
# the jail as configured. A security control that cannot fire must never be
# reachable by a code path that leaves no trace.
_F2B_OWNED_FILTERS = {
    'authentik': (
        "[Definition]\n"
        "# Read from Authentik's OWN source, 2026-07-27 (authentik 2026.5.x,\n"
        "# authentik/stages/identification/stage.py):\n"
        "#     self.stage.logger.info(\n"
        "#         \"invalid_login\", identifier=uid_field, client_ip=client_ip,\n"
        "#         action=\"invalid_identifier\", ...)\n"
        "# structlog renders the first positional arg as \"event\", so the line is\n"
        "#     {... \"event\":\"invalid_login\" ... \"client_ip\":\"1.2.3.4\" ...}\n"
        "#\n"
        "# The previous filter matched \"action\": \"login_failed\" and never fired once on\n"
        "# any box: that string does not appear in the log at all. `login_failed` is a\n"
        "# Django SIGNAL name (authentik/core/signals.py), not a logged field — it feeds\n"
        "# Authentik's own reputation scoring, not this file.\n"
        "#\n"
        "# REQUIRES AUTHENTIK_LOG_LEVEL=info — the call above is logger.info(), so at\n"
        "# `warning` the line is never emitted and this jail cannot fire.\n"
        "#\n"
        "# Field order is not guaranteed by structlog, so match client_ip in EITHER\n"
        "# direction relative to the event. Both alternatives cannot match the same line\n"
        "# (each requires the other token on the opposite side), so no double-counting.\n"
        "#\n"
        "# SCOPE, deliberately: this catches an unknown/invalid IDENTIFIER — credential\n"
        "# stuffing and username enumeration, the dominant attack. A wrong PASSWORD on a\n"
        "# valid username logs \"Invalid credentials\" with NO client_ip\n"
        "# (stages/password/stage.py), so it is not bannable from the log in this\n"
        "# version. Authentik's built-in reputation policy covers that case natively.\n"
        "failregex = \"event\":\\s*\"invalid_login\".*\"client_ip\":\\s*\"<HOST>\"\n"
        "            \"client_ip\":\\s*\"<HOST>\".*\"event\":\\s*\"invalid_login\"\n"
        "ignoreregex =\n"
        # datepattern is MANDATORY here, not tidiness. Without it fail2ban runs its
        # auto date-detector over Authentik's JSON, which mixes ISO strings with float
        # epochs, and dies with IndexError('string index out of range') on EVERY line
        # — logged as "Failed to process line", so the jail reads the file, matches
        # nothing, and looks perfectly healthy. Confirmed on test8 2026-07-27: auto
        # detect = IndexError and 0 processed; explicit pattern = 13/40 matched.
        "datepattern = \"timestamp\":\\s*\"%%Y-%%m-%%dT%%H:%%M:%%S\n"
    ),
    'takserver': (
        "[Definition]\n"
        "# Match TAK Server (Netty) TLS/SSL/handshake rejection lines.\n"
        "# Covers: PEER_DID_NOT_RETURN_A_CERTIFICATE, NO_SHARED_CIPHER,\n"
        "#         UNSUPPORTED_PROTOCOL, NotSslRecordException.\n"
        "# Log timestamp format: 2026-05-02-15:58:55.145 (YYYY-MM-DD-HH:MM:SS.mmm)\n"
        "failregex = NioNettyServerHandler error.*Remote address: <HOST>;\n"
        "ignoreregex =\n"
        "datepattern = %%Y-%%m-%%d-%%H:%%M:%%S\n"
        "              {^LN-BEG}\n"
    ),
    'takportal': (
        "[Definition]\n"
        "# Reads CADDY's access log for the TAK Portal host (v10.1.11). The Portal's\n"
        "# public, unauthenticated /lookup and /request-access forms are enumerable;\n"
        "# this bans an IP that keeps getting REJECTED on them. Caddy is the edge, so\n"
        "# client_ip is the true client with no X-Forwarded-For trust required.\n"
        "#\n"
        "# Scoped to those two paths ONLY — a 4xx anywhere else on the Portal (an\n"
        "# authenticated page, a missing asset) must never ban anyone. Success (2xx)\n"
        "# and redirects (3xx) are never matched, so normal use cannot accumulate\n"
        "# strikes. 429 is deliberately EXCLUDED: rate-limited callers behind one NAT\n"
        "# would punish a whole site for one noisy user.\n"
        "# \\s* after each colon: Go's encoder emits compact JSON, but tolerating a\n"
        "# space costs nothing and stops a formatting change from silently disarming\n"
        "# this jail — which is exactly how the last two died.\n"
        "failregex = \"client_ip\":\\s*\"<HOST>\".*\"uri\":\\s*\"/(?:lookup|request-access)[^\"]*\".*\"status\":\\s*(?:400|401|403)\\b\n"
        "ignoreregex =\n"
    ),
    'mediamtx-rtsp': (
        "[Definition]\n"
        "# Match MediaMTX AUTHENTICATION FAILURES per source IP.\n"
        "#\n"
        "# v10.1.30 rewrite. The previous filter matched\n"
        "#     \\[RTSP\\] \\[conn <HOST>:\\d+\\] opened\n"
        "# which is a SUCCESS event — every RTSP connection open, regardless of whether\n"
        "# the caller authenticated. At the shipped default (10 opens / 30 s) that bans\n"
        "# any client that legitimately opens several streams at once. Field-hit\n"
        "# 2026-08-11 (Ryan F., NY): a video-wall plugin pulling N tiles = N simultaneous\n"
        "# RTSP opens from one phone, banned mid-operation during a SWAT exercise. Every\n"
        "# other jail we ship matches a FAILURE; this one never did.\n"
        "#\n"
        "# MediaMTX logs a rejected caller on connection close, at INFO:\n"
        "#     [RTSP] [conn 1.2.3.4:5678] closed: authentication failed: ...\n"
        "# The `[s->c] RTSP/1.0 401 Unauthorized` line is emitted at DEBUG only, so it is\n"
        "# NOT usable — our mediamtx.yml runs the default logLevel (info) and a filter\n"
        "# keyed to a debug-only line would silently never fire.\n"
        "#\n"
        "# Protocol-agnostic on purpose: RTMP/SRT/WebRTC publishers log the same\n"
        "# `closed: authentication failed` shape, and a credential-stuffer will try\n"
        "# whichever listener answers. Anchored on the conn/session bracket so an\n"
        "# unrelated line mentioning the phrase cannot match.\n"
        "failregex = \\[conn <HOST>:\\d+\\] closed: .*authentication failed\n"
        "            \\[conn <HOST>:\\d+\\] \\[session [^\\]]+\\] closed: .*authentication failed\n"
        "ignoreregex =\n"
    ),
}


# Filter contents we have SHIPPED in the past and now know to be wrong. A file whose
# bytes exactly match one of these is ours and stale, so it is safe to upgrade. A file
# matching NONE of them has been hand-edited and is never touched.
#
# Why this exists: _f2b_selfheal_filters() originally only created MISSING filters, so
# a corrected filter could never reach a box that already had the broken one — it
# healed test6 (no file) and silently skipped every other box (stale file). Found while
# verifying the Authentik jail end-to-end on test8, 2026-07-27: the jail was loaded,
# fed, and logging invalid_login, and still matched 0 lines because the on-disk filter
# was the old login_failed one.
_F2B_LEGACY_FILTERS = {
    'authentik': [
        # v0.9.0–v10.1.11: matched "action": "login_failed", a string Authentik never
        # logs. login_failed is a Django signal name, not a log field. Never matched once.
        '[Definition]\n'
        '# Match Authentik JSON log lines containing login_failed events.\n'
        '# Authentik emits structured JSON; client_ip contains the real IP since v0.8.9\n'
        '# fixed AUTHENTIK_LISTEN__TRUSTED_PROXY_CIDRS.\n'
        'failregex = "action": "login_failed".*"client_ip": "<HOST>"\n'
        '            "client_ip": "<HOST>".*"action": "login_failed"\n'
        'ignoreregex =\n',
        # v10.1.11 first cut: correct event name, but NO datepattern — fail2ban's auto
        # date-detector threw IndexError on every Authentik JSON line, so it matched
        # nothing while appearing healthy.
        '[Definition]\n# Read from Authentik\'s OWN source, 2026-07-27 (authentik 2026.5.x,\n# authentik/stages/identification/stage.py):\n#     self.stage.logger.info(\n#         "invalid_login", identifier=uid_field, client_ip=client_ip,\n#         action="invalid_identifier", ...)\n# structlog renders the first positional arg as "event", so the line is\n#     {... "event":"invalid_login" ... "client_ip":"1.2.3.4" ...}\n#\n# The previous filter matched "action": "login_failed" and never fired once on\n# any box: that string does not appear in the log at all. `login_failed` is a\n# Django SIGNAL name (authentik/core/signals.py), not a logged field — it feeds\n# Authentik\'s own reputation scoring, not this file.\n#\n# REQUIRES AUTHENTIK_LOG_LEVEL=info — the call above is logger.info(), so at\n# `warning` the line is never emitted and this jail cannot fire.\n#\n# Field order is not guaranteed by structlog, so match client_ip in EITHER\n# direction relative to the event. Both alternatives cannot match the same line\n# (each requires the other token on the opposite side), so no double-counting.\n#\n# SCOPE, deliberately: this catches an unknown/invalid IDENTIFIER — credential\n# stuffing and username enumeration, the dominant attack. A wrong PASSWORD on a\n# valid username logs "Invalid credentials" with NO client_ip\n# (stages/password/stage.py), so it is not bannable from the log in this\n# version. Authentik\'s built-in reputation policy covers that case natively.\nfailregex = "event":\\s*"invalid_login".*"client_ip":\\s*"<HOST>"\n            "client_ip":\\s*"<HOST>".*"event":\\s*"invalid_login"\nignoreregex =\n',
    ],
    'mediamtx-rtsp': [
        # v0.9.x–v10.1.29: matched `opened`, a SUCCESS event, so it counted legitimate
        # stream pulls as strikes. Banned a real operator mid-exercise (2026-08-11).
        # Every box with MediaMTX auto-installed this jail, so the upgrade has to reach
        # them through the self-heal — creating-if-missing would skip all of them.
        "[Definition]\n"
        "# Match RTSP connection opens per source IP.\n"
        "# Counts 'opened' events — catches scanners before their probe cycle completes;\n"
        "# legitimate ATAK clients reconnect occasionally but never at scanner rates.\n"
        "failregex = \\[RTSP\\] \\[conn <HOST>:\\d+\\] opened\n"
        "ignoreregex =\n",
    ],
}


def _f2b_enabled_jail_files():
    """[(jail_name, filter_name, path)] for every enabled infratak-*.conf jail."""
    out = []
    jaild = '/etc/fail2ban/jail.d'
    if not os.path.isdir(jaild):
        return out
    import glob as _glob
    for path in sorted(_glob.glob(os.path.join(jaild, 'infratak-*.conf'))):
        try:
            with open(path) as f:
                text = f.read()
        except OSError:
            continue
        m = re.search(r'^\s*\[([^\]]+)\]', text, re.M)
        if not m:
            continue
        name = m.group(1).strip()
        en = re.search(r'^\s*enabled\s*=\s*(\S+)', text, re.M)
        if not en or en.group(1).strip().lower() not in ('true', 'yes', '1'):
            continue
        fm = re.search(r'^\s*filter\s*=\s*(\S+)', text, re.M)
        out.append((name, fm.group(1).strip() if fm else name, path))
    return out


def _f2b_loaded_jails():
    """Jail names the RUNNING fail2ban actually has. [] if it cannot be asked.

    NOT the same as the jails on disk — that gap is the whole point."""
    try:
        r = subprocess.run(_sudo_wrap(['fail2ban-client', 'status']),
                           capture_output=True, text=True, timeout=30)
        for line in (r.stdout or '').splitlines():
            if 'Jail list:' in line:
                return [j.strip() for j in line.split(':', 1)[1].replace(',', ' ').split() if j.strip()]
    except Exception:
        pass
    return []


# Authentik's log level decides whether the Authentik jail can EVER match, so the
# answer is part of that jail's health — but reading it costs a `docker inspect` plus
# a privileged file read, and /api/fail2ban/status is on a page poll. v10.1.37 already
# had to pull a posture probe off the 5-second metrics poll; this memo keeps the same
# mistake from being made again. TTL is generous because the answer only changes when
# an operator edits .env or this very release heals it.
_F2B_AK_LEVEL_TTL = 300
_F2B_AK_LEVEL_CACHE = {'at': 0.0, 'verdict': None}

# Levels at or below info. `invalid_login` is a logger.info() call, so anything
# coarser than these cannot emit the only failed-login line that carries a client IP.
_F2B_AK_MATCHABLE_LEVELS = ('info', 'debug', 'trace', 'notset')


def _f2b_ak_log_level_verdict(force=False):
    """Can Authentik, as configured, emit a line the Authentik jail could match?

    Returns (ok, level, reason): ok True = yes, False = no, None = cannot tell.

    This is the check that was missing. `fail2ban-client status authentik` reports a
    jail that is loaded, fed and completely inert, because whether the PRODUCER can
    emit a matchable line at all is invisible from fail2ban's side. Field report
    US-FED-NE 2026-08-17: sshd jail banning normally, Authentik jail Active with 0
    hits, log level `warning` — a decorative control the console called protection."""
    now = time.monotonic()
    cached = _F2B_AK_LEVEL_CACHE.get('verdict')
    if cached is not None and not force and (now - _F2B_AK_LEVEL_CACHE['at']) < _F2B_AK_LEVEL_TTL:
        return cached
    ak_dir, env_path, _c = _find_authentik_install_dir()
    if not ak_dir:
        verdict = (None, None, 'Authentik install dir not found (tried the running '
                               'container label, ~/authentik, /opt/authentik)')
    else:
        try:
            content = _read_priv(env_path)
        except Exception as e:
            verdict = (None, None, f'{env_path} could not be read ({str(e)[:80]})')
        else:
            m = re.search(r'^AUTHENTIK_LOG_LEVEL\s*=\s*(\S*)\s*$', content, re.M)
            # Absent = upstream's own default = info = matchable.
            level = (m.group(1).strip().lower() if m and m.group(1).strip() else 'info')
            if level in _F2B_AK_MATCHABLE_LEVELS:
                verdict = (True, level, '')
            else:
                verdict = (False, level,
                           'AUTHENTIK_LOG_LEVEL=%s cannot emit the invalid_login line '
                           'this jail matches (it is a logger.info call), so the jail '
                           'is loaded but can never fire' % level)
    _F2B_AK_LEVEL_CACHE['verdict'] = verdict
    _F2B_AK_LEVEL_CACHE['at'] = now
    return verdict


def _f2b_log_has_rotated_history(logpath):
    """True if this log has ever been written — including into a rotated sibling.

    v10.1.38, caught in T&E. The 0-byte STARVING test was written on the reasoning that
    "a quiet box legitimately has quiet logs, but a log that has never received one byte
    is unambiguous". Daily logrotate with `copytruncate` falsifies that: at 00:00 the
    rule copies auth.log to auth.log.1 and truncates the original to zero, so from
    midnight until the next failed login a perfectly healthy jail has a 0-byte log.
    Measured on test8/test12/aws-arm simultaneously, 2026-08-18 03:04 — all three
    reported STARVING with 1899 bytes sitting in auth.log.1 beside them.

    That was survivable while the verdict only reached a journal line nobody read. This
    release renders dead jails in the console, so without this check every operator would
    get a red "protecting nothing" banner every morning — and a control that cries wolf
    daily is worse than one that says nothing, because it trains people to ignore it.

    A rotated sibling with content proves the writer works. Only a log with no history at
    all is genuinely starving."""
    try:
        d = os.path.dirname(logpath) or '.'
        base = os.path.basename(logpath)
        for f in os.listdir(d):
            if f == base or not f.startswith(base + '.'):
                continue
            suffix = f[len(base) + 1:]
            # rotated siblings only: .1, .2.gz, .1.bz2 ... never .parked-missing-log
            if not re.fullmatch(r'\d+(\.(gz|bz2|xz|zst))?', suffix):
                continue
            try:
                if os.path.getsize(os.path.join(d, f)) > 0:
                    return True
            except OSError:
                continue
    except OSError:
        pass
    return False


def _f2b_dead_jails():
    """Jails that are configured but protecting nothing. [(jail, filter, reason)].

    THREE failure modes, because fixing only the first still leaves a green console
    over a control that cannot fire:

    1. NOT LOADED — enabled on disk but absent from the running daemon, usually a
       missing filter file. (test6/authentik, ≥2026-06-29.)
    2. STARVING — loaded and healthy-looking, but its logpath is 0 bytes, so it has
       never been fed a single line and never can be. (takportal, since 2026-06-12:
       the jail shipped ahead of the TAK Portal writer that was meant to emit the
       log, and the container has no mount for that path either.) A 0-byte file is
       used as the signal rather than staleness — a quiet box legitimately has quiet
       logs, but a log that has never received one byte is unambiguous.
    3. INERT — loaded, and its log is being written, but the PRODUCER cannot emit a
       line this filter could ever match. Modes 1 and 2 both look at fail2ban; this
       one looks at the software on the other end of the log, which is where the
       Authentik jail actually failed in the field (US-FED-NE, 2026-08-17: log level
       `warning`, so `invalid_login` — a logger.info call — was never written, on a
       jail reporting Active). Only Authentik is checked here, because it is the only
       jail whose producer has a config knob that can silently disarm it; the general
       case (does this filter match this log at all?) is roadmapped, not shipped."""
    dead = []
    loaded = _f2b_loaded_jails()
    if not loaded:
        return dead                       # daemon unreachable — cannot judge, don't guess
    for name, filt, path in _f2b_enabled_jail_files():
        if name not in loaded:
            reason = ('filter file /etc/fail2ban/filter.d/%s.conf is missing' % filt
                      if not os.path.exists('/etc/fail2ban/filter.d/%s.conf' % filt)
                      else 'enabled on disk but not loaded by fail2ban')
            dead.append((name, filt, reason))
            continue
        # Loaded — but is anything actually reaching it?
        try:
            with open(path) as f:
                jt = f.read()
        except OSError:
            continue
        if re.search(r'^\s*backend\s*=\s*systemd', jt, re.M):
            continue                      # journal-fed, no logpath to size-check
        lm = re.search(r'^\s*logpath\s*=\s*(\S+)', jt, re.M)
        if not lm:
            continue
        lp = lm.group(1)
        try:
            if os.path.getsize(lp) == 0 and not _f2b_log_has_rotated_history(lp):
                # v10.1.40 — the Authentik jail is NOT covered by the 0-byte rule, and
                # treating it as if it were is a false alarm.
                #
                # The STARVING test assumes "a log that has never received one byte is
                # unambiguous". True for takportal, whose writer emits routine traffic.
                # FALSE here: this feed is
                #     docker logs -f authentik-server-1 | grep -F invalid_login >> auth.log
                # so it writes ONLY when a login actually fails. A healthy box on which
                # nobody has ever mistyped a password has a legitimately 0-byte auth.log
                # and a perfectly armed jail. Reporting that as "protecting nothing" is
                # the same cry-wolf failure the rotated-log carve-out above exists to
                # prevent, and it reached a customer (Charles Laird, NC, v10.1.39).
                #
                # The signal that actually distinguishes the two cases is whether the
                # FORWARDER is running — which the console already computes for its
                # status badge and, until now, never used here.
                if name == 'authentik':
                    try:
                        _fwd = subprocess.run(
                            ['systemctl', 'is-active', 'authentik-log-forwarder'],
                            capture_output=True, text=True, timeout=10
                            ).stdout.strip() == 'active'
                    except Exception:
                        _fwd = None       # inconclusive — do NOT convict on it
                    if _fwd is not False:
                        continue          # feed alive (or unknown): armed, nothing to log yet
                    dead.append((name, filt,
                                 'the Authentik log forwarder (authentik-log-forwarder.'
                                 'service) is not running, so nothing writes %s and this '
                                 'jail has no feed. The console restarts it automatically '
                                 'on startup; to fix it now, toggle the Authentik jail off '
                                 'and on.' % lp))
                    continue
                dead.append((name, filt,
                             'loaded, but its log %s is 0 bytes and has no rotated '
                             'history — nothing has ever written to it, so this jail '
                             'can never fire' % lp))
                continue                  # 0 bytes is the deeper fault; don't double-report
        except OSError:
            dead.append((name, filt, 'loaded, but its log %s cannot be read' % lp))
            continue
        # Mode 3 — the log is being written, but can the producer emit a matchable
        # line at all? Authentik only: see the docstring.
        if name == 'authentik':
            ok, _level, why = _f2b_ak_log_level_verdict()
            if ok is False:
                dead.append((name, filt, why))
            elif ok is None:
                dead.append((name, filt,
                             'loaded, but infra-TAK cannot verify Authentik is able to '
                             'emit a matchable line (%s) — treat this jail as unproven' % why))
    return dead


def _f2b_remove_jail(jail_file, why, plog=None):
    """Delete a jail config and reload fail2ban. For when the thing it guards is gone.

    v10.1.38. Uninstalling a module left its jail behind: test12 still carried
    /etc/fail2ban/jail.d/infratak-mediamtx-rtsp.conf dated Jul 27 with MediaMTX long
    removed. Its `journalmatch=_SYSTEMD_UNIT=mediamtx.service` can never match, so it
    is inert rather than dangerous — but it is a configured-and-dead jail, it lands in
    _f2b_dead_jails() forever, and during v10.1.30 T&E it made a stale ban action look
    like a live one. No-op when the file is absent, so it is safe on every path."""
    _log = plog or (lambda m: None)
    if not _f2b_is_available():
        return False
    # This name is formatted into a path that is `rm -f`d with sudo. Every caller
    # passes a literal today; the guard is so that stays true if one ever doesn't.
    if not re.fullmatch(r'[A-Za-z0-9._-]+\.conf', jail_file or ''):
        _log('fail2ban: refusing to remove jail with unexpected name %r' % (jail_file,))
        return False
    path = '/etc/fail2ban/jail.d/%s' % jail_file
    if not _exists_priv(path):
        return False
    try:
        subprocess.run(_sudo_wrap(['rm', '-f', path]), capture_output=True, timeout=10)
        subprocess.run(_sudo_wrap(['fail2ban-client', 'reload']), capture_output=True, timeout=15)
    except Exception as e:
        _log('fail2ban: could not remove jail %s (%s) — it will keep showing as a dead '
             'jail until it is deleted' % (jail_file, str(e)[:80]))
        return False
    _log('Removed the %s fail2ban jail (%s)' % (jail_file, why))
    return True


# Log files infra-TAK ITSELF produces and one of our jails then reads. These we may
# create: an empty file is harmless (the jail tails it and matches nothing until the
# real writer appends), and its ABSENCE is fatal to the whole daemon.
#
# Everything NOT on this list belongs to another program — TAK Server's log4j owns
# /opt/tak/logs/*, Caddy owns its access logs — and those run as their own
# unprivileged users. Creating one of those root-owned would break the real writer,
# which is the failure `_f2b_prepare_portal_caddy_log()` was written for. A jail
# pointing at a missing FOREIGN log gets parked instead (see below).
_F2B_SELF_OWNED_LOGS = ('/var/log/authentik/auth.log', '/var/log/fail2ban.log')

# Suffix for a jail parked because its logpath does not exist. Parking (rather than
# editing `enabled`) keeps the existence-based _f2b_*_jail_enabled() checks honest,
# so the console reports the jail as off instead of showing a control that is not
# running.
_F2B_PARK_SUFFIX = '.parked-missing-log'


def _f2b_ensure_ak_logfile(plog=None):
    """Create /var/log/authentik/auth.log when it is missing. NEVER truncates.

    The Authentik jail hard-codes `logpath = /var/log/authentik/auth.log`, but the only
    thing that has ever created that file is the append redirect inside
    authentik-log-forwarder.service — and the installer starts that unit ONLY when an
    Authentik container is already running (migration step 6, and the same conditional
    in the jail-toggle route). Set fail2ban up before Authentik is deployed, or during
    a redeploy/upgrade window, and the jail is written pointing at a file nothing will
    ever create. Install only ever made the DIRECTORY.

    fail2ban does not skip such a jail — it aborts config parsing, so the whole daemon
    dies and EVERY jail stops, sshd included. What made this survive so long is that
    `fail2ban-client reload` (what almost all of our code calls) merely logs the bad
    jail and leaves the running daemon up: the box looks healthy for weeks, until a
    reboot or a package upgrade cold-starts fail2ban and it can never come back.

        ERROR Failed during configuration: Have not found any log file for authentik jail
        fail2ban.service: Main process exited, code=exited, status=255/EXCEPTION

    Field report yfdtak-2, 2026-08-06, on v10.1.25 — every jail on that box was down
    and no `systemctl start` would fix it.

    Same guard the other three jails already had, and the one this jail never got:
    sshd falls back to `backend = systemd` (_f2b_sshd_logpath), the portal log is
    created and chowned up front (_f2b_prepare_portal_caddy_log), recidive's
    /var/log/fail2ban.log is touched before the daemon starts."""
    _log = plog or (lambda m: None)
    path = '/var/log/authentik/auth.log'
    if os.path.exists(path):
        return False
    try:
        _makedirs_priv('/var/log/authentik', exist_ok=True)
        subprocess.run(_sudo_wrap(['touch', path]), capture_output=True, timeout=15)
        _chmod_priv(path, 0o640)
    except Exception as e:
        _log(f'fail2ban: could not create {path} (non-fatal): {e}')
        return False
    if not os.path.exists(path):
        _log('fail2ban: %s is STILL missing after create — the Authentik jail will keep '
             'fail2ban from starting. Check the log forwarder.' % path)
        return False
    _log('fail2ban: created the missing %s. The Authentik jail reads it, and a missing '
         'logpath aborts the ENTIRE fail2ban daemon at config parse — not just that '
         'jail — so this box had no fail2ban protection at all after its next restart.'
         % path)
    return True


def _f2b_guard_jail_logpaths(plog=None):
    """One jail's missing logpath must never take down every jail. Enforce that.

    Runs before anything (re)starts fail2ban, over every enabled infratak-* jail:

      1. RE-ARM first — a jail parked by an earlier pass whose log now exists comes
         back. Without this the guard would be a one-way door: install TAK Server the
         day after the takserver jail got parked and it would stay parked forever.
      2. CREATE the logs we own (_F2B_SELF_OWNED_LOGS), plus the portal access log via
         its owner-aware helper — Caddy must be able to write it, so it cannot just be
         touched root-owned.
      3. PARK what is left — a jail whose logpath belongs to another program and does
         not exist. Renaming it aside costs that ONE jail; leaving it costs all of
         them, because the daemon refuses to start at all. Real case: the takserver
         jail on a split-box deploy, where TAK Server runs on the other server and
         /opt/tak/logs/ does not exist here.
      4. RESTART a daemon that is down, once, and report what state it reached.

    Jails with `backend = systemd` are skipped — they read the journal and have no
    logpath to lose (mediamtx, and sshd on a box with no rsyslog).

    Parking is deliberately louder than it is clever: it logs the jail, the path, and
    the reason, and _f2b_dead_jails() keeps reporting the gap, so a parked jail shows
    up as missing protection instead of quietly passing as configured."""
    _log = plog or (lambda m: None)
    if not _f2b_is_available():
        return False
    jaild = '/etc/fail2ban/jail.d'
    if not os.path.isdir(jaild):
        return False
    import glob as _glob
    changed = False

    # ── 1. Re-arm jails whose log has come back ───────────────────────────────
    for parked in sorted(_glob.glob(os.path.join(jaild, 'infratak-*.conf' + _F2B_PARK_SUFFIX))):
        try:
            with open(parked) as f:
                text = f.read()
        except OSError:
            continue
        m = re.search(r'^\s*logpath\s*=\s*(\S+)', text, re.M)
        if not m or not os.path.exists(m.group(1)):
            continue
        live = parked[:-len(_F2B_PARK_SUFFIX)]
        try:
            subprocess.run(_sudo_wrap(['mv', parked, live]), capture_output=True, timeout=15)
            if os.path.exists(live):
                changed = True
                _log('fail2ban: re-armed %s — its log %s exists again.'
                     % (os.path.basename(live), m.group(1)))
        except Exception as e:
            _log(f'fail2ban: could not re-arm {os.path.basename(parked)} (non-fatal): {e}')

    # ── 2/3. Create what we own, park what we do not ──────────────────────────
    for name, filt, jpath in _f2b_enabled_jail_files():
        try:
            with open(jpath) as f:
                jt = f.read()
        except OSError:
            continue
        if re.search(r'^\s*backend\s*=\s*systemd', jt, re.M):
            continue                      # journal-fed — no logpath to lose
        lm = re.search(r'^\s*logpath\s*=\s*(\S+)', jt, re.M)
        if not lm:
            continue
        lp = lm.group(1)
        if os.path.exists(lp):
            continue
        # fail2ban accepts a GLOB as logpath. None of our jails ship one, but an
        # operator-edited jail may, and os.path.exists() is always False for a glob —
        # which would park a jail that is working perfectly. Never park a pattern:
        # act only on literal paths, where "missing" is unambiguous.
        if any(ch in lp for ch in '*?['):
            continue
        # Ours to create?
        if lp == '/var/log/authentik/auth.log':
            changed |= bool(_f2b_ensure_ak_logfile(_log))
        elif lp in _F2B_SELF_OWNED_LOGS:
            try:
                _makedirs_priv(os.path.dirname(lp), exist_ok=True)
                subprocess.run(_sudo_wrap(['touch', lp]), capture_output=True, timeout=15)
                _chmod_priv(lp, 0o640)
                if os.path.exists(lp):
                    changed = True
                    _log('fail2ban: created the missing %s that the %s jail reads — its '
                         'absence stops the whole daemon.' % (lp, name))
            except Exception as e:
                _log(f'fail2ban: could not create {lp} (non-fatal): {e}')
        elif lp == TAKPORTAL_CADDY_LOG:
            try:
                _f2b_prepare_portal_caddy_log()   # owner-aware: Caddy must write it
            except Exception:
                pass
        if os.path.exists(lp):
            continue
        # Not ours, still missing → park this jail so the others can run.
        try:
            subprocess.run(_sudo_wrap(['mv', jpath, jpath + _F2B_PARK_SUFFIX]),
                           capture_output=True, timeout=15)
            if not os.path.exists(jpath):
                changed = True
                _log('fail2ban: PARKED the %s jail — its logpath %s does not exist on '
                     'this box, and fail2ban aborts the ENTIRE daemon over one missing '
                     'log file. That jail is now off (it was never able to run); every '
                     'other jail keeps working. It re-arms automatically once %s '
                     'appears.' % (name, lp, lp))
        except Exception as e:
            _log(f'fail2ban: could not park {os.path.basename(jpath)} (non-fatal): {e}')

    if not changed:
        return False

    # ── 4. Bring the daemon back ──────────────────────────────────────────────
    try:
        act = subprocess.run(_sudo_wrap(['systemctl', 'is-active', 'fail2ban']),
                             capture_output=True, text=True, timeout=15).stdout.strip()
        if act == 'active':
            subprocess.run(_sudo_wrap(['fail2ban-client', 'reload']), capture_output=True, timeout=60)
            _log('fail2ban: reloaded after logpath repair.')
        else:
            subprocess.run(_sudo_wrap(['systemctl', 'restart', 'fail2ban']),
                           capture_output=True, timeout=60)
            now = subprocess.run(_sudo_wrap(['systemctl', 'is-active', 'fail2ban']),
                                 capture_output=True, text=True, timeout=15).stdout.strip()
            if now == 'active':
                _log('fail2ban: was %s and is now ACTIVE after the logpath repair — jails '
                     'are protecting this box again.' % (act or 'not running'))
            else:
                _log('fail2ban: still %s after the logpath repair — something else is '
                     'wrong; check `systemctl status fail2ban`.' % (now or 'not running'))
    except Exception as e:
        _log(f'fail2ban: restart after logpath repair failed ({e}) — check '
             '`systemctl status fail2ban`')
    return True


def _f2b_selfheal_filters(plog=None):
    """Write any MISSING filter file for an enabled jail whose filter we own.

    A jail with no filter is skipped by fail2ban on every reload and makes
    `fail2ban-client -t` fail for the whole daemon. Console-path delivery: runs at
    startup so a normal update repairs it with no SSH.

    Writes in exactly two cases: the file is MISSING, or its bytes exactly match a
    version WE shipped and have since corrected (_F2B_LEGACY_FILTERS). Anything else
    is operator-modified and is left alone. Creating-only was not enough — a corrected
    filter then never reached any box that already had the broken one."""
    _log = plog or (lambda m: None)
    if not _f2b_is_available():
        return False
    _makedirs_priv('/etc/fail2ban/filter.d', exist_ok=True)
    wrote, upgraded = [], []
    for name, filt, _path in _f2b_enabled_jail_files():
        if filt not in _F2B_OWNED_FILTERS:
            continue                      # distro filter (sshd/recidive) — not ours to write
        fpath = '/etc/fail2ban/filter.d/%s.conf' % filt
        want = _F2B_OWNED_FILTERS[filt]
        cur = None
        if os.path.exists(fpath):
            try:
                with open(fpath) as f:
                    cur = f.read()
            except OSError:
                continue
            if cur == want:
                continue                  # already current
            if cur not in _F2B_LEGACY_FILTERS.get(filt, []):
                continue                  # operator-modified — never clobber
        try:
            _write_priv(fpath, want)
            (upgraded if cur is not None else wrote).append(f'{filt} (jail {name})')
        except Exception as e:
            _log(f'fail2ban: could not write filter {fpath}: {e}')
    if not wrote and not upgraded:
        return False
    if wrote:
        _log('fail2ban: wrote MISSING filter(s) ' + ', '.join(wrote) +
             ' — those jails were enabled but skipped on every reload, so they were '
             'protecting nothing.')
    if upgraded:
        _log('fail2ban: UPGRADED stale filter(s) ' + ', '.join(upgraded) +
             ' — the shipped pattern could never match a real log line, so those jails '
             'were loaded and healthy-looking while banning nobody.')
    try:
        subprocess.run(_sudo_wrap(['fail2ban-client', 'reload']), capture_output=True, timeout=60)
    except Exception:
        pass
    return True


# The forwarder that feeds the Authentik jail. `docker logs -f X 2>&1 >> FILE` is
# WRONG: bash applies redirections left to right, so `2>&1` points stderr at the
# CURRENT stdout (systemd's StandardOutput=null) and only then does `>>` move stdout
# to the file. Net effect: stderr is discarded. Authentik writes its structured JSON
# — including every auth event — to stderr, so the jail was fed nothing but the
# entrypoint's stdout chatter (Django migration output). Measured on test8
# 2026-07-27: 192 of the last 200 stderr lines were JSON; stdout was
# "No migrations to apply." Correct order is `>> FILE 2>&1`.
# `2>&1 |` (before the pipe) sends BOTH streams to grep — Authentik's JSON is on stderr.
#
# The grep is not an optimisation, it is what makes the jail work at all. auth.log's only
# consumer is this jail, and feeding it the full firehose broke fail2ban outright: its
# auto date-detector hits Authentik's mixed timestamp formats (ISO strings, float epochs,
# and bare text from the Django entrypoint) and throws
# IndexError('string index out of range') on EVERY line — logged as "Failed to process
# line", so the jail tails the file, matches nothing, and looks perfectly healthy.
# Confirmed on test8 2026-07-27: full log = IndexError and nothing processed; a file of
# only invalid_login lines = 5/5 matched, clean.
#
# Narrowing here also fixes the second problem it caused: auth.log had grown to 21MB of
# migration chatter with no rotation. Nothing is lost — `docker logs` still holds the
# complete stream for humans.
_AK_FORWARDER_EXEC = ("ExecStart=/bin/bash -c 'docker logs -f authentik-server-1 2>&1 "
                      "| grep --line-buffered -F invalid_login "
                      ">> /var/log/authentik/auth.log'\n")

# v10.1.40 marker. Bump this string whenever the unit body changes so
# _f2b_selfheal_ak_forwarder() can recognise an out-of-date unit without having to
# enumerate every broken generation that ever shipped.
_AK_FORWARDER_MARK = '# infratak-forwarder-rev2'

_AK_FORWARDER_UNIT = (
    "[Unit]\n"
    f"{_AK_FORWARDER_MARK}\n"
    "Description=Authentik Docker Log Forwarder for fail2ban\n"
    "After=docker.service\n"
    # v10.1.40: Wants=, NOT Requires=. With Requires= a docker.service restart STOPS
    # this unit and never brings it back — and dockerd restarts on any OS update that
    # upgrades docker-ce, which is routine. Field: Charles Laird (NC, yfdtak.com) on
    # v10.1.39 showed "Log Forwarder Stopped" with a 0-byte auth.log and a red
    # "protecting nothing" banner; the jail was fine, its feed was dead. Wants= keeps
    # the ordering without the stop-propagation, and Restart=always then reattaches
    # once `docker logs -f` exits with the bounced container.
    "Wants=docker.service\n"
    # Never give up permanently. Without this, a burst of fast exits (docker socket not
    # ready at boot, container not yet created) can trip systemd's default start-rate
    # limit and leave the unit failed until a human intervenes — which is exactly the
    # state this feed must never reach, because nothing else writes auth.log.
    "StartLimitIntervalSec=0\n\n"
    "[Service]\n"
    "Type=simple\n"
    "Restart=always\n"
    "RestartSec=10\n"
    + _AK_FORWARDER_EXEC +
    "StandardOutput=null\n"
    "StandardError=null\n\n"
    "[Install]\n"
    "WantedBy=multi-user.target\n"
)


def _f2b_selfheal_authentik_log_level(plog=None, detail=None):
    """Flip AUTHENTIK_LOG_LEVEL warning -> info so the Authentik jail can actually fire.

    The only failed-login line carrying a client IP is
    `logger.info("invalid_login", ..., client_ip=...)`
    (authentik/stages/identification/stage.py). We set `warning` in v0.8.7 to trim log
    volume, not realising it silently disabled the whole jail — which is why that jail
    has never banned anything on any box. `info` is upstream's OWN default, and volume
    is now bounded by _f2b_ensure_authentik_logrotate().

    Narrow on purpose:
      - only when the Authentik jail is actually enabled (no jail, no reason to touch
        a working Authentik),
      - only when the value is exactly `warning`, i.e. OUR old default. An operator who
        deliberately chose `debug`/`error` keeps it,
      - recreates Authentik so the change takes effect. Skipping that would leave the
        setting written and the jail still dead, which is the exact failure this whole
        release is about. Costs one brief SSO interruption, ONCE.

    v10.1.38 — every exit now says why. This function shipped in v10.1.11 and ran on
    every console start for seven releases while doing NOTHING on an entire class of
    box, because each of its five give-up paths was a bare `return False`. Reported
    from the field (US-FED-NE, 2026-08-17) on a box whose Authentik jail read `Active`
    with AUTHENTIK_LOG_LEVEL=warning: /root is mode 700, the console runs as `takwerx`,
    so `os.path.exists('/root/authentik/.env')` was False and the heal declined without
    a word. A self-heal that cannot heal must be as loud as a jail that cannot fire —
    the same rule _f2b_dead_jails() already applies one screen below."""
    _log = plog or (lambda m: None)
    if not _f2b_authentik_jail_enabled():
        return False                      # no jail: nothing to arm, and not a fault
    ak_dir, env_path, _compose = _find_authentik_install_dir()
    if not ak_dir:
        _log('fail2ban: cannot locate the Authentik install dir (tried the running '
             'container label, ~/authentik, /opt/authentik) — the Authentik jail is '
             'enabled but its log level cannot be verified. If Authentik IS installed '
             'here, this jail is protecting nothing.')
        return False
    try:
        content = _read_priv(env_path)
    except Exception as e:
        _log(f'fail2ban: cannot read {env_path} ({e}) — the Authentik jail is enabled '
             'but its log level cannot be verified, so it may be protecting nothing.')
        return False
    m = re.search(r'^AUTHENTIK_LOG_LEVEL\s*=\s*(\S*)\s*$', content, re.M)
    if not m:
        # Absent = upstream default = info = the jail can fire. Nothing to do.
        return False
    cur = m.group(1).strip().lower()
    if cur != 'warning':
        if cur not in ('info', 'debug', 'trace'):
            # An operator-chosen level ABOVE info. Deliberate, so it is preserved --
            # but invalid_login is a logger.info() call, so the jail cannot fire and
            # the operator has to be told rather than left with a decorative control.
            _log(f'fail2ban: AUTHENTIK_LOG_LEVEL={cur} in {env_path} — kept (operator '
                 'choice, not our old default), but the Authentik jail matches '
                 'logger.info("invalid_login") and therefore CANNOT FIRE at this level. '
                 'Set it to info to arm the jail, or disable the jail so the console '
                 'stops reporting protection that is not there.')
        return False
    new = re.sub(r'^AUTHENTIK_LOG_LEVEL\s*=.*$', 'AUTHENTIK_LOG_LEVEL=info', content, count=1, flags=re.M)
    try:
        _write_priv(env_path, new)
    except Exception as e:
        _log(f'fail2ban: could not raise AUTHENTIK_LOG_LEVEL (non-fatal): {e}')
        return False
    # The INERT verdict is memoised for 300 s to keep docker inspect off the page
    # poll. Nothing invalidated it here, so for up to five minutes after the heal
    # repaired the level the console kept rendering "Enabled, but protecting
    # nothing" over a jail that was already fine — the operator fixes it and the
    # console calls them a liar. Same cry-wolf class as the logrotate false alarm;
    # a stale cache is just a slower way to say something untrue.
    _F2B_AK_LEVEL_CACHE['verdict'] = None
    _F2B_AK_LEVEL_CACHE['at'] = 0.0
    # Name the file. The bug this release fixes was the heal reading the WRONG .env
    # (or none at all), so "it healed" is not a useful log line without the path —
    # on a box with a stale second copy, that path is the whole diagnosis.
    _log('fail2ban: AUTHENTIK_LOG_LEVEL warning -> info in %s. The Authentik '
         'brute-force jail matches logger.info("invalid_login"), so at `warning` it '
         'could never fire — and never had. Applying to the running Authentik.' % env_path)
    # v10.1.38 — report what ACTUALLY happened, not what we intended.
    #
    # This previously announced "Recreating Authentik; brief SSO interruption, once"
    # unconditionally. But `compose up -d` only recreates when the resolved config
    # changed: if the container is already running at the target level (the file drifted
    # but the process did not), it is a no-op and there is no interruption. Measured on
    # test12 2026-08-18 — toast claimed a recreate while the container showed Up 12 hours.
    # Claiming an outage that did not happen is the same class of fault as claiming
    # protection that is not there; this release does not get to do one while fixing the
    # other. The container ID before/after is the only honest test.
    before = _ak_server_container_id()
    ok = True
    try:
        with _authentik_compose_lock('fail2ban-loglevel', plog=_log) as _locked:  # v10.1.55 W3
            if not _locked:
                raise RuntimeError('another healer holds the Authentik compose lock')
            r = subprocess.run(_sudo_wrap(['docker', 'compose', 'up', '-d']), cwd=ak_dir,
                               capture_output=True, text=True, timeout=300)
        if r.returncode != 0:
            ok = False
            _log('fail2ban: Authentik apply returned %s — the new log level takes effect at '
                 'its next restart; jail stays dormant until then.'
                 % (r.stderr or r.stdout or '')[-160:].strip())
    except Exception as e:
        ok = False
        _log(f'fail2ban: Authentik apply failed ({e}) — new log level applies on next restart.')
    recreated = bool(ok and before and _ak_server_container_id() != before)
    if ok:
        _log('fail2ban: Authentik %s.'
             % ('recreated — one brief SSO interruption' if recreated
                else 'was already running at that level; nothing restarted'))
    if isinstance(detail, dict):
        detail.update({'env_path': env_path, 'recreated': recreated, 'applied': ok})
    return True


# Hard ceiling for /var/log/authentik/auth.log. Same number as the `maxsize 50M` in
# the logrotate rule below, so both mechanisms converge on the same operational state.
_F2B_AK_LOG_MAX_BYTES = 50 * 1024 * 1024


def _f2b_bound_ak_logfile(plog=None):
    """Cap auth.log from the console, because logrotate CANNOT be installed on a
    non-root box — and never has been.

    `_f2b_ensure_authentik_logrotate()` writes /etc/logrotate.d/infratak-authentik.
    That prefix is not on the broker's allow-list, so on every non-root box the write is
    denied and the rule has simply never existed. Measured 2026-08-06: test6 (non-root)
    sat at 25 MB with no rotation of any kind, and nuc logs the denial at every boot —
    `broker write denied (/etc/logrotate.d/infratak-authentik): path not in allow-list`.
    The v10.1.11 release believed it had fitted a drain before turning up the tap; on
    the non-root half of the fleet it had not.

    **Widening the broker is NOT the fix.** logrotate executes `prerotate`/`postrotate`
    blocks as root, so write access to /etc/logrotate.d/ is a console->root escalation
    primitive — precisely what the broker exists to prevent. Same reasoning that kept
    /etc/tmpfiles.d/ off the list. The ceiling is enforced here instead, using verbs the
    console already holds. Mechanism differs by box; the outcome does not — a root box
    rotates and keeps 7 days, a non-root box hard-truncates at the same 50 MB, and
    neither can grow without bound.

    TRUNCATION, not deletion or rename, is required. The forwarder is a long-lived
    `docker logs -f ... >> auth.log` holding an open append fd. Every write path here
    opens O_TRUNC on the SAME inode — broker `_do_write()`, root `open(path,'w')`,
    legacy `sudo tee` — so the fd stays valid and the forwarder keeps appending at the
    new EOF. Rename-and-create would leave it writing to an unlinked inode forever and
    the jail would starve silently, which is the failure the logrotate rule's
    `copytruncate` was chosen to avoid. Nothing of value is lost: this file is the
    jail's private feed and `docker logs` still holds the complete stream.

    (`truncate -s 0` is deliberately not used — that binary is not on the broker's exec
    allow-list, which is also why the existing call in `_f2b_selfheal_ak_forwarder()` is
    a silent no-op on non-root boxes.)"""
    _log = plog or (lambda m: None)
    path = '/var/log/authentik/auth.log'
    try:
        size = os.path.getsize(path)
    except OSError:
        return False
    if size <= _F2B_AK_LOG_MAX_BYTES:
        return False
    try:
        _write_priv(path, '', perm=0o640)
    except Exception as e:
        _log('fail2ban: could not cap %s (non-fatal): %s' % (path, e))
        return False
    _log('fail2ban: %s had grown to %.1f MB unrotated, so the console truncated it in '
         'place (same inode — the forwarder keeps appending, the jail reads from the new '
         'EOF, and the full stream is still in `docker logs`). logrotate cannot be '
         'installed on this box: /etc/logrotate.d/ is off the broker allow-list by '
         'design, because logrotate runs postrotate scripts as root.'
         % (path, size / 1048576.0))
    return True


def _f2b_ensure_authentik_logrotate(plog=None):
    """Bound /var/log/authentik/auth.log. It has NEVER been rotated.

    Found at 21MB and growing on test8 (2026-07-27) with no logrotate rule anywhere
    — and the stderr-redirect fix in this same release makes it grow FASTER, because
    the file now receives the JSON stream it was always supposed to. Unbounded is a
    disk-exhaustion path on a long-lived box, so the fix ships with its own brake.

    `copytruncate` is REQUIRED, not stylistic: the writer is
    `docker logs -f ... >> auth.log`, a long-lived process holding an open fd. A
    rename-and-create rotation would leave it writing to the unlinked inode forever
    and the jail would silently starve — the exact class of bug this release is
    about. copytruncate keeps the fd valid; fail2ban handles truncation natively."""
    _log = plog or (lambda m: None)
    if not os.path.isdir('/etc/logrotate.d'):
        return False
    path = '/etc/logrotate.d/infratak-authentik'
    if _priv_write_denied_by_design(path):
        # Don't ask for what is refused by design. _f2b_bound_ak_logfile() already
        # enforces the same ceiling from the console, so the log stays bounded —
        # this is a no-op with a reason, not a degraded state.
        _log('fail2ban: logrotate rule not installed — /etc/logrotate.d/ is off the '
             'broker allow-list by design (postrotate runs as root). The console '
             'enforces the same %d MB ceiling on auth.log directly.'
             % (_F2B_AK_LOG_MAX_BYTES // (1024 * 1024)))
        return False
    conf = (
        "# infra-TAK v10.1.11 — auth.log feeds the Authentik fail2ban jail and was\n"
        "# previously unrotated. copytruncate: the docker-logs forwarder holds the fd.\n"
        "/var/log/authentik/auth.log {\n"
        "    daily\n"
        "    rotate 7\n"
        "    maxsize 50M\n"
        "    copytruncate\n"
        "    compress\n"
        "    delaycompress\n"
        "    missingok\n"
        "    notifempty\n"
        "    su root root\n"
        "}\n"
    )
    try:
        if os.path.exists(path):
            with open(path) as f:
                if f.read() == conf:
                    return False          # already correct
        _write_priv(path, conf)
        _chmod_priv(path, 0o644)          # logrotate refuses group/world-writable files
        _log('fail2ban: added logrotate for /var/log/authentik/auth.log — it had no '
             'rotation at all and was growing without bound.')
        return True
    except Exception as e:
        # Expected on every non-root box: /etc/logrotate.d/ is off the broker allow-list
        # by design (postrotate runs as root). _f2b_bound_ak_logfile() enforces the same
        # 50 MB ceiling from the console, so the log is still bounded.
        _log('fail2ban: logrotate rule not installed (%s). Expected on a non-root box — '
             'the console enforces the same %d MB ceiling directly instead.'
             % (str(e)[:120], _F2B_AK_LOG_MAX_BYTES // (1024 * 1024)))
        return False


def _f2b_start_ak_forwarder(plog=None):
    """Start authentik-log-forwarder.service and REPORT whether it actually started.

    v10.1.40. Every previous start site did a bare
        systemctl enable --now authentik-log-forwarder
    with capture_output=True and no return-code check. Two ways that lies:

    1. A unit in `failed` state that has tripped systemd's start rate limit refuses
       every start with "start request repeated too quickly" until someone runs
       `reset-failed`. Nothing in the codebase ever did. This is why toggling the
       Authentik jail off and on did NOT recover Charles Laird's box (NC, v10.1.39) —
       the console ran the start, systemd declined, the return code was discarded, and
       the UI reported "log forwarder started" over a forwarder that was still dead.
    2. Even without the rate limit, a start that fails for any other reason was
       invisible for the same reason.

    So: clear the failed state first, start, then VERIFY with is-active and hand the
    caller the truth. Returns (ok: bool, msg: str)."""
    _log = plog or (lambda m: None)
    try:
        # Harmless when the unit is not failed; the whole point is that we cannot know.
        subprocess.run(_sudo_wrap(['systemctl', 'reset-failed', 'authentik-log-forwarder']),
                       capture_output=True, timeout=20)
    except Exception:
        pass
    try:
        r = subprocess.run(_sudo_wrap(['systemctl', 'enable', '--now',
                                       'authentik-log-forwarder']),
                           capture_output=True, text=True, timeout=40)
    except Exception as e:
        _log(f'fail2ban: could not start the Authentik log forwarder: {e}')
        return (False, f'log forwarder start failed: {str(e)[:120]}')
    # Never trust rc alone here — verify the daemon agrees it is running.
    try:
        active = subprocess.run(['systemctl', 'is-active', 'authentik-log-forwarder'],
                                capture_output=True, text=True, timeout=15
                                ).stdout.strip() == 'active'
    except Exception:
        active = False
    if active:
        return (True, 'log forwarder started')
    err = ((r.stderr or r.stdout or '').strip() or 'no error reported')[:200]
    _log(f'fail2ban: the Authentik log forwarder did NOT start — {err}')
    return (False, f'log forwarder FAILED to start: {err}')


def _f2b_selfheal_ak_forwarder(plog=None):
    """Bring the Authentik log forwarder up to the current, working definition.

    Two generations of this unit were broken and BOTH are still out there, because the
    unit was only ever written when absent — a box that received a broken one kept it
    forever:
      1. `docker logs -f X 2>&1 >> FILE` with StandardError=null. Bash applies
         redirections left to right, so stderr went to null — and stderr is exactly
         where Authentik writes its JSON. The jail was fed stdout chatter only.
      2. The un-narrowed fix for (1): correct streams, but the whole firehose. That
         crashes fail2ban's date detector on every line (see _AK_FORWARDER_EXEC), so
         the jail still matched nothing while looking healthy.

    Trigger is the absence of the `invalid_login` grep, which only the current
    definition has — that identifies both broken generations without trying to
    enumerate them, and leaves a genuinely hand-edited unit that already narrows the
    stream alone."""
    _log = plog or (lambda m: None)
    svc_path = '/etc/systemd/system/authentik-log-forwarder.service'
    if not os.path.exists(svc_path):
        return False
    try:
        with open(svc_path) as f:
            cur = f.read()
    except OSError:
        return False
    # v10.1.40: two independent conditions now.
    #   (a) the unit body is out of date — either of the two broken generations above,
    #       or the pre-rev2 unit whose `Requires=docker.service` made a dockerd restart
    #       stop the forwarder for good.
    #   (b) the unit is fine but NOT RUNNING. That is the state Charles Laird's box was
    #       in on v10.1.39: correct unit, dead feed, 0-byte auth.log, and a red banner
    #       blaming the jail. Nothing in the console ever restarted it — the page could
    #       SEE it (it renders a "Log Forwarder Stopped" badge from `forwarder_active`)
    #       but no code acted on it, and there was no button to press.
    _stale = ('invalid_login' not in cur) or (_AK_FORWARDER_MARK not in cur)
    if not _stale:
        # Body is current — but is it actually running? Only worth starting when the
        # jail is on and Authentik is up; otherwise a stopped forwarder is correct.
        try:
            _active = subprocess.run(['systemctl', 'is-active', 'authentik-log-forwarder'],
                                     capture_output=True, text=True, timeout=10
                                     ).stdout.strip() == 'active'
        except Exception:
            return False
        if _active:
            return False
        if not _f2b_authentik_jail_enabled():
            return False
        try:
            _ak_up = 'authentik' in subprocess.run(
                _sudo_wrap(['docker', 'ps', '--format', '{{.Names}}']),
                capture_output=True, text=True, timeout=20).stdout
        except Exception:
            return False
        if not _ak_up:
            return False                  # Authentik down: nothing to forward yet
        _ok, _m = _f2b_start_ak_forwarder(plog)
        if not _ok:
            return False
        _log('fail2ban: the Authentik log forwarder was stopped while its jail was '
             'enabled — restarted it. Nothing writes /var/log/authentik/auth.log while '
             'it is down, so the jail had no feed. A dockerd restart (any OS update '
             'that upgrades docker-ce) is the usual cause on units predating v10.1.40.')
        return True
    try:
        _write_priv(svc_path, _AK_FORWARDER_UNIT)
    except Exception as e:
        _log(f'fail2ban: could not repair the Authentik log forwarder: {e}')
        return False
    # The old unit appended the firehose; leftover chatter would keep crashing the date
    # detector on the lines already in the file. Truncate so the jail starts clean —
    # safe because this file is the jail's private feed, not an audit record, and the
    # full stream remains in `docker logs`.
    try:
        # v10.1.40: was `truncate -s 0`, which the broker DENIES on every non-root box
        # ("binary not in allow-list: truncate") — and the failure was swallowed, so the
        # rewrite path believed it had cleared the file for eight releases. /var/log/ is
        # already a broker write prefix, so an empty write does the same job through a
        # path that is actually permitted, on root and non-root alike.
        _write_priv('/var/log/authentik/auth.log', '')
    except Exception as _tr_e:
        _log(f'fail2ban: could not clear auth.log after the forwarder rebuild: {_tr_e}')
    try:
        subprocess.run(_sudo_wrap(['systemctl', 'daemon-reload']), capture_output=True, timeout=30)
        # v10.1.40: clear any failed/rate-limited state, or the restart is refused.
        subprocess.run(_sudo_wrap(['systemctl', 'reset-failed', 'authentik-log-forwarder']),
                       capture_output=True, timeout=20)
        subprocess.run(_sudo_wrap(['systemctl', 'restart', 'authentik-log-forwarder']),
                       capture_output=True, timeout=30)
        subprocess.run(_sudo_wrap(['fail2ban-client', 'reload']), capture_output=True, timeout=60)
    except Exception:
        pass
    _log('fail2ban: rebuilt the Authentik log forwarder — it now captures stderr (where '
         'Authentik logs auth events) and forwards ONLY invalid_login lines. The full '
         'stream was crashing fail2ban\'s date detector on every line, so the jail read '
         'the file and matched nothing.')
    return True


def _f2b_selfheal_portal_caddy_log(plog=None):
    """Repoint the takportal jail at Caddy's access log, and make Caddy emit it.

    The jail shipped in 2026-06 reading /var/log/tak-portal/lookup.log, a file the
    TAK Portal was meant to write and never did — so it has sat loaded and starving
    ever since while /lookup and /request-access stayed public. TAK-Portal is a
    third-party repo, so we feed the jail from the log Caddy already produces.

    Two halves, both idempotent:
      1. Caddyfile — regenerate so the Portal site block gains its `log` block.
         Only when the Portal is installed AND the block is absent. Reload (not
         restart) so a bad config is REFUSED and the running Caddy is untouched.
      2. Jail — rewrite logpath/maxretry, preserving operator thresholds.

    Deliberately does nothing on a box with no TAK Portal."""
    _log = plog or (lambda m: None)
    if not _f2b_is_available():
        return False
    if not _f2b_portal_jail_enabled():
        return False                      # no portal jail on this box — nothing to do
    changed = False

    # ── 1. Make Caddy emit the log ────────────────────────────────────────────
    # Ownership FIRST, unconditionally: a root-owned logfile makes Caddy reject the
    # entire config, which only shows up as a dead Caddy at the next restart. Repair
    # it even when the Caddyfile already looks right — "the file says so" is not
    # evidence Caddy accepted it, and on the 2026-07-27 rollout it had not.
    try:
        _f2b_prepare_portal_caddy_log()
    except Exception:
        pass
    try:
        if os.path.exists(CADDYFILE_PATH):
            with open(CADDYFILE_PATH) as f:
                live = f.read()
            generated = live.split(CADDYFILE_USER_BLOCKS_MARKER, 1)[0]
            if TAKPORTAL_CADDY_LOG not in generated:
                generate_caddyfile()
            # Always reload and CHECK, even if the block was already on disk — the
            # running Caddy may have refused it. reload (never restart) leaves the
            # previous config serving if it is refused again.
            # restart_on_error=False keeps the promise the comment above makes: a refused
            # config must leave the RUNNING Caddy untouched. A restart would read the same
            # bad file and take the edge down entirely.
            rl_ok, rl_detail = _caddy_reload_checked(timeout=60, restart_on_error=False)
            if not rl_ok:
                _log('fail2ban: Caddy REFUSED the config carrying the portal access log '
                     '(%s). The running config is untouched, but the ON-DISK Caddyfile is '
                     'now unloadable — Caddy would fail to start on reboot. Portal jail '
                     'left on its old logpath.'
                     % rl_detail[-200:].strip())
                return False          # do NOT repoint the jail at a log nothing writes
            _log('fail2ban: Caddy accepted the portal access log %s — the takportal jail '
                 'finally has something to read.' % TAKPORTAL_CADDY_LOG)
            changed = True
    except Exception as e:
        _log(f'fail2ban: portal access-log setup failed (non-fatal): {e}')
        return False

    # ── 2. Repoint the jail ───────────────────────────────────────────────────
    try:
        jail_path = '/etc/fail2ban/jail.d/infratak-takportal.conf'
        with open(jail_path) as f:
            cur = f.read()
        if TAKPORTAL_CADDY_LOG in cur:
            return changed                # already repointed
        cfg = _f2b_read_portal_jail_config()
        # The old default (5) was tuned for the per-result contract. HTTP status is a
        # blunter signal, so lift a still-default jail to the new floor; an operator
        # who deliberately chose a higher number keeps it.
        maxretry = cfg.get('maxretry', 5)
        if maxretry <= 5:
            maxretry = TAKPORTAL_F2B_MAXRETRY
        _f2b_write_portal_jail(maxretry, cfg.get('findtime', 600),
                               cfg.get('bantime', 3600),
                               _f2b_operator_extra(cfg.get('ignoreip', '')))
        subprocess.run(_sudo_wrap(['fail2ban-client', 'reload']), capture_output=True, timeout=60)
        _log('fail2ban: takportal jail repointed to Caddy\'s access log (maxretry=%d) — '
             'it had been watching a file nothing writes since 2026-06-12.' % maxretry)
        return True
    except Exception as e:
        _log(f'fail2ban: could not repoint the takportal jail (non-fatal): {e}')
        return changed


def _f2b_selfheal_trusted_ignoreip(plog=None):
    """Add the never-bannable subnets to every infra-TAK jail's ignoreip, and release
    anything already banned inside one.

    Two classes, both of which fail2ban must never cut:
      - management tunnels (WireGuard relay / NetBird) — the road IN. On a CGNAT box
        that tunnel is the only way to reach the machine.
      - our own container bridges — the road BETWEEN our services. See
        _f2b_container_subnets(): the takserver jail banned the nodered container on
        test8/test12 on 2026-07-25, and TAK Portal polls TAK on a 15 s timer that hits
        the jail's 20-per-300 s threshold exactly.

    Boxes deployed before each fix carry an ignoreip missing those subnets. Console-path
    delivery: this runs at startup so a normal update fixes it with no SSH. Idempotent;
    no-op when there is nothing to trust or nothing to change."""
    _log = plog or (lambda m: None)
    if not _f2b_is_available():
        return False
    tun = _f2b_mgmt_tunnel_subnets() + _f2b_container_subnets() + _f2b_own_addresses()
    if not tun:
        return False                      # no tunnel and no containers — nothing to trust
    jaild = '/etc/fail2ban/jail.d'
    if not os.path.isdir(jaild):
        return False
    import glob as _glob
    changed = []
    for path in sorted(_glob.glob(os.path.join(jaild, 'infratak-*.conf'))):
        try:
            with open(path) as f:
                text = f.read()
        except OSError:
            continue
        out, hit = [], False
        for line in text.splitlines(True):
            m = re.match(r'^\s*ignoreip\s*=\s*(.*?)\s*$', line)
            if not m:
                out.append(line)
                continue
            cur = m.group(1)
            new = _f2b_trusted_ignoreip(_f2b_operator_extra(cur))
            if set(new.split()) != set(cur.split()):
                out.append(f'ignoreip = {new}\n')
                hit = True
            else:
                out.append(line)
        if hit:
            try:
                _write_priv(path, ''.join(out))
                changed.append(os.path.basename(path))
            except Exception as e:
                _log(f'fail2ban: could not update ignoreip in {path}: {e}')

    # Release anything already banned inside a trusted subnet — the operator may be
    # locked out RIGHT NOW, or TAK Portal may be severed from TAK Server RIGHT NOW,
    # and a config rewrite alone does not lift a live ban.
    nets = []
    for c in tun:
        try:
            nets.append(ipaddress.ip_network(c))
        except Exception:
            pass
    unbanned = []
    try:
        st = subprocess.run(_sudo_wrap(['fail2ban-client', 'status']),
                            capture_output=True, text=True, timeout=30)
        jails = []
        for line in (st.stdout or '').splitlines():
            if 'Jail list:' in line:
                jails = [j.strip() for j in line.split(':', 1)[1].replace(',', ' ').split()]
        for j in jails:
            js = subprocess.run(_sudo_wrap(['fail2ban-client', 'status', j]),
                                capture_output=True, text=True, timeout=30)
            for line in (js.stdout or '').splitlines():
                if 'Banned IP list:' not in line:
                    continue
                for ip in line.split(':', 1)[1].split():
                    try:
                        addr = ipaddress.ip_address(ip.strip())
                    except ValueError:
                        continue
                    if any(addr in n for n in nets):
                        subprocess.run(_sudo_wrap(['fail2ban-client', 'set', j, 'unbanip', str(addr)]),
                                       capture_output=True, timeout=30)
                        unbanned.append(f'{addr} ({j})')
    except Exception as e:
        _log(f'fail2ban: trusted-subnet unban sweep failed (non-fatal): {e}')

    if not changed and not unbanned:
        return False
    if changed:
        _log('fail2ban: trusted subnets ' + ', '.join(tun) +
             ' added to ignoreip in ' + ', '.join(changed) +
             ' — the management tunnel and our own containers can no longer be banned.')
        try:
            subprocess.run(_sudo_wrap(['fail2ban-client', 'reload']), capture_output=True, timeout=60)
        except Exception:
            pass
    if unbanned:
        _log('fail2ban: released ' + ', '.join(unbanned) +
             ' — a management-tunnel or container address was banned, which blocks EVERY port from it.')
    return True


def _f2b_selfheal_rhel_jails(plog=None):
    """RHEL self-heal: repair fail2ban jail configs written by a pre-RHEL-port build.
    A jail with `action = ufw` (no ufw on RHEL) makes the WHOLE fail2ban daemon fail
    to start ('Unable to read action ufw'); and the sshd jail's
    `logpath = /var/log/auth.log` never matches (RHEL logs to /var/log/secure).
    Rewrite both in place across /etc/fail2ban/jail.d/*.conf, then reload (or restart
    if it's down) so the fix takes effect. No-op on Debian / when nothing is stale /
    when fail2ban isn't installed. Idempotent."""
    if _distro_family() != 'rhel':
        return False
    _log = plog or (lambda m: None)
    jaild = '/etc/fail2ban/jail.d'
    if not os.path.isdir(jaild):
        return False
    try:
        import glob as _glob
        banaction = _f2b_banaction()  # iptables-allports on RHEL
        changed = False
        for path in _glob.glob(os.path.join(jaild, '*.conf')):
            try:
                with open(path) as f:
                    txt = f.read()
            except Exception:
                continue
            new = re.sub(r'(?m)^(\s*action\s*=\s*)ufw\b', r'\g<1>' + banaction, txt)
            new = new.replace('/var/log/auth.log', '/var/log/secure')
            if new != txt:
                _write_priv(path, new)   # v10.0.5 non-root: /etc/fail2ban is root-owned
                changed = True
                _log(f"  fail2ban self-heal: patched {os.path.basename(path)} (ufw→{banaction}, auth.log→secure)")
        # The recidive jail reads fail2ban's OWN log (/var/log/fail2ban.log). On a box
        # where fail2ban never started cleanly (it was failing on the ufw action), that
        # file was never created → "Have not found any log file for recidive jail" →
        # fail2ban still won't start. Pre-create it (logtarget already points there) so
        # the jail loads on this start.
        if not os.path.exists('/var/log/fail2ban.log'):
            subprocess.run(_sudo_wrap(['touch', '/var/log/fail2ban.log']), capture_output=True, timeout=10)
            changed = True
            _log("  fail2ban self-heal: created /var/log/fail2ban.log (recidive jail reads it)")
        # Bring fail2ban up if jails are configured but it isn't running (clears the
        # failed state left by the pre-fix ufw config).
        act = subprocess.run(_sudo_wrap(['systemctl', 'is-active', 'fail2ban']),
                             capture_output=True, text=True).stdout.strip()
        if changed or act != 'active':
            if act == 'active':
                subprocess.run(_sudo_wrap(['fail2ban-client', 'reload']), capture_output=True, text=True, timeout=30)
            else:
                subprocess.run(_sudo_wrap(['systemctl', 'restart', 'fail2ban']), capture_output=True, text=True, timeout=30)
            _log("  ✓ fail2ban self-heal: jails repaired for RHEL and fail2ban (re)started")
        return changed
    except Exception as e:
        _log(f"  ⚠ fail2ban self-heal error (non-fatal): {str(e)[:120]}")
        return False


def _f2b_write_jail_config(maxretry, findtime, bantime, ignoreip=''):
    """Rewrite the infratak-authentik jail config with new thresholds and ignoreip whitelist."""
    jail_path = '/etc/fail2ban/jail.d/infratak-authentik.conf'
    _makedirs_priv('/etc/fail2ban/jail.d', exist_ok=True)
    # Never write this jail without its log file present: a missing logpath aborts the
    # WHOLE fail2ban daemon at config parse, not just this jail. The forwarder that
    # normally creates it is started only when Authentik is already running, so on any
    # box where it is not, this is the difference between fail2ban starting and not.
    _f2b_ensure_ak_logfile()
    guarddog_action = ""
    if os.path.exists('/etc/fail2ban/action.d/infratak-guarddog.conf'):
        guarddog_action = "\n         infratak-guarddog"
    ignoreip_line = f"ignoreip = {_f2b_trusted_ignoreip(ignoreip)}\n"
    jail_conf = (
        "[authentik]\n"
        "enabled  = true\n"
        "filter   = authentik\n"
        "logpath  = /var/log/authentik/auth.log\n"
        f"maxretry = {maxretry}\n"
        f"findtime = {findtime}\n"
        f"bantime  = {bantime}\n"
        f"{ignoreip_line}"
        f"action   = {_f2b_banaction()}{guarddog_action}\n"
    )
    _write_priv(jail_path, jail_conf)

def _f2b_tak_jail_enabled():
    """Return True if the infratak-takserver jail config file exists."""
    return os.path.exists('/etc/fail2ban/jail.d/infratak-takserver.conf')

def _f2b_read_tak_jail_config():
    """Read current thresholds and ignoreip from the infratak-takserver jail config file."""
    jail_path = '/etc/fail2ban/jail.d/infratak-takserver.conf'
    cfg = {'maxretry': 20, 'findtime': 300, 'bantime': 3600, 'ignoreip': ''}
    if not os.path.exists(jail_path):
        return cfg
    try:
        with open(jail_path) as _f:
            for line in _f:
                line = line.strip()
                for key in ('maxretry', 'findtime', 'bantime'):
                    if line.startswith(key):
                        try: cfg[key] = int(line.split('=')[1].strip())
                        except Exception: pass
                if line.startswith('ignoreip'):
                    cfg['ignoreip'] = line.split('=', 1)[1].strip()
    except Exception:
        pass
    return cfg

def _f2b_write_tak_jail_config(maxretry, findtime, bantime, ignoreip=''):
    """Write the infratak-takserver jail config with given thresholds."""
    jail_path = '/etc/fail2ban/jail.d/infratak-takserver.conf'
    _makedirs_priv('/etc/fail2ban/jail.d', exist_ok=True)
    guarddog_action = ""
    if os.path.exists('/etc/fail2ban/action.d/infratak-guarddog.conf'):
        guarddog_action = "\n         infratak-guarddog-takserver"
    ignoreip_line = f"ignoreip = {_f2b_trusted_ignoreip(ignoreip)}\n"
    jail_conf = (
        "[takserver]\n"
        "enabled  = true\n"
        "filter   = takserver\n"
        "logpath  = /opt/tak/logs/takserver-messaging.log\n"
        f"maxretry = {maxretry}\n"
        f"findtime = {findtime}\n"
        f"bantime  = {bantime}\n"
        f"{ignoreip_line}"
        f"action   = {_f2b_banaction()}{guarddog_action}\n"
    )
    _write_priv(jail_path, jail_conf)

def _f2b_ssh_jail_enabled():
    """Return True if the infratak-sshd jail config file exists."""
    return os.path.exists('/etc/fail2ban/jail.d/infratak-sshd.conf')

def _f2b_read_ssh_jail_config():
    """Read current thresholds and ignoreip from the infratak-sshd jail config file."""
    jail_path = '/etc/fail2ban/jail.d/infratak-sshd.conf'
    cfg = {'maxretry': 3, 'findtime': 600, 'bantime': 3600, 'ignoreip': ''}
    if not os.path.exists(jail_path):
        return cfg
    try:
        with open(jail_path) as _f:
            for line in _f:
                line = line.strip()
                for key in ('maxretry', 'findtime', 'bantime'):
                    if line.startswith(key):
                        try: cfg[key] = int(line.split('=')[1].strip())
                        except Exception: pass
                if line.startswith('ignoreip'):
                    cfg['ignoreip'] = line.split('=', 1)[1].strip()
    except Exception:
        pass
    return cfg

def _f2b_write_ssh_jail_config(maxretry, findtime, bantime, ignoreip=''):
    """Write the infratak-sshd jail config with given thresholds."""
    jail_path = '/etc/fail2ban/jail.d/infratak-sshd.conf'
    _makedirs_priv('/etc/fail2ban/jail.d', exist_ok=True)
    guarddog_action = ""
    if os.path.exists('/etc/fail2ban/action.d/infratak-guarddog.conf'):
        guarddog_action = "\n         infratak-guarddog"
    ignoreip_line = f"ignoreip = {_f2b_trusted_ignoreip(ignoreip)}\n"
    # No syslog file on this box (no rsyslog) → read sshd auth events straight
    # from the journal. Writing a logpath that does not exist would kill the
    # whole fail2ban daemon at config-parse time — see _f2b_sshd_logpath().
    _lp = _f2b_sshd_logpath()
    _source_line = f"logpath  = {_lp}\n" if _lp else "backend  = systemd\n"
    jail_conf = (
        "[sshd]\n"
        "enabled  = true\n"
        "filter   = sshd\n"
        f"{_source_line}"
        f"maxretry = {maxretry}\n"
        f"findtime = {findtime}\n"
        f"bantime  = {bantime}\n"
        f"{ignoreip_line}"
        f"action   = {_f2b_banaction()}{guarddog_action}\n"
    )
    _write_priv(jail_path, jail_conf)

def _f2b_authentik_jail_enabled():
    """Return True if the infratak-authentik jail config file exists."""
    return os.path.exists('/etc/fail2ban/jail.d/infratak-authentik.conf')


@app.route('/api/fail2ban/status')
@login_required
def fail2ban_status_api():
    """Return fail2ban jail status for the authentik jail, plus version info."""
    if not _f2b_is_available():
        return jsonify({'available': False, 'error': 'fail2ban not installed'})
    try:
        r = subprocess.run(_sudo_wrap(['fail2ban-client', 'status', 'authentik']),
                           capture_output=True, text=True, timeout=10)
        status = _f2b_parse_status(r.stdout)
        status['available']      = True
        status['daemon_running'] = (subprocess.run(
            ['systemctl', 'is-active', 'fail2ban'],
            capture_output=True, text=True).stdout.strip() == 'active')
        status['jail_enabled']   = _f2b_authentik_jail_enabled()
        status['jail_config']    = _f2b_read_jail_config()
        status['forwarder_active'] = (subprocess.run(
            ['systemctl', 'is-active', 'authentik-log-forwarder'],
            capture_output=True, text=True).stdout.strip() == 'active')
        status['version'] = _f2b_get_version()
        # v10.1.11 — report jails that are enabled on disk but NOT running. Without
        # this the page reads config files and calls a dead jail healthy, which is
        # exactly how Authentik went a month with no brute-force protection.
        status['dead_jails'] = [{'jail': j, 'filter': f, 'reason': r}
                                for j, f, r in _f2b_dead_jails()]
        return jsonify(status)
    except Exception as e:
        return jsonify({'available': False, 'error': str(e)[:200]})


@app.route('/api/fail2ban/authentik/config', methods=['POST'])
@login_required
def fail2ban_authentik_toggle_api():
    """Enable or disable the Authentik jail (and its log forwarder)."""
    if not _f2b_is_available():
        return jsonify({'ok': False, 'error': 'fail2ban not installed'}), 400
    data    = request.get_json(force=True) or {}
    enabled = bool(data.get('enabled', False))
    if not enabled:
        jail_path = '/etc/fail2ban/jail.d/infratak-authentik.conf'
        if os.path.exists(jail_path):
            subprocess.run(_sudo_wrap(['rm', '-f', jail_path]), capture_output=True)  # v10.0.5 non-root: /etc/fail2ban is root-owned
        subprocess.run(_sudo_wrap(['systemctl', 'stop',    'authentik-log-forwarder']), capture_output=True)
        subprocess.run(_sudo_wrap(['systemctl', 'disable', 'authentik-log-forwarder']), capture_output=True)
        subprocess.run(_sudo_wrap(['fail2ban-client', 'reload']), capture_output=True, timeout=15)
        return jsonify({'ok': True, 'enabled': False})
    # Enable: write jail config (preserving existing thresholds/ignoreip if present)
    cfg = _f2b_read_jail_config()
    ignoreip = str(data.get('ignoreip', cfg.get('ignoreip', ''))).strip()
    maxretry = int(data.get('maxretry', cfg.get('maxretry', 5)))
    findtime = int(data.get('findtime', cfg.get('findtime', 600)))
    bantime  = int(data.get('bantime',  cfg.get('bantime',  3600)))
    try:
        _f2b_write_jail_config(maxretry, findtime, bantime, ignoreip)
        # Re-write the log forwarder service file if it was never written
        # (e.g. servers that installed Fail2ban before this service was introduced).
        svc_path = '/etc/systemd/system/authentik-log-forwarder.service'
        if not os.path.exists(svc_path):
            forwarder_service = _AK_FORWARDER_UNIT
            _makedirs_priv('/var/log/authentik', exist_ok=True)
            _write_priv(svc_path, forwarder_service)
            subprocess.run(_sudo_wrap(['systemctl', 'daemon-reload']), capture_output=True)
        # Ensure the fail2ban daemon is running before reloading jails
        _svc = subprocess.run(_sudo_wrap(['systemctl', 'is-active', 'fail2ban']),
                              capture_output=True, text=True)
        if _svc.stdout.strip() != 'active':
            subprocess.run(_sudo_wrap(['systemctl', 'enable', '--now', 'fail2ban']),
                           capture_output=True)
        # Start log forwarder only if Authentik is running
        ak_running = subprocess.run(
            _sudo_wrap(['docker', 'ps', '--format', '{{.Names}}']),
            capture_output=True, text=True).stdout
        forwarder_msg = 'log forwarder not started (Authentik not running)'
        if 'authentik' in ak_running:
            # v10.1.40: was a bare enable --now with the return code discarded, so a
            # rate-limited/failed unit reported success while staying dead (Charles
            # Laird, NC — toggling the jail off/on "worked" and changed nothing).
            _fok, forwarder_msg = _f2b_start_ak_forwarder()
        subprocess.run(_sudo_wrap(['fail2ban-client', 'reload']), capture_output=True, timeout=15)
        # v10.1.38 — ARM the jail, don't just switch it on.
        #
        # Until now this route wrote the jail, started the forwarder, returned
        # enabled:true, and left AUTHENTIK_LOG_LEVEL alone. The level was raised ONLY by
        # _f2b_selfheal_authentik_log_level() at console startup — so from the moment an
        # operator enabled this jail until whenever the console next restarted, the
        # console reported a live brute-force control that could not match a single line.
        # `invalid_login` is a logger.info() call; at `warning` Authentik never writes it.
        # That window is unbounded: days, or weeks.
        #
        # This is what the field report was (US-FED-NE, 2026-08-17): jail enabled
        # 2026-08-15 18:24, reporting Active, 0 bans, .env at `warning`. Not a path bug —
        # enabling the control simply never armed it.
        #
        # The heal is a no-op unless the level is exactly `warning`, so on a correctly
        # configured box this costs one file read. When it does fire it recreates
        # Authentik, which is why the outcome is returned for the UI to surface rather
        # than done silently behind a toggle.
        level_msg = ''
        try:
            _heal = {}
            if _f2b_selfheal_authentik_log_level(detail=_heal):
                # Say only what happened. `compose up -d` is a no-op when the running
                # container already matches, so "Authentik recreated" is not a given.
                level_msg = ('log level raised to info; Authentik restarted'
                             if _heal.get('recreated')
                             else 'log level raised to info (no restart needed)')
            else:
                ok, lvl, why = _f2b_ak_log_level_verdict(force=True)
                if ok is False:
                    level_msg = 'WARNING: %s' % why
                elif ok is None:
                    level_msg = 'WARNING: could not verify Authentik can emit a matchable line (%s)' % why
        except Exception as _e:
            level_msg = 'WARNING: log-level check failed (%s)' % str(_e)[:80]
        return jsonify({'ok': True, 'enabled': True, 'forwarder': forwarder_msg,
                        'log_level': level_msg})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)[:200]}), 500


@app.route('/api/fail2ban/config', methods=['POST'])
@login_required
def fail2ban_config_api():
    """Update jail thresholds (maxretry, findtime, bantime) and reload fail2ban."""
    if not _f2b_is_available():
        return jsonify({'ok': False, 'error': 'fail2ban not installed'}), 400
    data = request.get_json(force=True) or {}
    try:
        maxretry = max(1, min(50, int(data.get('maxretry', 5))))
        findtime = max(60, min(86400, int(data.get('findtime', 600))))
        bantime = max(60, min(2592000, int(data.get('bantime', 3600))))
    except (ValueError, TypeError) as e:
        return jsonify({'ok': False, 'error': f'Invalid value: {e}'}), 400
    ignoreip = str(data.get('ignoreip', '')).strip()
    try:
        _f2b_write_jail_config(maxretry, findtime, bantime, ignoreip)
        subprocess.run(_sudo_wrap(['fail2ban-client', 'reload']), capture_output=True, timeout=15)
        return jsonify({'ok': True, 'maxretry': maxretry, 'findtime': findtime, 'bantime': bantime, 'ignoreip': ignoreip})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)[:200]}), 500

import re as _re_f2b
_VALID_IP_RE = _re_f2b.compile(
    r'^(\d{1,3}\.){3}\d{1,3}$|^[0-9a-fA-F:]+:[0-9a-fA-F:]+$')

@app.route('/api/fail2ban/unban', methods=['POST'])
@login_required
def fail2ban_unban_api():
    """Unban a specific IP from the authentik jail."""
    if not _f2b_is_available():
        return jsonify({'ok': False, 'error': 'fail2ban not installed'}), 400
    data = request.get_json(force=True) or {}
    ip = str(data.get('ip', '')).strip()
    if not ip or not _VALID_IP_RE.match(ip):
        return jsonify({'ok': False, 'error': 'Invalid IP address'}), 400
    try:
        r = subprocess.run(_sudo_wrap(['fail2ban-client', 'set', 'authentik', 'unbanip', ip]),
                           capture_output=True, text=True, timeout=10)
        if r.returncode == 0:
            return jsonify({'ok': True, 'ip': ip})
        return jsonify({'ok': False, 'error': r.stderr.strip()[:200] or 'Unban failed'}), 500
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)[:200]}), 500

@app.route('/api/fail2ban/log')
@login_required
def fail2ban_log_api():
    """Return last 100 lines from /var/log/fail2ban.log filtered to [authentik] jail."""
    log_path = '/var/log/fail2ban.log'
    if not os.path.exists(log_path):
        return jsonify({'lines': [], 'error': 'fail2ban.log not found'})
    try:
        r = subprocess.run(['tail', '-n', '300', log_path],
                           capture_output=True, text=True, timeout=5)
        all_lines = r.stdout.splitlines()
        filtered = [l for l in all_lines if 'authentik' in l.lower()][-100:]
        return jsonify({'lines': filtered})
    except Exception as e:
        return jsonify({'lines': [], 'error': str(e)[:200]})

