@app.route('/api/takserver/cert-expiry')
@login_required
def takserver_cert_expiry():
    """Return Root CA and Intermediate CA expiry dates and days remaining."""
    cert_dir = '/opt/tak/certs/files'
    results = {}
    for label, filename in [('root_ca', 'root-ca.pem'), ('intermediate_ca', 'ca.pem')]:
        path = os.path.join(cert_dir, filename)
        if not os.path.exists(path):
            results[label] = {'error': 'Not found', 'file': filename}
            continue
        try:
            r = subprocess.run(
                ['openssl', 'x509', '-enddate', '-noout', '-in', path],
                capture_output=True, text=True, timeout=5
            )
            if r.returncode != 0:
                results[label] = {'error': 'Failed to read cert'}
                continue
            raw = r.stdout.strip().split('=', 1)[-1]
            from datetime import datetime
            expiry = datetime.strptime(raw, '%b %d %H:%M:%S %Y %Z')
            now = datetime.utcnow()
            days_left = (expiry - now).days
            results[label] = {
                'file': filename,
                'expires': expiry.strftime('%Y-%m-%d'),
                'days_left': days_left
            }
        except Exception as e:
            results[label] = {'error': str(e)[:200]}
    return jsonify(results)


@app.route('/api/fedhub/cert-expiry')
@login_required
def fedhub_cert_expiry():
    """Return Federation Hub Root CA and Intermediate CA expiry (local or remote). Same shape as /api/takserver/cert-expiry."""
    settings = load_settings()
    cfg = _get_fedhub_deployment_config(settings)
    if not cfg.get('deployed'):
        return jsonify({'root_ca': {'error': 'Not deployed'}, 'intermediate_ca': {'error': 'Not deployed'}})
    is_remote = cfg.get('target_mode') == 'remote'
    remote = cfg.get('remote', {})
    if is_remote and not (remote.get('host') or '').strip():
        return jsonify({'root_ca': {'error': 'No host'}, 'intermediate_ca': {'error': 'No host'}})
    fh_dir = '/opt/tak/federation-hub/certs/files'
    results = {}
    for label, filename in [('root_ca', 'root-ca.pem'), ('intermediate_ca', 'ca.pem')]:
        path = f'{fh_dir}/{filename}'
        cmd = f'openssl x509 -enddate -noout -in {shlex.quote(path)} 2>/dev/null'
        ok, out = _module_run(cfg, cmd, timeout=15)
        if not ok or not (out or '').strip() or 'notAfter' not in out:
            results[label] = {'error': 'Not found', 'file': filename}
            continue
        try:
            raw = out.strip().split('=', 1)[-1].strip()
            from datetime import datetime
            expiry = datetime.strptime(raw, '%b %d %H:%M:%S %Y %Z')
            now = datetime.utcnow()
            days_left = (expiry - now).days
            results[label] = {
                'file': filename,
                'expires': expiry.strftime('%Y-%m-%d'),
                'days_left': days_left,
            }
        except Exception as e:
            results[label] = {'error': str(e)[:200], 'file': filename}
    return jsonify(results)


def _canonical_tak_group_name(value):
    """Normalize TAK group names to a canonical channel name.

    We intentionally collapse TAK Portal directional suffix groups
    (e.g. *_READ, *_WRITE, *_BOTH) to the base name so cert assignment
    targets the same channel identity.
    """
    name = str(value or '').strip()
    if not name:
        return ''
    m = re.match(r'^(.*?)(?:[_-](?:read|write|both))$', name, re.IGNORECASE)
    if m:
        base = (m.group(1) or '').strip()
        if base:
            return base
    return name


def _exclude_from_cert_group_picker(name):
    """Return True for system/admin groups we do not want in cert picker."""
    n = str(name or '').strip()
    if not n:
        return True
    lowered = n.lower()
    if lowered == '__anon__':
        return True
    if lowered == 'role_admin':
        return True
    if lowered.startswith('authentik'):
        return True
    if lowered.startswith('cn=tak_'):
        return True
    if lowered in ('vid_public', 'vid_private'):
        return True
    return False


@app.route('/api/takserver/groups')
@login_required
def takserver_groups():
    """List groups from TAK Server APIs using admin cert.

    We merge:
    - /Marti/api/groups/all
    - /user-management/api/list-groupnames
    so TAK Portal-created groups can still appear in certificate workflows.
    """
    settings = load_settings()
    cert_dir = '/opt/tak/certs/files'
    cert_pass = _get_tak_cert_password(settings)
    admin_p12 = os.path.join(cert_dir, 'admin.p12')
    if not os.path.exists(admin_p12):
        return jsonify({'error': 'admin.p12 not found in /opt/tak/certs/files/', 'groups': []})
    try:
        # TAK Server generates legacy PKCS12 (RC2-40-CBC) that modern curl/OpenSSL 3.x
        # rejects (exit 58). Extract PEM cert+key with -legacy flag for curl.
        admin_pem = '/tmp/tak-admin-curl.pem'
        admin_key = '/tmp/tak-admin-curl.key'
        # v10.0.5 non-root: admin.p12 is 0600 tak:tak — cat it via the broker into a temp so
        # openssl can read it (raw openssl as takwerx -> empty PEM -> "Failed to extract").
        import tempfile as _tf
        _src_p12, _tmp_src = admin_p12, None
        try:
            _cat = subprocess.run(_sudo_wrap(['cat', admin_p12]), capture_output=True, timeout=10)
            if _cat.returncode == 0 and _cat.stdout:
                _fd, _tmp_src = _tf.mkstemp(suffix='.p12')
                with os.fdopen(_fd, 'wb') as _f:
                    _f.write(_cat.stdout)
                _src_p12 = _tmp_src
        except Exception:
            pass
        subprocess.run(
            f'openssl pkcs12 -in {_src_p12} -passin pass:{shlex.quote(cert_pass)} -clcerts -nokeys -legacy 2>/dev/null > {admin_pem}',
            shell=True, capture_output=True, text=True, timeout=10)
        subprocess.run(
            f'openssl pkcs12 -in {_src_p12} -passin pass:{shlex.quote(cert_pass)} -nocerts -nodes -legacy 2>/dev/null > {admin_key}',
            shell=True, capture_output=True, text=True, timeout=10)
        if _tmp_src:
            try:
                os.remove(_tmp_src)
            except Exception:
                pass
        if not os.path.exists(admin_pem) or os.path.getsize(admin_pem) == 0:
            return jsonify({'error': 'Failed to extract PEM from admin.p12 (legacy conversion)', 'groups': []})
        import json as _json
        def _curl_json(url):
            cmd = ['curl', '-sk', '--max-time', '8',
                   '--cert', admin_pem, '--key', admin_key, url]
            r = subprocess.run(cmd, capture_output=True, text=True, timeout=12)
            body = (r.stdout or '').strip()
            if r.returncode != 0 or not body:
                return None, f'curl_exit_{r.returncode}'
            try:
                return _json.loads(body), None
            except _json.JSONDecodeError:
                return None, 'invalid_json'

        merged = {}
        warnings = []

        marti_data, marti_err = _curl_json('https://127.0.0.1:8443/Marti/api/groups/all')
        if marti_data is not None:
            items = marti_data.get('data', marti_data) if isinstance(marti_data, dict) else marti_data
            if isinstance(items, list):
                for g in items:
                    if not isinstance(g, dict):
                        continue
                    name = _canonical_tak_group_name(g.get('name'))
                    if _exclude_from_cert_group_picker(name):
                        continue
                    merged[name] = {
                        'name': name,
                        'direction': g.get('direction', ''),
                        'active': g.get('active', True)
                    }
        elif marti_err:
            warnings.append(f'marti_groups:{marti_err}')

        um_data, um_err = _curl_json('https://127.0.0.1:8443/user-management/api/list-groupnames')
        if um_data is not None:
            items = um_data.get('data', um_data) if isinstance(um_data, dict) else um_data
            if isinstance(items, list):
                for g in items:
                    if isinstance(g, str):
                        name = _canonical_tak_group_name(g)
                    elif isinstance(g, dict):
                        name = _canonical_tak_group_name(
                            g.get('name')
                            or g.get('groupName')
                            or g.get('groupname')
                            or g.get('group')
                            or ''
                        )
                    else:
                        name = ''
                    if _exclude_from_cert_group_picker(name):
                        continue
                    if name not in merged:
                        merged[name] = {
                            'name': name,
                            'direction': '',
                            'active': True
                        }
        elif um_err:
            warnings.append(f'user_mgmt_groups:{um_err}')

        # Also pull tak_* groups directly from Authentik so newly-created groups
        # appear in the picker before first user login hits TAK.
        ak_token = _get_authentik_env_value(settings, 'AUTHENTIK_BOOTSTRAP_TOKEN') or _get_authentik_env_value(settings, 'AUTHENTIK_TOKEN')
        if ak_token:
            try:
                import urllib.request as _req
                import urllib.parse as _parse
                ak_url = _get_authentik_api_url(settings)
                next_url = f'{ak_url}/api/v3/core/groups/?page_size=200&name__istartswith=tak_'
                seen = 0
                while next_url and seen < 2000:
                    req = _req.Request(next_url, headers={'Authorization': f'Bearer {ak_token}', 'Content-Type': 'application/json'})
                    with _req.urlopen(req, timeout=12) as resp:
                        page = _json.loads((resp.read() or b'').decode('utf-8', 'replace'))
                    results = page.get('results', []) if isinstance(page, dict) else []
                    for g in results:
                        raw = (g.get('name') or '').strip() if isinstance(g, dict) else ''
                        if not raw:
                            continue
                        name = raw[4:] if raw.lower().startswith('tak_') else raw
                        name = _canonical_tak_group_name(name)
                        if _exclude_from_cert_group_picker(name):
                            continue
                        if name not in merged:
                            merged[name] = {
                                'name': name,
                                'direction': '',
                                'active': True
                            }
                    seen += len(results)
                    nxt = page.get('next') if isinstance(page, dict) else None
                    if not nxt:
                        next_url = None
                    elif str(nxt).startswith('http'):
                        next_url = str(nxt)
                    else:
                        next_url = _parse.urljoin(ak_url, str(nxt))
            except Exception as e:
                warnings.append(f'authentik_groups:{str(e)[:80]}')

        groups = sorted(merged.values(), key=lambda x: x['name'].lower())
        if not groups and warnings:
            return jsonify({'error': '; '.join(warnings), 'groups': []})
        if warnings:
            return jsonify({'groups': groups, 'warnings': warnings})
        return jsonify({'groups': groups})
    except Exception as e:
        return jsonify({'error': str(e)[:200], 'groups': []})
    finally:
        for f in ['/tmp/tak-admin-curl.pem', '/tmp/tak-admin-curl.key']:
            try:
                os.remove(f)
            except OSError:
                pass


@app.route('/api/takserver/ca-info')
@login_required
def takserver_ca_info():
    """Return current Root CA and Intermediate CA names, expiry, and truststore contents."""
    cert_dir = '/opt/tak/certs/files'
    cert_pass = _get_tak_cert_password(load_settings())
    info = {'root_ca': None, 'intermediate_ca': None, 'old_cas_in_truststore': [], 'suggested_new_name': ''}
    for label, filename in [('root_ca', 'root-ca.pem'), ('intermediate_ca', 'ca.pem')]:
        path = os.path.join(cert_dir, filename)
        if not os.path.exists(path):
            continue
        try:
            r = subprocess.run(['openssl', 'x509', '-subject', '-enddate', '-noout', '-in', path],
                               capture_output=True, text=True, timeout=5)
            cn = ''
            expiry_raw = ''
            for line in r.stdout.strip().split('\n'):
                line = line.strip()
                if line.startswith('subject=') or line.startswith('subject ='):
                    subj = line.split('=', 1)[-1].strip()
                    for part in subj.split(','):
                        part = part.strip()
                        if part.startswith('CN') or part.startswith('CN '):
                            cn = part.split('=', 1)[-1].strip()
                elif 'notAfter' in line:
                    expiry_raw = line.split('=', 1)[-1].strip()
            days_left = None
            expires = ''
            if expiry_raw:
                from datetime import datetime
                exp_dt = datetime.strptime(expiry_raw, '%b %d %H:%M:%S %Y %Z')
                days_left = (exp_dt - datetime.utcnow()).days
                expires = exp_dt.strftime('%Y-%m-%d')
            info[label] = {'name': cn, 'file': filename, 'expires': expires, 'days_left': days_left}
        except Exception:
            pass
    import re
    def _increment_name(name):
        m = re.search(r'(\d+)$', name)
        if m:
            return name[:m.start()] + f'{int(m.group(1)) + 1:02d}'
        return name + '-02'
    if info['intermediate_ca'] and info['intermediate_ca']['name']:
        info['suggested_new_name'] = _increment_name(info['intermediate_ca']['name'])
    if info['root_ca'] and info['root_ca']['name']:
        info['suggested_new_root_name'] = _increment_name(info['root_ca']['name'])
        info['suggested_new_root_int_name'] = _increment_name(info.get('suggested_new_name', 'INT-CA-01'))
    # List CAs in current truststore (to show old CAs that can be revoked)
    import glob as _glob
    ts_files = sorted(_glob.glob(os.path.join(cert_dir, 'truststore-*.jks')))
    ts_files = [f for f in ts_files if 'root' not in os.path.basename(f)]
    if ts_files:
        ts_path = ts_files[-1]
        info['truststore_file'] = os.path.basename(ts_path)
        try:
            if _tak_is_container():
                # v10.0.1: no host keytool on a container box (JDK is inside the container) —
                # list the truststore inside the running TAK container so old CAs are detected
                # and the 'Revoke Old CA' box actually appears on arm64.
                _kt = f'keytool -list -keystore {shlex.quote(ts_path)} -storepass {shlex.quote(cert_pass)}'
                r = subprocess.run(f'docker exec {TAK_CONTAINER} bash -c {shlex.quote(_kt)}',
                                   shell=True, capture_output=True, text=True, timeout=15)
            else:
                r = subprocess.run(
                    ['keytool', '-list', '-keystore', ts_path, '-storepass', cert_pass],
                    capture_output=True, text=True, timeout=10)
            aliases = []
            trusted_aliases = []
            for line in r.stdout.split('\n'):
                if ',' not in line:
                    continue
                alias = line.split(',')[0].strip()
                if 'trustedCertEntry' in line:
                    aliases.append(alias)
                    trusted_aliases.append(alias)
                elif 'PrivateKeyEntry' in line:
                    aliases.append(alias)
            info['truststore_aliases'] = aliases
            current_cn = (info['intermediate_ca'] or {}).get('name', '').lower()
            root_cn = (info['root_ca'] or {}).get('name', '').lower()
            old_cas = []
            skip_aliases = {'mykey'}  # legacy default alias, not a CA to revoke
            for a in trusted_aliases:
                if a.lower() in skip_aliases:
                    continue
                if a.lower() != current_cn.lower() and a.lower() != 'root-ca' and a.lower() != root_cn.lower():
                    old_cas.append(a)
            info['old_cas_in_truststore'] = old_cas
        except Exception:
            pass
    return jsonify(info)


rotate_intca_log = []
rotate_intca_status = {'running': False, 'complete': False, 'error': False}

@app.route('/api/takserver/rotate-intca', methods=['POST'])
@login_required
def takserver_rotate_intca():
    """Rotate the intermediate CA: create new CA, server cert, admin cert, import old CA into truststore."""
    if rotate_intca_status.get('running'):
        return jsonify({'error': 'Rotation already in progress'}), 409
    data = request.json or {}
    new_ca_name = (data.get('new_ca_name') or '').strip()
    if not new_ca_name:
        return jsonify({'error': 'New CA name is required'}), 400
    import re
    if not re.match(r'^[a-zA-Z0-9._-]+$', new_ca_name):
        return jsonify({'error': 'CA name can only contain letters, numbers, dots, hyphens, underscores'}), 400

    cert_dir = '/opt/tak/certs/files'
    if not os.path.exists(os.path.join(cert_dir, 'root-ca.pem')):
        return jsonify({'error': 'root-ca.pem not found — cannot rotate without a Root CA'}), 400
    if not os.path.exists(os.path.join(cert_dir, 'ca.pem')):
        return jsonify({'error': 'ca.pem not found — no current intermediate CA detected'}), 400

    # Detect current intermediate CA name
    try:
        r = subprocess.run(['openssl', 'x509', '-subject', '-noout', '-in', os.path.join(cert_dir, 'ca.pem')],
                           capture_output=True, text=True, timeout=5)
        old_ca_name = ''
        for part in r.stdout.replace('subject=', '').split(','):
            part = part.strip()
            if part.startswith('CN') or part.startswith('CN '):
                old_ca_name = part.split('=', 1)[-1].strip()
    except Exception:
        old_ca_name = ''
    if not old_ca_name:
        return jsonify({'error': 'Could not detect current intermediate CA name from ca.pem'}), 500
    if new_ca_name == old_ca_name:
        return jsonify({'error': f'New CA name must be different from current ({old_ca_name})'}), 400

    # Optional new cert password (save so thread uses it for new keystores)
    new_cert_password = (data.get('new_cert_password') or '').strip()
    if new_cert_password:
        settings = load_settings()
        settings['tak_cert_password'] = new_cert_password
        save_settings(settings)
    cert_pass = _get_tak_cert_password(load_settings())

    # Root CA days left — cap new intermediate validity to this
    root_days_left = None
    try:
        r = subprocess.run(['openssl', 'x509', '-enddate', '-noout', '-in', os.path.join(cert_dir, 'root-ca.pem')],
                           capture_output=True, text=True, timeout=5)
        if r.returncode == 0 and r.stdout:
            from datetime import datetime
            expiry_raw = r.stdout.strip().split('=', 1)[-1].strip()
            exp_dt = datetime.strptime(expiry_raw, '%b %d %H:%M:%S %Y %Z')
            root_days_left = (exp_dt - datetime.utcnow()).days
    except Exception:
        pass

    try:
        requested_validity = int(data.get('intermediate_validity_days') or 730)
        requested_validity = max(1, min(3652, requested_validity))
    except (TypeError, ValueError):
        requested_validity = 730
    int_validity_days = min(requested_validity, root_days_left) if root_days_left is not None and root_days_left > 0 else requested_validity
    if root_days_left is not None and requested_validity > root_days_left:
        pass  # already capped to root_days_left in int_validity_days

    rotate_intca_log.clear()
    rotate_intca_status.update({'running': True, 'complete': False, 'error': False})

    def do_rotate():
        def log(msg):
            rotate_intca_log.append(msg)

        def run(cmd, desc=None, check=True):
            if desc:
                log(desc)
            cmd = _rotate_tak_cert_cmd(cmd)  # v10.0.1: container-aware (runuser/chown/systemctl → docker)
            try:
                r = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=120)
                if check and r.returncode != 0:
                    err = (r.stderr or r.stdout or '').strip()[:200]
                    log(f"  ✗ Failed (exit {r.returncode}): {err}")
                    return False
                return True
            except Exception as e:
                log(f"  ✗ Exception: {e}")
                return False

        try:
            log(f"━━━ Rotating Intermediate CA ━━━")
            log(f"  Old CA: {old_ca_name}")
            log(f"  New CA: {new_ca_name}")
            log("")

            # Save current (old) intermediate to a named file before we overwrite ca.pem — needed for transition bundle and truststore
            old_pem = os.path.join(cert_dir, f'{old_ca_name}.pem')
            if not os.path.exists(old_pem):
                run(f'cp {cert_dir}/ca.pem {old_pem}')
                log(f"  Saved current CA to {old_ca_name}.pem for transition bundle")

            log("Step 1/7: Restoring Root CA as working CA...")
            run(f'cp {cert_dir}/root-ca.pem {cert_dir}/ca.pem')
            run(f'cp {cert_dir}/root-ca-do-not-share.key {cert_dir}/ca-do-not-share.key')
            run(f'cp {cert_dir}/root-ca-trusted.pem {cert_dir}/ca-trusted.pem')
            log("✓ Root CA files restored")

            _patch_openssl_string_mask()

            log("")
            log(f"Step 2/7: Creating new Intermediate CA: {new_ca_name}...")
            run('chown tak:tak /opt/tak/certs/cert-metadata.sh && chmod 500 /opt/tak/certs/cert-metadata.sh')
            run(f'grep -qE "^CA_VALIDITY=" /opt/tak/certs/cert-metadata.sh 2>/dev/null && sed -i "s/^CA_VALIDITY=.*/CA_VALIDITY={int_validity_days}/" /opt/tak/certs/cert-metadata.sh || true', check=False)
            run(f'grep -qE "^INTERMEDIATE_VALIDITY" /opt/tak/certs/cert-metadata.sh 2>/dev/null && sed -i "s/^INTERMEDIATE_VALIDITY.*/INTERMEDIATE_VALIDITY={int_validity_days}/" /opt/tak/certs/cert-metadata.sh || true', check=False)
            log(f"  New intermediate validity: {int_validity_days} days (capped by root if needed)")
            _patch_cert_metadata_password(cert_pass)
            if not run(f'cd /opt/tak/certs && echo "y" | runuser -u tak -- /opt/tak/certs/makeCert.sh ca "{new_ca_name}" 2>&1'):
                raise Exception('Failed to create new intermediate CA')
            log(f"✓ Intermediate CA {new_ca_name} created")

            log("")
            log("Step 3/7: Creating new server certificate (signed by new CA)...")
            if not run(f'cd /opt/tak/certs && echo "y" | runuser -u tak -- /opt/tak/certs/makeCert.sh server takserver 2>&1'):
                raise Exception('Failed to create new server certificate')
            log("✓ Server certificate regenerated (signed by new CA)")

            log("")
            log("Step 4/7: Regenerating all client certificates...")
            run('chown tak:tak /opt/tak/certs/cert-metadata.sh && chmod 500 /opt/tak/certs/cert-metadata.sh')
            skip = {'takserver', 'root-ca', 'ca', old_ca_name.lower(), new_ca_name.lower()}
            regen_count = 0
            for f in sorted(os.listdir(cert_dir)):
                if not f.endswith('.p12'):
                    continue
                name = f[:-4]
                if name.lower() in skip or name.startswith('truststore-'):
                    continue
                log(f"  Regenerating: {name}")
                run(f'cd /opt/tak/certs && echo "y" | runuser -u tak -- /opt/tak/certs/makeCert.sh client {name} 2>&1')
                regen_count += 1
            log(f"✓ {regen_count} client certificate(s) regenerated (signed by new CA)")

            log("")
            log("Step 5/7: Updating truststore...")
            ts_jks = os.path.join(cert_dir, f'truststore-{new_ca_name}.jks')
            # v10.0.5 non-root: bare keytool writes JKS into tak-owned /opt/tak/certs/files
            # and fails as takwerx — route via the broker-allowed `runuser -u tak -- keytool`.
            run(f'runuser -u tak -- keytool -import -alias root-ca -file {cert_dir}/root-ca.pem '
                f'-keystore {ts_jks} -storepass {shlex.quote(cert_pass)} -noprompt 2>&1', check=False)
            log("  Root CA imported into new truststore")
            old_pem = os.path.join(cert_dir, f'{old_ca_name}.pem')
            if os.path.exists(old_pem):
                run(f'runuser -u tak -- keytool -import -trustcacerts -file {old_pem} '
                    f'-keystore {ts_jks} -alias "{old_ca_name}" -deststorepass {shlex.quote(cert_pass)} -noprompt 2>&1',
                    check=False)
                log(f"  Old CA ({old_ca_name}) imported into new truststore (transition period)")
            else:
                log(f"  ⚠ {old_ca_name}.pem not found — old CA NOT added to truststore")
            log("✓ Truststore updated")

            log("")
            log("Step 6/7: Updating CoreConfig.xml...")
            # v10.0.5 non-root: sed isn't broker-routed + /opt/tak is tak:tak — rewrite
            # CoreConfig via broker read-modify-write.
            for _cc in ('/opt/tak/CoreConfig.xml', '/opt/tak/CoreConfig.example.xml'):
                try:
                    _t = _read_priv(_cc)
                    if old_ca_name in _t:
                        _write_priv(_cc, _t.replace(old_ca_name, new_ca_name))
                except Exception:
                    pass
            _patch_coreconfig_passwords(cert_pass, log_fn=log)
            log("✓ CoreConfig.xml updated")

            log("")
            log("Step 7/7: Updating TAK Portal certificates...")
            # v10.0.1: delegate to _takportal_sync_certs — refreshes client cert +
            # CA via a temp-file re-encode (the old stdin pipe failed on OpenSSL 3
            # and shipped an unreadable legacy cert). restart=True so the portal
            # picks up the new CA-signed cert.
            _tp_ok, _tp_msg = _takportal_sync_certs(plog=log, restart=True)
            log(f"  {'✓' if _tp_ok else '⚠'} TAK Portal cert sync: {_tp_msg}")

            log("")
            log("Restarting TAK Server...")
            ne_changed, ne_msg = _sanitize_coreconfig_name_entries()
            if ne_changed:
                log(f"  NameEntry fix: {ne_msg}")
            changed, resync_msg = _resync_ldap_credential_to_coreconfig()
            if changed:
                log(f"  LDAP resync: {resync_msg}")
            run('systemctl restart takserver 2>&1')
            log("  Waiting for TAK Server to come back up...")
            time.sleep(45)
            log("✓ TAK Server restarted")

            log("")
            log("━━━ ROTATION COMPLETE ━━━")
            log(f"  New CA: {new_ca_name}")
            log(f"  Server cert + all client certs signed by new CA")
            log(f"  Old CA ({old_ca_name}) in truststore — server still accepts old client certs during transition")
            log(f"  Existing ATAK clients must re-enroll (new QR) to get the new CA")
            log(f"  When everyone has re-enrolled, use 'Revoke Old CA' to remove {old_ca_name}")
            rotate_intca_status.update({'running': False, 'complete': True, 'error': False})
        except Exception as e:
            log(f"")
            log(f"✗ ROTATION FAILED: {e}")
            rotate_intca_status.update({'running': False, 'complete': True, 'error': True})

    import threading
    threading.Thread(target=do_rotate, daemon=True).start()
    return jsonify({'started': True, 'old_ca': old_ca_name, 'new_ca': new_ca_name})


@app.route('/api/takserver/rotate-intca/status')
@login_required
def takserver_rotate_intca_status():
    return jsonify({'log': rotate_intca_log, **rotate_intca_status})


@app.route('/api/takserver/revoke-old-ca', methods=['POST'])
@login_required
def takserver_revoke_old_ca():
    """Create new server cert (signed by current/new CA), remove old CA from truststore, restart. Cuts off clients with old certs."""
    data = request.json or {}
    old_ca_alias = (data.get('old_ca_alias') or '').strip()
    if not old_ca_alias:
        return jsonify({'error': 'Old CA alias is required'}), 400

    cert_dir = '/opt/tak/certs/files'
    cert_pass = _get_tak_cert_password(load_settings())
    import glob as _glob
    ts_files = sorted(_glob.glob(os.path.join(cert_dir, 'truststore-*.jks')))
    ts_files = [f for f in ts_files if 'root' not in os.path.basename(f)]
    if not ts_files:
        return jsonify({'error': 'No truststore found'}), 500
    ts_path = ts_files[-1]

    try:
        # 1) Create new server cert (signed by current = new CA) so server presents new chain. Skip if using Let's Encrypt.
        le_jks = os.path.join(cert_dir, 'takserver-le.jks')
        if not os.path.isfile(le_jks):
            r = subprocess.run(
                _rotate_tak_cert_cmd('cd /opt/tak/certs && echo "y" | runuser -u tak -- /opt/tak/certs/makeCert.sh server takserver 2>&1'),
                shell=True, capture_output=True, text=True, timeout=120)
            if r.returncode != 0:
                return jsonify({'error': f'Creating new server cert failed: {(r.stderr or r.stdout or "")[:200]}'}), 500
            # Build JKS from new takserver.p12 so server can use it (CoreConfig may reference takserver.jks or we update connector)
            p12 = os.path.join(cert_dir, 'takserver.p12')
            jks = os.path.join(cert_dir, 'takserver.jks')
            if os.path.isfile(p12):
                subprocess.run(
                    _rotate_tak_cert_cmd(
                        f'runuser -u tak -- keytool -importkeystore -srcstoretype PKCS12 -srckeystore {p12} -srcstorepass {shlex.quote(cert_pass)} '
                        f'-deststoretype JKS -destkeystore {jks} -deststorepass {shlex.quote(cert_pass)} -noprompt 2>&1'),
                    shell=True, capture_output=True, text=True, timeout=30)

        # 2) Remove old CA from truststore
        r = subprocess.run(
            _rotate_tak_cert_cmd(
                f'runuser -u tak -- keytool -delete -alias {shlex.quote(old_ca_alias)} '
                f'-keystore {shlex.quote(ts_path)} -storepass {shlex.quote(cert_pass)} 2>&1'),
            shell=True, capture_output=True, text=True, timeout=15)
        if r.returncode != 0:
            return jsonify({'error': f'keytool failed: {r.stderr or r.stdout}'}), 500

        # 3) Regenerate .p12 truststore
        ts_p12 = ts_path.replace('.jks', '.p12')
        subprocess.run(
            _rotate_tak_cert_cmd(
                f'runuser -u tak -- keytool -importkeystore -srckeystore {ts_path} -destkeystore {ts_p12} '
                f'-srcstoretype JKS -deststoretype PKCS12 -srcstorepass {shlex.quote(cert_pass)} -deststorepass {shlex.quote(cert_pass)} -noprompt 2>&1'),
            shell=True, capture_output=True, text=True, timeout=15)

        if _tak_is_container():
            subprocess.run(_sudo_wrap(['docker', 'restart', 'takserver']), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=120)
        else:
            subprocess.run(_sudo_wrap(['systemctl', 'restart', 'takserver']), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=90)

        # 4) Update TAK Portal certs so it can talk to TAK Server (new server cert / chain)
        # v10.0.1: delegate to _takportal_sync_certs (temp-file re-encode of the
        # client cert + CA; restart so the portal picks up the new chain).
        _takportal_sync_certs(restart=True)

        msg = (f'Removed {old_ca_alias} from truststore and restarted TAK Server. '
               f'Server cert is now signed by the new CA (clients who re-enrolled via CloudTAK/QR can connect). '
               f'TAK Portal certs updated. Clients still using certs signed by {old_ca_alias} must re-enroll.')
        if os.path.isfile(le_jks):
            msg = (f'Removed {old_ca_alias} from truststore and restarted TAK Server. '
                   f'(Server TLS is Let\'s Encrypt; unchanged.) Clients with certs signed by {old_ca_alias} must re-enroll.')
        return jsonify({'success': True, 'message': msg})
    except Exception as e:
        return jsonify({'error': str(e)[:200]}), 500


rotate_rootca_log = []
rotate_rootca_status = {'running': False, 'complete': False, 'error': False}

@app.route('/api/takserver/rotate-rootca', methods=['POST'])
@login_required
def takserver_rotate_rootca():
    """Full Root CA rotation: new root, new intermediate, new server cert, all client certs, update TAK Portal, restart."""
    if rotate_rootca_status.get('running'):
        return jsonify({'error': 'Root CA rotation already in progress'}), 409
    data = request.json or {}
    new_root_name = (data.get('new_root_name') or '').strip()
    new_int_name = (data.get('new_int_name') or '').strip()
    if not new_root_name or not new_int_name:
        return jsonify({'error': 'Both new Root CA and Intermediate CA names are required'}), 400
    import re
    for name in [new_root_name, new_int_name]:
        if not re.match(r'^[a-zA-Z0-9._-]+$', name):
            return jsonify({'error': f'CA name "{name}" can only contain letters, numbers, dots, hyphens, underscores'}), 400

    # Optional new cert password (save so thread uses it for new keystores)
    new_cert_password = (data.get('new_cert_password') or '').strip()
    if new_cert_password:
        settings = load_settings()
        settings['tak_cert_password'] = new_cert_password
        save_settings(settings)
    cert_pass = _get_tak_cert_password(load_settings())

    cert_dir = '/opt/tak/certs/files'
    if not os.path.exists(os.path.join(cert_dir, 'root-ca.pem')):
        return jsonify({'error': 'root-ca.pem not found — no current Root CA detected'}), 400

    # Detect current names
    old_root_name = ''
    old_int_name = ''
    for label, filename in [('root', 'root-ca.pem'), ('int', 'ca.pem')]:
        path = os.path.join(cert_dir, filename)
        if not os.path.exists(path):
            continue
        try:
            r = subprocess.run(['openssl', 'x509', '-subject', '-noout', '-in', path],
                               capture_output=True, text=True, timeout=5)
            for line in r.stdout.strip().split('\n'):
                if line.startswith('subject=') or line.startswith('subject ='):
                    subj = line.split('=', 1)[-1].strip()
                    for part in subj.split(','):
                        part = part.strip()
                        if part.startswith('CN') or part.startswith('CN '):
                            cn = part.split('=', 1)[-1].strip()
                            if label == 'root':
                                old_root_name = cn
                            else:
                                old_int_name = cn
        except Exception:
            pass
    if not old_root_name:
        return jsonify({'error': 'Could not detect current Root CA name'}), 500

    rotate_rootca_log.clear()
    rotate_rootca_status.update({'running': True, 'complete': False, 'error': False})

    def do_rotate_root():
        def log(msg):
            rotate_rootca_log.append(msg)

        def run(cmd, desc=None, check=True):
            if desc:
                log(desc)
            cmd = _rotate_tak_cert_cmd(cmd)  # v10.0.1: container-aware (runuser/chown/systemctl → docker)
            try:
                r = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=120)
                if check and r.returncode != 0:
                    err = (r.stderr or r.stdout or '').strip()[:200]
                    log(f"  ✗ Failed (exit {r.returncode}): {err}")
                    return False
                return True
            except Exception as e:
                log(f"  ✗ Exception: {e}")
                return False

        try:
            log("━━━ Rotating Root CA ━━━")
            log(f"  Old Root CA: {old_root_name}")
            log(f"  Old Intermediate CA: {old_int_name}")
            log(f"  New Root CA: {new_root_name}")
            log(f"  New Intermediate CA: {new_int_name}")
            log("")

            log("Step 1/8: Removing old certificate files...")
            if _tak_is_container():
                # v10.0.1: the cert files are owned by the container uid, so a HOST `rm -rf`
                # as takwerx SILENTLY fails and the old truststore-*.jks survives — then Step 6's
                # `keytool -import -alias root-ca` hits the existing `root-ca` alias and is dropped
                # (check=False), so the new ROOT CA never lands in the truststore and EUDs get
                # "cert not trusted". Clear the dir INSIDE the container (root there) so the
                # rotation starts from a clean slate, exactly like the native rm does. The native
                # branch below is byte-identical to before — Ubuntu/Rocky are untouched.
                _tak_real = os.path.realpath('/opt/tak')
                run(f"docker run --rm -v {shlex.quote(_tak_real)}:/opt/tak:z --entrypoint bash "
                    f"{TAK_CONTAINER} -c 'rm -rf /opt/tak/certs/files && mkdir -p /opt/tak/certs/files' 2>&1")
            else:
                run('rm -rf /opt/tak/certs/files')
                run('mkdir -p /opt/tak/certs/files')
                run('chown -R tak:tak /opt/tak/certs/')
            log("✓ Old cert files cleared")

            _patch_openssl_string_mask()

            log("")
            log(f"Step 2/8: Creating new Root CA: {new_root_name}...")
            run('chown tak:tak /opt/tak/certs/cert-metadata.sh && chmod 500 /opt/tak/certs/cert-metadata.sh')
            _patch_cert_metadata_password(cert_pass)
            if not run(f'cd /opt/tak/certs && echo "{new_root_name}" | runuser -u tak -- /opt/tak/certs/makeRootCa.sh 2>&1'):
                raise Exception('Failed to create new Root CA')
            log(f"✓ Root CA {new_root_name} created")

            log("")
            log(f"Step 3/8: Creating new Intermediate CA: {new_int_name}...")
            if not run(f'cd /opt/tak/certs && echo "y" | runuser -u tak -- /opt/tak/certs/makeCert.sh ca "{new_int_name}" 2>&1'):
                raise Exception('Failed to create new Intermediate CA')
            log(f"✓ Intermediate CA {new_int_name} created")

            log("")
            log("Step 4/8: Creating new server certificate...")
            if not run('cd /opt/tak/certs && echo "y" | runuser -u tak -- /opt/tak/certs/makeCert.sh server takserver 2>&1'):
                raise Exception('Failed to create server certificate')
            log("✓ Server certificate created")

            log("")
            log("Step 5/8: Regenerating all client certificates...")
            skip = {'takserver', 'root-ca', 'ca', new_root_name.lower(), new_int_name.lower(),
                    old_root_name.lower(), old_int_name.lower()}
            # We need to create admin and user first since old files were cleared
            run('cd /opt/tak/certs && runuser -u tak -- /opt/tak/certs/makeCert.sh client admin 2>&1')
            log("  Regenerated: admin")
            run('cd /opt/tak/certs && runuser -u tak -- /opt/tak/certs/makeCert.sh client user 2>&1')
            log("  Regenerated: user")
            # Check settings or old backup for any other client cert names to recreate
            regen_count = 2
            log(f"✓ {regen_count} client certificate(s) created")
            log("  Note: Additional client certs (Node-RED, etc.) must be recreated manually")

            log("")
            log("Step 6/8: Updating truststore...")
            ts_jks = os.path.join(cert_dir, f'truststore-{new_int_name}.jks')
            # v10.0.5 non-root: route keytool via broker-allowed `runuser -u tak -- keytool`.
            run(f'runuser -u tak -- keytool -import -alias root-ca -file {cert_dir}/root-ca.pem '
                f'-keystore {ts_jks} -storepass {shlex.quote(cert_pass)} -noprompt 2>&1', check=False)
            log("  Root CA imported into truststore")
            log("✓ Truststore updated")

            log("")
            log("Step 7/8: Updating CoreConfig.xml...")
            # v10.0.5 non-root: sed isn't broker-routed + /opt/tak is tak:tak — rewrite
            # CoreConfig via broker read-modify-write.
            _repl = []
            if old_int_name:
                _repl.append((old_int_name, new_int_name))
            if old_root_name and old_root_name != new_root_name:
                _repl.append((old_root_name, new_root_name))
            for _cc in ('/opt/tak/CoreConfig.xml', '/opt/tak/CoreConfig.example.xml'):
                try:
                    _t = _read_priv(_cc); _orig = _t
                    for _o, _n in _repl:
                        _t = _t.replace(_o, _n)
                    if _t != _orig:
                        _write_priv(_cc, _t)
                except Exception:
                    pass
            _patch_coreconfig_passwords(cert_pass, log_fn=log)
            log("✓ CoreConfig.xml updated")

            log("")
            log("Step 8/8: Restarting TAK Server and updating TAK Portal...")
            ne_changed, ne_msg = _sanitize_coreconfig_name_entries()
            if ne_changed:
                log(f"  NameEntry fix: {ne_msg}")
            changed, resync_msg = _resync_ldap_credential_to_coreconfig()
            if changed:
                log(f"  LDAP resync: {resync_msg}")
            run('systemctl restart takserver 2>&1')
            log("  TAK Server restarting...")

            # Copy new certs to TAK Portal if it's running
            portal_running = _priv_pipe(['docker', 'ps', '--format', '{{.Names}}'], ['grep', '-q', 'tak-portal']).returncode == 0
            if portal_running:
                log("  Updating TAK Portal certificates...")
                # v10.0.1: delegate to _takportal_sync_certs — temp-file re-encode
                # of the client cert + CA (the old stdin pipe failed on OpenSSL 3
                # and shipped an unreadable legacy cert). restart=True.
                _tp_ok, _tp_msg = _takportal_sync_certs(plog=log, restart=True)
                log(f"  {'✓' if _tp_ok else '⚠'} TAK Portal cert sync: {_tp_msg}")
            else:
                log("  TAK Portal not running — skip cert copy (will update on next TAK Portal deploy)")

            log("  Waiting for TAK Server to come back up...")
            time.sleep(45)
            log("✓ TAK Server restarted")

            log("")
            log("━━━ ROOT CA ROTATION COMPLETE ━━━")
            log(f"  New Root CA: {new_root_name}")
            log(f"  New Intermediate CA: {new_int_name}")
            log(f"  All certificates have been regenerated")
            if portal_running:
                log(f"  TAK Portal updated — users can scan new QR codes to re-enroll")
            log(f"  All existing client connections are disconnected")
            log(f"  Clients must re-enroll via TAK Portal QR code")
            rotate_rootca_status.update({'running': False, 'complete': True, 'error': False})
        except Exception as e:
            log(f"")
            log(f"✗ ROOT CA ROTATION FAILED: {e}")
            rotate_rootca_status.update({'running': False, 'complete': True, 'error': True})

    import threading
    threading.Thread(target=do_rotate_root, daemon=True).start()
    return jsonify({'started': True, 'old_root': old_root_name, 'new_root': new_root_name})


@app.route('/api/takserver/rotate-rootca/status')
@login_required
def takserver_rotate_rootca_status():
    return jsonify({'log': rotate_rootca_log, **rotate_rootca_status})


@app.route('/api/takserver/create-client-cert', methods=['POST'])
@login_required
def takserver_create_client_cert():
    """Create a client certificate with optional group assignment."""
    data = request.json or {}
    cert_name = (data.get('name') or '').strip()
    if not cert_name:
        return jsonify({'error': 'Certificate name is required'}), 400
    import re
    if not re.match(r'^[a-zA-Z0-9._-]+$', cert_name):
        return jsonify({'error': 'Name can only contain letters, numbers, dots, hyphens, underscores'}), 400
    if len(cert_name) > 64:
        return jsonify({'error': 'Name too long (max 64 chars)'}), 400

    cert_dir = '/opt/tak/certs/files'
    if os.path.exists(os.path.join(cert_dir, f'{cert_name}.p12')):
        return jsonify({'error': f'Certificate "{cert_name}" already exists'}), 400

    def _normalize_groups(values):
        out = []
        seen = set()
        for v in (values or []):
            g = _canonical_tak_group_name(v)
            if not g:
                continue
            key = g.lower()
            if key in seen:
                continue
            seen.add(key)
            out.append(g)
        return out

    groups_in = _normalize_groups(data.get('groups_in', []))
    groups_out = _normalize_groups(data.get('groups_out', []))
    groups_both = _normalize_groups(data.get('groups_both', []))
    groups_in = [g for g in groups_in if g not in groups_both]
    groups_out = [g for g in groups_out if g not in groups_both]

    try:
        _patch_openssl_string_mask()
        if _tak_is_container():
            # container: no host `tak` user — chown tak:tak is invalid; just fix the mode (broker root)
            _run_priv_chain([['chmod', '500', '/opt/tak/certs/cert-metadata.sh']], 'and')
        else:
            _run_priv_chain([['chown', 'tak:tak', '/opt/tak/certs/cert-metadata.sh'], ['chmod', '500', '/opt/tak/certs/cert-metadata.sh']], 'and')
        r = subprocess.run(
            _rotate_tak_cert_cmd(f'cd /opt/tak/certs && runuser -u tak -- /opt/tak/certs/makeCert.sh client {cert_name} 2>&1'),
            shell=True, capture_output=True, text=True, timeout=30
        )
        if r.returncode != 0:
            return jsonify({'error': f'makeCert.sh failed: {r.stdout or r.stderr}'}), 500

        p12_path = os.path.join(cert_dir, f'{cert_name}.p12')
        if not os.path.exists(p12_path):
            return jsonify({'error': 'Certificate file was not created'}), 500

        if groups_in or groups_out or groups_both:
            pem_path = os.path.join(cert_dir, f'{cert_name}.pem')
            cmd = f'java -jar /opt/tak/utils/UserManager.jar certmod'
            for g in groups_both:
                cmd += f' -g {shlex.quote(g)}'
            for g in groups_in:
                cmd += f' -ig {shlex.quote(g)}'
            for g in groups_out:
                cmd += f' -og {shlex.quote(g)}'
            cmd += f' {shlex.quote(pem_path)}'
            # v10.0.1 container: java + UserManager.jar live ONLY inside the takserver container
            # (no host JDK), so run the group-assignment in-container; native path unchanged.
            full = _tak_exec(cmd) if _tak_is_container() else (cmd + ' 2>&1')
            gr = subprocess.run(full, shell=True, capture_output=True, text=True, timeout=15)
            if gr.returncode != 0:
                pass  # cert still created, group assignment is best-effort

        return jsonify({
            'success': True,
            'name': cert_name,
            'p12': f'{cert_name}.p12',
            'download_url': f'/api/certs/download/{cert_name}.p12',
            'groups_both': groups_both,
            'groups_in': groups_in,
            'groups_out': groups_out
        })
    except Exception as e:
        return jsonify({'error': str(e)[:200]}), 500


def _sync_webadmin_after_authentik_reconfigure(plog):
    """After Authentik reconfigure, regenerate Caddyfile and reload Caddy. Does NOT touch TAK Server or 8446 cert."""
    modules = detect_modules()
    if not modules.get('takserver', {}).get('installed'):
        return
    try:
        plog("  Syncing WebAdmin (Caddy reload only, no TAK restart)...")
        settings = load_settings()
        generate_caddyfile(settings)
        _caddy_reload()
        plog("  ✓ Caddy reloaded.")
    except Exception as e:
        plog(f"  ⚠ WebAdmin sync failed: {str(e)[:80]} — run Update config on TAK Server page if needed.")


def _run_takserver_update_config():
    """Regenerate Caddyfile, reload Caddy, re-install 8446 LE cert for current TAK Server hostname, restart TAK Server."""
    settings = load_settings()
    fqdn = settings.get('fqdn', '').strip()
    generate_caddyfile(settings)
    _caddy_reload()
    takserver_host = _get_service_domain(settings, 'takserver')
    if fqdn and takserver_host:
        caddy_active = subprocess.run(_sudo_wrap(['systemctl', 'is-active', 'caddy']), capture_output=True, text=True)
        if caddy_active.stdout.strip() == 'active':
            def _log(msg):
                print(msg, flush=True)
            install_le_cert_on_8446(takserver_host, _log, wait_for_cert=False)
    subprocess.run(_tak_systemctl('restart'), shell=True, capture_output=True, text=True, timeout=60)  # v10.0.1: container-aware
    takserver_update_config_status.update({'running': False, 'complete': True, 'error': False})

takserver_update_config_status = {'running': False, 'complete': False, 'error': False}

@app.route('/api/takserver/update-config', methods=['POST'])
@login_required
def takserver_update_config():
    """Sync Caddy + 8446 cert to current TAK Server domain and restart TAK Server. Use after changing TAK Server domain in Caddy/Domains."""
    if takserver_update_config_status.get('running'):
        return jsonify({'error': 'Update already in progress'}), 409
    modules = detect_modules()
    tak = modules.get('takserver', {})
    if not tak.get('installed'):
        return jsonify({'error': 'TAK Server not installed'}), 400
    takserver_update_config_status.update({'running': True, 'complete': False, 'error': False})
    def _run():
        try:
            _run_takserver_update_config()
        except Exception as e:
            takserver_update_config_status.update({'running': False, 'complete': True, 'error': True, 'message': str(e)[:200]})
    threading.Thread(target=_run, daemon=True).start()
    return jsonify({'success': True, 'message': 'Update config started. Caddy and 8446 cert (if applicable) will be updated; TAK Server will restart.'})

@app.route('/api/takserver/update-config/status')
@login_required
def takserver_update_config_status_api():
    return jsonify(takserver_update_config_status)

@app.route('/api/takserver/control', methods=['POST'])
@login_required
def takserver_control():
    action = request.json.get('action')
    target = request.json.get('target', 'core')  # core | database | both
    if action not in ['start', 'stop', 'restart']:
        return jsonify({'error': 'Invalid action'}), 400
    results = {}
    settings = load_settings()
    tak_cfg = _get_tak_deployment_config(settings)
    is_two_server = tak_cfg.get('mode') == 'two_server'
    # Handle remote database (Server One)
    if is_two_server and target in ('database', 'both'):
        s1 = tak_cfg.get('server_one', {})
        if s1.get('host'):
            pg_action = 'restart' if action == 'restart' else action
            db_cmd = f'sudo pg_ctlcluster 15 main {pg_action} 2>&1 || sudo systemctl {pg_action} postgresql 2>&1'
            ok, out = _ssh_probe(s1, db_cmd, timeout=30)
            verify_ok, verify_out = _ssh_probe(s1, 'pg_isready -q && echo DB_OK', timeout=10)
            db_running = verify_ok and 'DB_OK' in (verify_out or '')
            results['database'] = {'success': ok or db_running, 'running': db_running, 'host': s1['host']}
        else:
            results['database'] = {'success': False, 'error': 'Server One host not configured'}
    # Handle local TAK Server (Core)
    if target in ('core', 'both'):
        if action in ('start', 'restart'):
            ne_changed, ne_msg = _sanitize_coreconfig_name_entries()
            if ne_changed:
                results['nameentry_fix'] = ne_msg
            changed, msg = _resync_ldap_credential_to_coreconfig()
            if changed:
                results['ldap_resync'] = msg
        # v10.0.1: container-aware lifecycle — _tak_systemctl maps start/stop/
        # restart to `docker ...` in container mode (native systemctl on .deb).
        subprocess.run(_tak_systemctl(action), shell=True, capture_output=True, text=True, timeout=120)
        time.sleep(3)
        results['core'] = {'success': True, 'running': _takserver_running_local()}
    return jsonify({'success': True, 'results': results, 'action': action, 'target': target,
                    'running': results.get('core', {}).get('running', None)})

@app.route('/api/takserver/log')
@login_required
def takserver_log():
    """Tail the takserver-messaging.log file"""
    log_path = '/opt/tak/logs/takserver-messaging.log'
    offset = request.args.get('offset', 0, type=int)
    lines = request.args.get('lines', 100, type=int)
    if not os.path.exists(log_path):
        return jsonify({'entries': [], 'offset': 0, 'size': 0})
    try:
        size = os.path.getsize(log_path)
        if offset == 0:
            r = subprocess.run(f'tail -n {lines} "{log_path}"', shell=True, capture_output=True, text=True, timeout=10)
            entries = r.stdout.strip().split('\n') if r.stdout.strip() else []
            return jsonify({'entries': entries, 'offset': size, 'size': size})
        elif size > offset:
            with open(log_path, 'r') as f:
                f.seek(offset)
                new_data = f.read()
            entries = new_data.strip().split('\n') if new_data.strip() else []
            return jsonify({'entries': entries, 'offset': size, 'size': size})
        else:
            return jsonify({'entries': [], 'offset': offset, 'size': size})
    except Exception as e:
        return jsonify({'entries': [f'Error reading log: {str(e)[:200]}'], 'offset': offset, 'size': 0})

@app.route('/api/takserver/services')
@login_required
def takserver_services():
    """Get TAK Server Java process status"""
    services = []
    try:
        r = subprocess.run("ps aux | grep java | grep -v grep", shell=True, capture_output=True, text=True, timeout=10)
        seen = {}
        for line in r.stdout.strip().split('\n'):
            if not line.strip(): continue
            parts = line.split()
            if len(parts) < 11: continue
            pid = parts[1]
            cpu = parts[2]
            mem_pct = parts[3]
            rss_kb = int(parts[5])
            mem_mb = round(rss_kb / 1024)
            cmd = ' '.join(parts[10:])
            # Identify the service
            if 'profiles.active=messaging' in cmd:
                name = 'Messaging'; icon = '📡'
            elif 'profiles.active=api' in cmd:
                name = 'API'; icon = '🧩'
            elif 'profiles.active=config' in cmd:
                name = 'Config'; icon = '⚙️'
            elif 'takserver-pm.jar' in cmd:
                name = 'Plugin Manager'; icon = '🔌'
            elif 'takserver-retention.jar' in cmd:
                name = 'Retention'; icon = '📦'
            else:
                continue  # skip unknown java processes
            # Keep only one entry per service name (highest mem)
            if name not in seen or mem_mb > seen[name]['mem_mb_raw']:
                seen[name] = {
                    'name': name, 'icon': icon, 'pid': pid,
                    'cpu': f"{cpu}%", 'mem_mb': f"{mem_mb} MB",
                    'mem_pct': f"{mem_pct}%", 'status': 'running',
                    'mem_mb_raw': mem_mb
                }
        for svc in seen.values():
            del svc['mem_mb_raw']
            services.append(svc)
        # Check PostgreSQL — remote for two-server, local otherwise
        settings = load_settings()
        tak_cfg = _get_tak_deployment_config(settings)
        if tak_cfg.get('mode') == 'two_server':
            s1 = tak_cfg.get('server_one', {})
            s1_host = (s1.get('host') or '').strip()
            if s1_host:
                import socket
                db_port = int(tak_cfg.get('database', {}).get('port') or 5432)
                try:
                    s = socket.create_connection((s1_host, db_port), timeout=5)
                    s.close()
                    pg_status = 'running'
                except Exception:
                    pg_status = 'stopped'
                services.append({
                    'name': f'PostgreSQL ({s1_host})', 'icon': '🐘', 'pid': '',
                    'cpu': '', 'mem_mb': '', 'mem_pct': '',
                    'status': pg_status
                })
            else:
                services.append({
                    'name': 'PostgreSQL (remote)', 'icon': '🐘', 'pid': '',
                    'cpu': '', 'mem_mb': '', 'mem_pct': '',
                    'status': 'stopped'
                })
        elif _tak_is_container():
            # v10.0.1: single-server container deploy — PostgreSQL runs in the
            # takserver-db container, not as a host systemd service.
            pg_running = _tak_container_running(TAK_DB_CONTAINER)
            services.append({
                'name': 'PostgreSQL', 'icon': '🐘', 'pid': '',
                'cpu': '', 'mem_mb': '', 'mem_pct': '',
                'status': 'running' if pg_running else 'stopped'
            })
        else:
            # Native host PostgreSQL: Debian/Ubuntu use the unsuffixed `postgresql`
            # meta-service; RHEL/EL (PGDG) use `postgresql-<major>`. EITHER being active
            # means PG is up. Probing only `postgresql` false-reds every Rocky/RHEL
            # native box ("PostgreSQL stopped") even though postgresql-<major> is serving
            # cot fine — same EL/Debian split already handled at the deploy probe.
            pg = subprocess.run(_sudo_wrap(['systemctl', 'is-active', 'postgresql'] + list(_PG_SVC_UNITS)), capture_output=True, text=True, timeout=5)
            pg_active = 'active' in (pg.stdout or '').split()
            services.append({
                'name': 'PostgreSQL', 'icon': '🐘', 'pid': '',
                'cpu': '', 'mem_mb': '', 'mem_pct': '',
                'status': 'running' if pg_active else 'stopped'
            })
    except Exception as e:
        services.append({'name': 'Error', 'icon': '❌', 'status': str(e)[:200]})
    return jsonify({'services': services, 'count': len([s for s in services if s['status'] == 'running'])})


@app.route('/api/takserver/remote-metrics')
@login_required
def takserver_remote_metrics():
    """Return CPU/memory/disk/uptime for Server One when in two-server (remote DB) mode."""
    settings = load_settings()
    tak_cfg = _get_tak_deployment_config(settings)
    if tak_cfg.get('mode') != 'two_server':
        return jsonify({'error': 'Not two-server'}), 404
    s1 = tak_cfg.get('server_one', {})
    if not (s1.get('host') or '').strip():
        return jsonify({'error': 'No Server One host'}), 404
    metrics = _get_remote_host_metrics(s1)
    if metrics is None:
        return jsonify({'error': 'Could not fetch remote metrics'}), 503
    return jsonify(metrics)


@app.route('/api/takserver/uninstall', methods=['POST'])
@login_required
def takserver_uninstall():
    """Remove TAK Server, clean up, ready for fresh deploy"""
    data = request.json or {}
    password = data.get('password', '')
    auth = load_auth()
    if not auth.get('password_hash') or not check_password_hash(auth['password_hash'], password):
        return jsonify({'error': 'Invalid admin password'}), 403
    steps = []
    # v10.0.1: container TAK teardown FIRST. The native systemctl/apt steps below
    # are no-ops on a Docker TAK (no unit, no package) and --restart=always would
    # just respawn the containers, so do the real teardown here. Confirmed by the
    # uninstall test: native Remove left containers/volume/network/bundle behind.
    if _tak_is_container():
        for c in (TAK_CONTAINER, TAK_DB_CONTAINER):
            subprocess.run(_sudo_wrap(['docker', 'rm', '-f', c]), capture_output=True, timeout=60)
        subprocess.run(_sudo_wrap(['docker', 'volume', 'rm', TAK_DB_VOLUME]), capture_output=True, timeout=30)
        subprocess.run(_sudo_wrap(['docker', 'network', 'rm', TAK_DOCKER_NET]), capture_output=True, timeout=30)
        subprocess.run(_sudo_wrap(['rm', '-rf', TAK_DOCKER_ROOT]), capture_output=True, timeout=60)  # v10.0.1: broker rm — the host console user can't delete the root-owned in-container cert files
        # Remove the /opt/tak symlink explicitly. After ~/tak-docker is gone it is a
        # DANGLING symlink, which the native `if os.path.exists('/opt/tak')` cleanup
        # below skips (exists() follows the link → False), leaving it behind.
        subprocess.run(_sudo_wrap(['rm', '-f', '/opt/tak']), capture_output=True, timeout=10)
        # Reset the persisted method/credentials so detection falls back to the
        # platform default (arm64 still defaults to container; a redeploy re-sets it).
        try:
            _us = load_settings()
            _us.pop('tak_install_method', None)
            _us.pop('tak_db_password', None)
            save_settings(_us)
        except Exception:
            pass
        steps.append('Container TAK removed (containers, volume, network, ~/tak-docker)')
    # Stop service
    subprocess.run(_sudo_wrap(['systemctl', 'stop', 'takserver']), capture_output=True, timeout=90)
    subprocess.run(_sudo_wrap(['systemctl', 'disable', 'takserver']), capture_output=True, timeout=90)
    steps.append('Stopped TAK Server')
    # Kill any remaining processes
    subprocess.run('pkill -9 -f takserver 2>/dev/null; true', shell=True, capture_output=True)
    steps.append('Killed remaining processes')
    # Purge package — must complete BEFORE removing /opt/tak, otherwise the
    # package can remain in 'ii' state with files gone, and the next
    # `apt-get install` becomes a no-op ("already newest version") that leaves
    # a half-installed system. See deploy Step 4 self-heal for the matching
    # recovery path.
    if _distro_family() == 'rhel':
        # EL9 native: dnf remove the rpm, then drop the SELinux policy module that
        # the rpm's apply-selinux.sh loaded (else a reinstall warns it's already there).
        # IMPORTANT: clean_requirements_on_remove=False — by default `dnf remove
        # takserver` CASCADES out postgresql15 (and psql) as now-orphaned deps, which
        # runs BEFORE the cot/martiuser drop below → the drop fails (no psql) and a
        # redeploy inherits a stale martiuser with a mismatched password. Keeping
        # postgres (matches the .deb uninstall, which doesn't cascade it) lets the
        # later DROP DATABASE cot / DROP USER martiuser actually run.
        _rpm_installed = subprocess.run('rpm -q takserver 2>/dev/null', shell=True, capture_output=True, text=True).stdout.strip()
        if _rpm_installed.startswith('takserver'):
            subprocess.run(_sudo_wrap(['dnf', 'remove', '-y', '--setopt=clean_requirements_on_remove=False', 'takserver']), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=180)
            _after = subprocess.run('rpm -q takserver 2>/dev/null', shell=True, capture_output=True, text=True).stdout.strip()
            if not _after.startswith('takserver') or 'not installed' in _after.lower():
                steps.append('Removed TAK Server rpm (dnf)')
            else:
                subprocess.run('rpm -e --noscripts --nodeps takserver 2>&1', shell=True, capture_output=True, text=True, timeout=120)
                steps.append('Force-removed TAK Server rpm')
        # remove the takserver SELinux module (named takserver-policy on EL9)
        _run_priv_chain([['semodule', '-r', 'takserver-policy'], ['semodule', '-r', 'takserver']], 'seq', timeout=60)
    else:
        pkg_status = subprocess.run(
            "dpkg-query -W -f='${Status}' takserver 2>/dev/null",
            shell=True, capture_output=True, text=True
        ).stdout.strip()
        if pkg_status:
            # Try purge (apt first, then dpkg, then dpkg --force-all). Capture
            # stderr so silent failures don't pretend success.
            purge_ok = False
            for cmd in (
                'DEBIAN_FRONTEND=noninteractive apt-get purge -y takserver',
                'DEBIAN_FRONTEND=noninteractive dpkg --purge takserver',
                'DEBIAN_FRONTEND=noninteractive dpkg --purge --force-all takserver',
            ):
                r = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=180)
                after = subprocess.run(
                    "dpkg-query -W -f='${Status}' takserver 2>/dev/null",
                    shell=True, capture_output=True, text=True
                ).stdout.strip()
                if not after or 'not-installed' in after:
                    purge_ok = True
                    break
            if purge_ok:
                steps.append('Purged TAK Server package')
            else:
                steps.append('⚠ Could not purge takserver package (still registered with dpkg) — manual cleanup required')
    # Clean up /opt/tak
    if os.path.exists('/opt/tak'):
        subprocess.run(_sudo_wrap(['rm', '-rf', '/opt/tak']), capture_output=True)
        steps.append('Removed /opt/tak')
    # Clean up PostgreSQL — local or external depending on deployment mode
    settings = load_settings()
    tak_cfg = _get_tak_deployment_config(settings)
    if tak_cfg.get('mode') == 'external_db':
        # External / managed DB: use stored martiuser credentials to drop the cot database.
        # martiuser was granted azure_pg_admin (Azure) or rds_superuser (AWS) during provisioning
        # so it has permission to drop databases it doesn't own.
        edb = tak_cfg.get('external_db', {})
        edb_host = (edb.get('host') or '').strip()
        edb_port = int(edb.get('port') or 5432)
        edb_name = (edb.get('name') or 'cot').strip()
        edb_user = (edb.get('user') or 'martiuser').strip()
        edb_pass = (edb.get('password') or '').strip()
        if edb_host and edb_pass:
            env = dict(os.environ, PGPASSWORD=edb_pass)
            # Terminate active connections then drop the database
            terminate_sql = f"SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname='{edb_name}' AND pid <> pg_backend_pid();"
            drop_sql = f"DROP DATABASE IF EXISTS {edb_name};"
            for sql, label in [(terminate_sql, 'terminate connections'), (drop_sql, f'drop database {edb_name}')]:
                r = subprocess.run(
                    ['psql', '-h', edb_host, '-p', str(edb_port), '-U', edb_user,
                     '-d', 'postgres', '--no-password', '-c', sql],
                    capture_output=True, text=True, timeout=30, env=env
                )
                if r.returncode == 0:
                    steps.append(f'External DB: {label} — OK')
                else:
                    steps.append(f'External DB: {label} — {(r.stderr or r.stdout or "failed")[:120]}')
        else:
            steps.append('External DB cleanup skipped — no credentials stored (run Provision Database on next deploy)')
        # The .deb installer always creates a local martiuser + cot DB regardless of deployment
        # mode. Clean them up so re-deploys don't hit stale-password noise in the postinstall.
        subprocess.run("runuser -u postgres -- psql -c \"DROP DATABASE IF EXISTS cot WITH (FORCE);\" 2>/dev/null || runuser -u postgres -- psql -c \"DROP DATABASE IF EXISTS cot;\" 2>/dev/null; true", shell=True, capture_output=True, timeout=30)
        subprocess.run("runuser -u postgres -- psql -c \"DROP USER IF EXISTS martiuser;\" 2>/dev/null; true", shell=True, capture_output=True, timeout=30)
        steps.append('Cleaned up local PostgreSQL side-effect (cot database, martiuser)')
    else:
        # Local PostgreSQL (single-server or two-server mode)
        subprocess.run("runuser -u postgres -- psql -c \"DROP DATABASE IF EXISTS cot WITH (FORCE);\" 2>/dev/null || runuser -u postgres -- psql -c \"DROP DATABASE IF EXISTS cot;\" 2>/dev/null; true", shell=True, capture_output=True, timeout=30)
        subprocess.run("runuser -u postgres -- psql -c \"DROP USER IF EXISTS martiuser;\" 2>/dev/null; true", shell=True, capture_output=True, timeout=30)
        steps.append('Cleaned up local PostgreSQL (cot database, martiuser)')
    # Clean up GPG verification artifacts
    subprocess.run('rm -rf /usr/share/debsig/keyrings/* /etc/debsig/policies/* 2>/dev/null; true', shell=True, capture_output=True, timeout=10)
    steps.append('Cleaned up GPG verification artifacts')
    # Clean up uploads so user can upload fresh
    for f in os.listdir(UPLOAD_DIR):
        os.remove(os.path.join(UPLOAD_DIR, f))
    steps.append('Cleared uploads')
    # Reset deploy status
    deploy_log.clear()
    deploy_status.update({'running': False, 'complete': False, 'error': False})
    # Clear saved deployment config so the form is blank on next visit
    try:
        _settings = load_settings()
        td = _settings.get('tak_deployment', {})
        td['mode'] = 'single_server'
        edb = td.get('external_db', {})
        edb['host'] = ''
        edb['password'] = ''
        td['external_db'] = edb
        _settings['tak_deployment'] = td
        save_settings(_settings)
        steps.append('Cleared saved deployment config')
    except Exception as _ce:
        steps.append(f'Could not clear deployment config (non-fatal): {_ce}')
    # v0.9.31: regenerate Caddyfile so the webtak.<fqdn> vhost is removed.
    # Same gap as takportal/authentik uninstall — without this the vhost
    # remained and Caddy fell through to Authentik's "Not Found" page.
    try:
        settings = load_settings()
        generate_caddyfile(settings)
        _caddy_reload()
        steps.append('Regenerated Caddyfile + reloaded Caddy')
    except Exception as caddy_err:
        steps.append(f'Caddy regen warning (non-fatal): {caddy_err}')
    return jsonify({'success': True, 'steps': steps})

@app.route('/api/upload/takserver', methods=['POST'])
@login_required
def upload_takserver_package():
    if 'files' not in request.files:
        return jsonify({'error': 'No files uploaded'}), 400
    files = request.files.getlist('files')
    if not files or all(f.filename == '' for f in files):
        return jsonify({'error': 'No files selected'}), 400
    os_type = load_settings().get('os_type', '')
    results = {'packages': [], 'gpg_key': None, 'policy': None}
    for f in files:
        raw_name = f.filename or ''
        fn = secure_filename(raw_name)
        if not fn:
            return jsonify({'error': f'Invalid filename: {raw_name[:64]}'}), 400
        fp = os.path.join(UPLOAD_DIR, fn)
        f.save(fp)
        sz = round(os.path.getsize(fp) / (1024*1024), 1)
        # v10.0.1 platform gate: the accepted package type is fixed by arch+distro,
        # mirroring the existing .deb/.rpm cross-rejection. arm64 → docker .zip only
        # (no native arm TAK package exists); amd64 RHEL → .rpm only; amd64 Debian/
        # Ubuntu → .deb only. Reject anything else up-front so a box can't be deployed
        # with the wrong package by accident.
        _arch = _host_arch()
        _native_ext = '.rpm' if _distro_family() == 'rhel' else '.deb'
        if fn.endswith('.deb'):
            if _arch == 'arm64':
                os.remove(fp)
                return jsonify({'error': f'.deb uploaded but this arm64 box deploys TAK Server via the container path — upload the takserver-docker .zip.'}), 400
            if _distro_family() == 'rhel':
                os.remove(fp)
                return jsonify({'error': f'.deb uploaded but system is {os_type} (RHEL family). Need a takserver .rpm.'}), 400
            results['packages'].append({'filename': fn, 'filepath': fp, 'pkg_type': 'deb', 'size_mb': sz})
        elif fn.endswith('.rpm'):
            if _arch == 'arm64':
                os.remove(fp)
                return jsonify({'error': f'.rpm uploaded but this arm64 box deploys TAK Server via the container path — upload the takserver-docker .zip.'}), 400
            if _distro_family() != 'rhel':
                os.remove(fp)
                return jsonify({'error': f'.rpm uploaded but system is {os_type}. Need a takserver .deb.'}), 400
            results['packages'].append({'filename': fn, 'filepath': fp, 'pkg_type': 'rpm', 'size_mb': sz})
        elif fn.endswith('.zip') and 'docker' in fn.lower():
            # official takserver-docker-*.zip - the CONTAINER path.
            #
            # v10.2.0: amd64 may now upload this. The container path was always
            # described as "arm64, or operator-selected on amd64" (see the block
            # comment by TAK_CONTAINER) and the deploy route has always honoured an
            # explicit install_method='container' on any arch - but this validation
            # rejected the only artifact that path needs, so on amd64 it was
            # unreachable through the UI. The two now agree.
            #
            # arm64 remains container-ONLY, enforced above: .deb and .rpm are still
            # rejected there. This widens amd64; it does not loosen arm64.
            results['packages'].append({'filename': fn, 'filepath': fp, 'pkg_type': 'docker', 'size_mb': sz})
        elif fn.endswith('.key') or 'gpg' in fn.lower():
            results['gpg_key'] = {'filename': fn, 'filepath': fp, 'size_mb': sz}
        elif fn.endswith('.pol') or 'policy' in fn.lower():
            results['policy'] = {'filename': fn, 'filepath': fp, 'size_mb': sz}
    return jsonify({'success': True, **results,
        'has_verification': results['gpg_key'] is not None and results['policy'] is not None})

@app.route('/api/upload/takserver/delete', methods=['POST'])
@login_required
def delete_uploaded_file():
    fn = request.json.get('filename', '')
    import re
    if not fn or not re.match(r'^[a-zA-Z0-9._-]+$', fn):
        return jsonify({'error': 'Invalid filename'}), 400
    fp = os.path.join(UPLOAD_DIR, fn)
    if os.path.exists(fp):
        os.remove(fp)
        return jsonify({'success': True, 'filename': fn})
    return jsonify({'error': 'File not found'}), 404

@app.route('/api/upload/takserver/existing')
@login_required
def check_existing_uploads():
    """Check for files already uploaded from a previous session. Returns all .deb/.rpm as packages list (database + core both shown)."""
    files = {'packages': []}
    for fn in sorted(os.listdir(UPLOAD_DIR)):
        fp = os.path.join(UPLOAD_DIR, fn)
        if not os.path.isfile(fp):
            continue
        sz = os.path.getsize(fp)
        sz_mb = round(sz / (1024*1024), 1)
        if fn.endswith('.deb') or fn.endswith('.rpm') or (fn.endswith('.zip') and 'docker' in fn.lower()):
            files['packages'].append({'filename': fn, 'filepath': fp, 'size_mb': sz_mb})
        elif fn.endswith('.key') or 'gpg' in fn.lower():
            files['gpg_key'] = {'filename': fn, 'filepath': fp, 'size_mb': sz_mb}
        elif fn.endswith('.pol') or 'policy' in fn.lower():
            files['policy'] = {'filename': fn, 'filepath': fp, 'size_mb': sz_mb}
    return jsonify(files)


@app.route('/api/upload/fedhub', methods=['POST'])
@login_required
def upload_fedhub_package():
    if 'files' not in request.files:
        return jsonify({'error': 'No files uploaded'}), 400
    files = request.files.getlist('files')
    if not files or all((f.filename or '') == '' for f in files):
        return jsonify({'error': 'No files selected'}), 400
    results = []
    for f in files:
        raw_name = f.filename or ''
        fn = secure_filename(raw_name)
        if not fn:
            return jsonify({'error': f'Invalid filename: {raw_name[:64]}'}), 400
        if not fn.endswith('.deb'):
            return jsonify({'error': 'Federation Hub upload must be a .deb file'}), 400
        fp = os.path.join(UPLOAD_DIR, fn)
        f.save(fp)
        ok_m, err = _validate_fedhub_deb_path(fp)
        if not ok_m:
            try:
                os.remove(fp)
            except OSError:
                pass
            return jsonify({'error': err}), 400
        sz = round(os.path.getsize(fp) / (1024 * 1024), 1)
        results.append({'filename': fn, 'size_mb': sz})
    return jsonify({'success': True, 'packages': results})


@app.route('/api/upload/fedhub/delete', methods=['POST'])
@login_required
def delete_fedhub_upload():
    fn = (request.json or {}).get('filename', '')
    if not fn or not re.match(r'^[a-zA-Z0-9._-]+$', fn):
        return jsonify({'error': 'Invalid filename'}), 400
    fp = os.path.join(UPLOAD_DIR, fn)
    if os.path.isfile(fp):
        ok_m, _ = _validate_fedhub_deb_path(fp)
        if not ok_m:
            return jsonify({'error': 'File is not a recognized Federation Hub package'}), 400
        os.remove(fp)
