@app.route('/api/takserver/security-config')
@login_required
def takserver_security_config_get():
    """Read issued cert validity (validityDays) from CoreConfig TAKServerCAConfig. Lets you change it anytime (e.g. 90 days = re-enroll by scanning QR)."""
    coreconfig_path = '/opt/tak/CoreConfig.xml'
    if not os.path.exists(coreconfig_path):
        return jsonify({'error': 'TAK Server not installed'}), 400
    try:
        r = subprocess.run(_sudo_wrap(['cat', coreconfig_path]), capture_output=True, text=True, timeout=5)
        if r.returncode != 0:
            return jsonify({'error': 'Could not read CoreConfig.xml'}), 500
        content = r.stdout or ''
    except Exception as e:
        return jsonify({'error': str(e)[:200]}), 500
    import re
    m = re.search(r'<TAKServerCAConfig[^>]*validityDays="(\d+)"', content)
    validity_days = int(m.group(1)) if m else 3650
    return jsonify({'validity_days': validity_days})


@app.route('/api/takserver/security-config', methods=['POST'])
@login_required
def takserver_security_config_post():
    """Update issued cert validity (validityDays) in CoreConfig and restart TAK Server. E.g. set to 90 to force re-enrollment (scan QR again); or rotate CA / revoke client cert from TAK Server."""
    data = request.get_json() or {}
    try:
        validity_days = int(data.get('validity_days', 0))
        if validity_days < 1 or validity_days > 3652:
            return jsonify({'error': 'validity_days must be between 1 and 3652'}), 400
    except (TypeError, ValueError):
        return jsonify({'error': 'validity_days must be a number'}), 400
    coreconfig_path = '/opt/tak/CoreConfig.xml'
    if not os.path.exists(coreconfig_path):
        return jsonify({'error': 'TAK Server not installed'}), 400
    try:
        r = subprocess.run(_sudo_wrap(['cat', coreconfig_path]), capture_output=True, text=True, timeout=5)
        if r.returncode != 0:
            return jsonify({'error': 'Could not read CoreConfig.xml'}), 500
        content = r.stdout or ''
    except Exception as e:
        return jsonify({'error': str(e)[:200]}), 500
    import re
    if not re.search(r'<TAKServerCAConfig[^>]*validityDays="\d+"', content):
        return jsonify({'error': 'TAKServerCAConfig / validityDays not found in CoreConfig (certificate enrollment may not be enabled)'}), 400
    new_content = re.sub(r'(<TAKServerCAConfig[^>]*validityDays=")\d+(")', rf'\g<1>{validity_days}\g<2>', content, count=1)
    if new_content == content:
        return jsonify({'error': 'No change applied'}), 400
    try:
        _write_priv(coreconfig_path, new_content)  # v10.0.5 non-root: broker write (literal `sudo tee` bypassed the broker)
    except Exception as e:
        return jsonify({'error': str(e)[:200]}), 500
    subprocess.run(_tak_systemctl('restart'), shell=True, capture_output=True, timeout=90)  # v10.0.1: container-aware
    return jsonify({'success': True, 'validity_days': validity_days, 'message': f'Issued cert validity set to {validity_days} days. TAK Server restarted.'})


# ── TAK 5.8 pre-flight (v10.2.0 W2) ─────────────────────────────────────────
# READ-ONLY. Mirrors the gates `upgrade-db.sh` enforces internally, but BEFORE
# anything is touched, so the operator gets a useful refusal instead of a
# mid-flight abort that leaves TAK wedged between the package install and the DB
# migration (UPSTREAM-TAK-5.8-RELEASE-NOTES.md §1.1, §3.2a).
#
# Three of these mirror the vendor script; two are ours because the vendor's own
# equivalents are absent or broken:
#   * it takes NO backup — rollback rests entirely on the 15 cluster surviving,
#     which is only true if disk holds both. Hence the 1.5x disk gate matters
#     more to us than to it.
#   * its Debian cluster check (lines 71-76) tests $? after a backtick assignment
#     so it reflects the assignment, not pg_lsclusters, and only echoes — never
#     exits. It is not the safety check it appears to be. We do our own.
#
# cot_router.id is inspected LIVE and never inferred from the TAK version:
# measured 2026-09-01, test6 and test12 both run 5.7-RELEASE8 yet hold `integer`
# and `bigint` respectively. Whether a box pays for SchemaManager's full-table PK
# rewrite is a property of that box's history, not of its version string.
_TAK58_MIN_DISK_RATIO = 1.5          # upgrade-db.sh exits 1 below this


_tak58_pf_cache = {'at': 0, 'data': None}


def _tak_58_preflight_cached(max_age=60):
    """Cached pre-flight for page RENDERS.

    The real check shells out to `du -sb` on the PostgreSQL data directory, which on
    a multi-GB database is slow enough to stall a page load. The TAK Server page
    renders this on every visit, so it reads through a short cache; the migration
    itself always calls _tak_58_preflight() directly and never a cached verdict.
    """
    now = time.time()
    if _tak58_pf_cache['data'] is not None and (now - _tak58_pf_cache['at']) < max_age:
        return _tak58_pf_cache['data']
    try:
        d = _tak_58_preflight()
    except Exception:
        return _tak58_pf_cache['data']
    _tak58_pf_cache.update({'at': now, 'data': d})
    return d


def _tak_58_preflight():
    """Read-only readiness for the 5.8 + PG18 migration.

    Returns {'ready': bool, 'blockers': [str], 'warnings': [str], 'facts': {...}}.
    Never mutates anything. Safe to call on every page render.
    """
    facts, blockers, warnings = {}, [], []

    def _sh(argv, timeout=20):
        try:
            return subprocess.run(_sudo_wrap(argv), capture_output=True, text=True, timeout=timeout)
        except Exception:
            return None

    def _sql(q, db='cot', timeout=20):
        try:
            r = _pg_exec(['psql', '-tAX', '-d', db, '-c', q], timeout=timeout)
            return (r.stdout or '').strip() if r and r.returncode == 0 else None
        except Exception:
            return None

    # 1. Topology — D4 is open; container and remote DBs are out of 10.2.0 scope.
    try:
        mode, db_host, _db_port = _tak_db_topology()
    except Exception:
        mode, db_host = 'local', 'localhost'
    facts['db_mode'] = mode
    if mode == 'container':
        blockers.append('TAK runs its database in a container — the 5.8 guided migration '
                        'covers native host PostgreSQL only in this release.')
    elif mode == 'remote':
        blockers.append('The CoT database is on a remote host (%s). The 5.8 migration must be '
                        'run there, not from this console, in this release.' % (db_host or 'unknown'))

    # 2. Which major is actually serving, and is 15 present at all?
    #    upgrade-db.sh exits 1 with "Upgrade will be skipped" if no 15 cluster exists.
    running_major = None
    sv = _sql('SHOW server_version_num;', db='postgres')
    if sv and sv.isdigit():
        running_major = int(sv) // 10000
    facts['pg_running_major'] = running_major
    if running_major is None:
        blockers.append('Could not determine the running PostgreSQL version — is the database up?')
    elif running_major >= TAK_PG_MAJOR:
        facts['already_migrated'] = True
    elif running_major != 15:
        blockers.append('PostgreSQL %s is running. TAK 5.8 migrates from 15 only; upgrade-db.sh '
                        'refuses anything else.' % running_major)

    # 3. Our own cluster check (the vendor's is broken — see header).
    lsc = _sh(['pg_lsclusters', '--no-header'])
    if lsc and lsc.returncode == 0:
        rows = [l.split() for l in (lsc.stdout or '').splitlines() if l.strip()]
        facts['clusters'] = ['%s/%s %s' % (r[0], r[1], r[3]) for r in rows if len(r) > 3]
        if running_major == 15 and not any(r and r[0] == '15' for r in rows):
            blockers.append('No PostgreSQL 15 cluster found — upgrade-db.sh will refuse.')

    # 4. Disk: the new cluster needs 1.5x the old data dir, on ITS partition.
    datadir = _sql('SHOW data_directory;', db='postgres')
    facts['data_directory'] = datadir
    if datadir:
        du = _sh(['du', '-sb', datadir], timeout=120)
        target_parent = '/var/lib/pgsql' if datadir.startswith('/var/lib/pgsql') else '/var/lib/postgresql'
        df = _sh(['df', '-B1', '--output=avail', target_parent], timeout=20)
        try:
            used = int((du.stdout or '').split()[0])
            avail = int((df.stdout or '').splitlines()[-1].strip())
            need = int(used * _TAK58_MIN_DISK_RATIO)
            facts['data_bytes'], facts['avail_bytes'], facts['need_bytes'] = used, avail, need
            if avail < need:
                blockers.append(
                    'Not enough disk for a rollback-safe migration: %s free on %s, %s needed '
                    '(1.5x the %s database). pg_upgrade runs in copy mode so the PostgreSQL 15 '
                    'cluster survives — that is the only way back if the upgrade fails.'
                    % (_cotdb_fmt_bytes(avail), target_parent, _cotdb_fmt_bytes(need), _cotdb_fmt_bytes(used)))
        except Exception:
            warnings.append('Could not measure free disk space for the new cluster — verify by hand.')

    # 5. The conditional expensive bit: cot_router's PK type and size.
    if mode == 'local' and running_major:
        idtype = _sql("SELECT data_type FROM information_schema.columns "
                      "WHERE table_name = 'cot_router' AND column_name = 'id';")
        facts['cot_router_id_type'] = idtype or None
        rows_s = _sql('SELECT count(*) FROM cot_router;', timeout=120)
        try:
            facts['cot_router_rows'] = int(rows_s) if rows_s else None
        except Exception:
            facts['cot_router_rows'] = None
        # MEASURED 2026-09-01 on a 5,000,004-row / 8.1 GB box, and it corrected the plan:
        # 5.8 does NOT widen cot_router.id. The actual migration is
        # V101__update_cot_router_chat_id_to_bigint.sql — the CHAT table, which is
        # typically empty (0 rows here, 18 ms). The release notes' "cot_router.id
        # integer -> bigint" does not happen: after a full 5.8 migration this box
        # still reported cot_router.id = integer.
        #
        # So there is no expensive full-table rewrite, and warning about one was
        # wrong. What IS true, and worth telling an operator, is the opposite: a box
        # old enough to still have `integer` KEEPS it. Newer TAK installs create the
        # column as bigint (dev-4 on 5.7-RELEASE43 and test12 both did; test6 did
        # not), and 5.8 ships no migration to fix the old ones — so the 2.1-billion
        # ceiling those boxes carry is not lifted by upgrading. That is an upstream
        # gap, not something this release can fix, and it is not a reason to block.
        if idtype == 'integer':
            facts['pk_rewrite_expected'] = False
            facts['cot_router_id_stays_integer'] = True
            warnings.append(
                'This database has cot_router.id as integer. TAK 5.8 does not widen it — its '
                'schema update only widens cot_router_chat.id — so the column keeps its '
                '2,147,483,647 row-id ceiling after the upgrade. Nothing to do now; worth '
                'raising with TAK for boxes with long histories.')
        elif idtype == 'bigint':
            facts['pk_rewrite_expected'] = False
            facts['cot_router_id_stays_integer'] = False

    facts['pg_target_major'] = TAK_PG_MAJOR
    # Pre-formatted for the template — Jinja should not be doing byte math.
    facts['data_human'] = _cotdb_fmt_bytes(facts.get('data_bytes') or 0)
    facts['avail_human'] = _cotdb_fmt_bytes(facts.get('avail_bytes') or 0)
    facts['need_human'] = _cotdb_fmt_bytes(facts.get('need_bytes') or 0)
    return {'ready': not blockers, 'blockers': blockers, 'warnings': warnings, 'facts': facts}


@app.route('/api/takserver/58-preflight')
@login_required
def takserver_58_preflight():
    """Read-only 5.8/PG18 readiness. Drives the upgrade card; W4 refuses on `ready`."""
    try:
        return jsonify({'ok': True, **_tak_58_preflight()})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)[:300]}), 500


# ── TAK 5.8 pre-migration backup (v10.2.0 W3) ───────────────────────────────
# `upgrade-db.sh` takes NO backup — no dump, no snapshot. Its whole rollback story
# is "the PostgreSQL 15 cluster is left intact", which is true on both families but
# only helps if disk held both (W2's 1.5x gate) and covers only the database, not
# CoreConfig or certs.
#
# So the backup is ours. It does NOT reinvent one: `_tak_snapshot()` already
# captures TAK version, CoreConfig.xml, UserAuthenticationFile.xml,
# /etc/default/takserver, the cot dump and /opt/tak/certs/files/, and it already
# handles all three topologies (local, two_server, external_db). This wrapper adds
# the one thing it does not do — PROVING the dump is readable.
#
# `_tak_snapshot` sets meta['db_dump'] only when a non-empty file lands. Non-empty
# is not restorable: a truncated archive has bytes and fails to restore. Since this
# dump is the only thing standing between an operator and an unrecoverable 5.8
# migration, "it has bytes" is not a standard worth shipping. `pg_restore --list`
# parses the archive's table of contents, so truncation and corruption both fail it.
# Reporting a success we had not established is the fault the whole v10.1.40 release
# was about; this is the same fault with a database attached.


def _tak_58_backup(plog=None):
    """Snapshot before the 5.8 migration, then PROVE the cot dump reads.

    Returns {'ok', 'label', 'snapshot_path', 'dump_path', 'dump_bytes',
             'toc_entries', 'error'}. `ok` is True only when pg_restore parsed the
    archive — never merely because pg_dump exited 0.
    """
    if plog is None:
        plog = lambda m: print(m, flush=True)

    label = 'pre-58-%s' % time.strftime('%Y%m%d-%H%M%S')
    out = {'ok': False, 'label': label,
           'snapshot_path': os.path.join(SNAPSHOT_DIR, label),
           'dump_path': None, 'dump_bytes': 0, 'toc_entries': 0, 'error': None}

    ok, meta = _tak_snapshot(label, plog=plog)
    if not ok:
        out['error'] = 'snapshot failed: %s' % str(meta)[:300]
        plog('BACKUP FAILED — %s' % out['error'])
        return out

    # The snapshot can succeed overall while deliberately skipping the DB dump
    # (external_db with no pg_dump client, for one). For a migration backup that
    # is a hard stop, not a warning — the database is the irreplaceable part.
    if not (isinstance(meta, dict) and meta.get('db_dump')):
        out['error'] = ('the snapshot completed but captured NO database dump — refusing to '
                        'treat that as a pre-migration backup.')
        plog('BACKUP FAILED — %s' % out['error'])
        return out

    dump_path = os.path.join(out['snapshot_path'], 'cot.pgdump')
    out['dump_path'] = dump_path
    try:
        st = subprocess.run(_sudo_wrap(['stat', '-c', '%s', dump_path]),
                            capture_output=True, text=True, timeout=20)
        out['dump_bytes'] = int((st.stdout or '0').strip() or 0)
    except Exception:
        out['dump_bytes'] = 0

    # Prove it reads. This is the entire point of the wrapper.
    #
    # It must go through the broker, not `runuser -u postgres -- pg_restore`: the
    # broker writes dumps root-owned 0600, so postgres gets EACCES on its own
    # snapshot. Found the hard way on dev-4 — the migration correctly refused to
    # proceed, but on a permissions bug rather than a real corruption. Reading a
    # TOC needs no database, so the broker does it as root, and its HMAC sidecar
    # check runs first: bytes intact AND archive well-formed.
    plog('  verifying the backup is restorable (pg_restore --list)…')
    try:
        r = _broker_request({'op': 'pg_restore', 'path': dump_path,
                             'list_only': True, 'timeout': 600}, timeout=660)
        if not r.get('ok') or not r.get('toc_entries'):
            out['error'] = ('backup verification FAILED — could not read the archive (%s). '
                            'Do not proceed with the migration.'
                            % (str(r.get('error') or '').strip()[:200] or 'empty table of contents'))
            plog(out['error'])
            return out
        out['toc_entries'] = int(r.get('toc_entries') or 0)
    except Exception as e:
        out['error'] = 'backup verification FAILED: %s' % str(e)[:300]
        plog(out['error'])
        return out

    out['ok'] = True
    plog('  backup verified: %s, %d objects in the archive (%s)'
         % (_cotdb_fmt_bytes(out['dump_bytes']), out['toc_entries'], out['snapshot_path']))
    return out


# ── TAK 5.8 guided migration (v10.2.0 W4) ───────────────────────────────────
# ONE operation, deliberately. The 5.8 package detects PG 15 and REFUSES to
# finish, printing "Please manually run sudo /opt/tak/db-utils/upgrade-db.sh".
# Between that refusal and the DB script completing, the box is a broken server:
# package installed, schema not migrated, TAK down. An operator who does the
# first half by hand and stops there has an outage and no obvious way back.
#
# So there is NO button that performs half of this. The route below runs
# pre-flight → backup → stop → install → upgrade-db.sh → start → verify, and if
# it fails after the package landed it says so in those words and names the two
# ways out. That single property is the reason this release exists; the version
# gate (below) is only holding the fleet safe until it shipped.
#
# D1 (operator, 2026-09-01): call `upgrade-db.sh` BARE on both families — TAK's
# supported path, rather than owning a migration we deviated from.
#
# The two costs that decision accepted are GONE as of 5.8-RELEASE75, verified by
# extracting the script from the .deb on 2026-09-01: TAK now calls
# `pg_upgradecluster -m upgrade 15 main` (lines 133/135). In RELEASE65 — which
# UPSTREAM-TAK-5.8-RELEASE-NOTES.md analysed — the `-m` was absent, so Debian's
# default `dump` method applied: a full dump/reload (hours) AND, because
# pg_upgradecluster only passes --no-data-checksums when method eq 'upgrade',
# data page checksums ON for Ubuntu vs OFF for RHEL. With `-m upgrade` both are
# fixed upstream: file-level migration, checksums off, platforms uniform.
#
# Keep verifying this per release rather than trusting it — it changed once
# already, and our estimates and our honesty about downtime both depend on it.
tak58_log = []
tak58_status = {'running': False, 'complete': False, 'error': False}

_TAK58_UPGRADE_DB_SH = '/opt/tak/db-utils/upgrade-db.sh'


def _tak58_log(msg):
    tak58_log.append(msg)


# ── 5.8 schema verification + the EL md5->scram heal (v10.2.0) ──────────────
# `upgrade-db.sh` exits 0 and prints "Database updated with SchemaManager.jar"
# EVEN WHEN SchemaManager failed. Measured on Rocky 9.8, 2026-09-03: SchemaManager
# logged `FATAL: password authentication failed for user "martiuser"`, the script
# still exited 0, and the console reported "Migration complete" over a database
# still on schema_version 99. TAK Server 5.8 was left running against a 5.7 schema
# — a broken server that reports healthy.
#
# So the exit code is not evidence. We ask the database instead.
_TAK58_MIN_SCHEMA_VERSION = 100     # V100 adds flow_tags/username to cot_router


def _tak58_schema_version():
    """Highest successfully-applied TAK schema version, or None if unreadable."""
    try:
        r = _pg_exec(['psql', '-tAX', '-d', 'cot', '-c',
                      'select coalesce(max(version::int), 0) from schema_version where success'],
                     timeout=60)
        if r and r.returncode == 0 and (r.stdout or '').strip().isdigit():
            return int(r.stdout.strip())
    except Exception:
        pass
    return None


def _tak58_heal_md5_scram(say):
    """Re-hash the TAK DB password under scram-sha-256, then re-run TAK's schema setup.

    ROOT CAUSE (EL only, measured on Rocky 9.8 2026-09-03): TAK's 5.8 package installs
    a pg_hba.conf demanding `scram-sha-256`, but `pg_upgrade` carries the old cluster's
    password over as an **md5 hash**, and an md5 hash cannot satisfy scram — there is no
    way to derive a scram verifier from it. So martiuser cannot authenticate to the new
    cluster and SchemaManager silently fails. Debian escapes this because
    `pg_upgradecluster` keeps the old cluster's pg_hba (md5), so nothing changes.

    Re-issuing ALTER USER ... PASSWORD with password_encryption=scram-sha-256 stores a
    scram verifier for the SAME password, which is why this needs no new credential and
    changes nothing the operator has to know about. The password is read from CoreConfig
    and never logged.
    """
    try:
        cc = _read_coreconfig() or ''
    except Exception:
        cc = ''
    m = re.search(r'<connection[^>]*password="([^"]+)"', cc)
    if not m:
        say('  Could not read the database password from CoreConfig.xml — cannot repair '
            'authentication automatically.')
        return False
    pw = m.group(1)
    say('  The new cluster requires scram-sha-256 but the migrated password is an md5 hash, '
        'so TAK could not authenticate to update the schema. Re-encoding the same password '
        'under scram-sha-256…')
    try:
        # Console-authored SQL only. The password is parameterised through psql's own
        # quoting via a dollar-quoted literal chosen not to collide with the value.
        tag = '$tak58pw$'
        if tag.strip('$') in pw:
            say('  Password contains the quoting tag — refusing to build this statement.')
            return False
        r = _pg_exec(['psql', '-q', '-d', 'postgres', '-c',
                      "SET password_encryption = 'scram-sha-256'; "
                      "ALTER USER martiuser PASSWORD %s%s%s;" % (tag, pw, tag)], timeout=60)
        if not r or r.returncode != 0:
            say('  Could not re-encode the password: %s'
                % ((getattr(r, 'stderr', '') or '').strip()[:200]))
            return False
    except Exception as e:
        say('  Could not re-encode the password: %s' % str(e)[:200])
        return False
    say('  Re-running TAK\'s database setup…')
    rc = _tak58_run_setup_db()
    if rc != 0:
        say('  TAK database setup returned %d after the password repair.' % rc)
    return True


def _tak58_run_setup_db(timeout_sec=3600):
    """Run TAK's takserver-setup-db.sh (which runs SchemaManager). Returns exit code."""
    script = '/opt/tak/db-utils/takserver-setup-db.sh'
    if not os.path.exists(script):
        return 127
    if _broker_should_route() and _broker_available():
        try:
            resp = _broker_request({'op': 'tak58_setup_db', 'timeout': timeout_sec},
                                   timeout=timeout_sec + 60)
            return int(resp.get('returncode') or (0 if resp.get('ok') else 1))
        except Exception:
            return 1
    r = subprocess.run(_sudo_wrap(['sh', script]), capture_output=True, text=True,
                       timeout=timeout_sec)
    return r.returncode


# -- 5.8 container migration: export/import between two live DB containers ---
# TAK documents the container upgrade as an export/import, NOT an in-place
# migration (docker/README_hardened_docker.md, "postgres database version
# upgrades"). The old container is the only one with /usr/pgsql-15/bin/psql, so it
# must stay alive to export from; the new one must already carry the 5.8 schema
# (its init runs SchemaManager) because the dump is --data-only.
#
# `--column-inserts` is row-by-row and far slower than the native pg_upgrade path.
# The native 142 s / 181 s figures do NOT transfer here - container downtime is its
# own measurement.
_TAK58_EXPORT_NAME = 'cot_data.sql'


def _tak58_db_password():
    """The cot DB password from CoreConfig, or None. Never logged."""
    try:
        m = re.search(r'<connection[^>]*password="([^"]+)"', _read_coreconfig() or '')
        return m.group(1) if m else None
    except Exception:
        return None


def _tak58_container_pgbin(container, major):
    """Path to psql for `major` inside `container`, or None if absent."""
    r = subprocess.run(_sudo_wrap(['docker', 'exec', container,
                                   'test', '-x', f'/usr/pgsql-{major}/bin/psql']),
                       capture_output=True, timeout=60)
    return f'/usr/pgsql-{major}/bin/psql' if r.returncode == 0 else None


def _tak58_container_counts(container, pgbin, pw):
    """{table: rowcount} for the cot DB inside `container`, or None.

    Used to PROVE an import landed. A psql exit code of 0 says the file was read,
    not that the rows arrived - the same distinction that hid a failed SchemaManager
    behind upgrade-db.sh's exit 0 on the native path.
    """
    sql = ("select relname||' '||n_live_tup from pg_stat_user_tables "
           "where n_live_tup > 0 order by relname")
    try:
        r = subprocess.run(_sudo_wrap([
            'docker', 'exec', '-e', f'PGPASSWORD={pw}', container,
            pgbin, '-h', 'localhost', '-U', 'martiuser', '-d', 'cot', '-tAc', sql]),
            capture_output=True, text=True, timeout=300)
        if r.returncode != 0:
            return None
        out = {}
        for line in (r.stdout or '').splitlines():
            parts = line.strip().split()
            if len(parts) == 2 and parts[1].isdigit():
                out[parts[0]] = int(parts[1])
        return out
    except Exception:
        return None


def _tak58_container_export(container, dest_path, pw, say):
    """Export cot data from the OLD container. Returns bytes written, or 0 on failure.

    Verified, not assumed: an export that produces a file with no INSERT statements
    is a failure even though psql exited 0.
    """
    pgbin = _tak58_container_pgbin(container, 15)
    if not pgbin:
        say(f'  {container} has no PostgreSQL 15 client — cannot export from it.')
        return 0
    say(f'  Exporting the database from {container} (row-by-row; this is the slow part)…')
    try:
        _makedirs_priv(os.path.dirname(dest_path))
    except Exception:
        pass
    cmd = (f"docker exec -e PGPASSWORD={shlex.quote(pw)} {shlex.quote(container)} "
           f"{shlex.quote(pgbin)} -h localhost -U martiuser -d cot "
           f"--data-only --column-inserts --disable-triggers")
    try:
        with open(dest_path, 'wb') as fh:
            proc = subprocess.run(_sudo_wrap(['sh', '-c', cmd]), stdout=fh,
                                  stderr=subprocess.PIPE, timeout=6 * 3600)
        if proc.returncode != 0:
            say(f'  Export failed: {(proc.stderr or b"").decode(errors="replace")[:200]}')
            return 0
        size = os.path.getsize(dest_path)
    except Exception as e:
        say(f'  Export failed: {str(e)[:200]}')
        return 0
    if size <= 0:
        say('  Export produced an empty file — refusing to treat that as a backup.')
        return 0
    try:
        g = subprocess.run(_sudo_wrap(['grep', '-c', '^INSERT INTO', dest_path]),
                           capture_output=True, text=True, timeout=300)
        inserts = int((g.stdout or '0').strip() or 0)
    except Exception:
        inserts = -1
    if inserts == 0:
        say('  Export contains no INSERT statements — the database looked empty. '
            'Refusing to continue on an export that captured nothing.')
        return 0
    say(f'  Exported {_cotdb_fmt_bytes(size)}'
        + (f', {inserts:,} INSERT statements' if inserts > 0 else ''))
    return size


def _tak58_container_import(container, src_path, pw, say):
    """Import the export into the NEW container. Returns True only if rows landed."""
    pgbin = _tak58_container_pgbin(container, TAK_PG_MAJOR)
    if not pgbin:
        say(f'  {container} has no PostgreSQL {TAK_PG_MAJOR} client — cannot import into it.')
        return False
    say(f'  Copying the export into {container}…')
    r = subprocess.run(_sudo_wrap(['docker', 'cp', src_path,
                                   f'{container}:/tmp/{_TAK58_EXPORT_NAME}']),
                       capture_output=True, text=True, timeout=3600)
    if r.returncode != 0:
        say(f'  Copy into the container failed: {(r.stderr or "").strip()[:200]}')
        return False
    say('  Importing (row-by-row — allow a long window on a large database)…')
    r = subprocess.run(_sudo_wrap([
        'docker', 'exec', '-e', f'PGPASSWORD={pw}', container,
        pgbin, '-h', 'localhost', '-U', 'martiuser', '-d', 'cot',
        '-f', f'/tmp/{_TAK58_EXPORT_NAME}']), capture_output=True, text=True,
        timeout=12 * 3600)
    if r.returncode != 0:
        say(f'  Import failed: {(r.stderr or "").strip()[:300]}')
        return False
    return True


def _tak58_run_upgrade_db(timeout_sec=6 * 3600, log=None):
    """Run the vendor's upgrade-db.sh and stream it. Returns its exit code.

    EVERY box in the fleet runs the console as `takwerx`, so every box takes the
    broker path — the direct branch below is only reached on root-era installs.
    The broker enforces EXEC_ALLOW and `upgrade-db.sh` is deliberately NOT on it;
    a generic "run any script" allowance would be a hole. Instead W4b adds a
    dedicated op bounded to that one fixed path, the shape `pg_dump` already uses.
    """
    _L = (log if log is not None else tak58_log).append

    if _broker_should_route() and _broker_available():
        # W4b: dedicated broker op, bounded to that one fixed path — no argv, no
        # cwd, and the broker re-checks root-ownership and write permissions at
        # call time before running it. The op is synchronous and returns the full
        # combined output at the end, so nothing streams during the migration;
        # the operator is told to expect that rather than left watching a dead log.
        _L('  Running the migration through the privilege broker. Output arrives when it')
        _L('  finishes — on a large database this can be hours with no visible progress.')
        try:
            resp = _broker_request({'op': 'tak58_upgrade_db', 'timeout': timeout_sec},
                                   timeout=timeout_sec + 60)
        except Exception as e:
            _L('  Broker call failed: %s' % str(e)[:300])
            return 1
        for line in (resp.get('output') or '').splitlines():
            _L('  ' + line)
        if not resp.get('ok') and resp.get('error'):
            _L('  %s' % str(resp.get('error'))[:300])
        return int(resp.get('returncode') or (0 if resp.get('ok') else 1))
    argv = _sudo_wrap(['sh', _TAK58_UPGRADE_DB_SH])
    proc = subprocess.Popen(argv, cwd='/', stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT, text=True, bufsize=1)
    if proc.stdout is None:
        return 1

    def _drain():
        # No shebang + bashisms mean dash emits noise on Ubuntu while the script
        # still works. Noise is not failure — only the exit code decides.
        for line in iter(proc.stdout.readline, ''):
            if line:
                _L('  ' + line.rstrip('\n'))

    t = threading.Thread(target=_drain, daemon=True)
    t.start()
    try:
        proc.wait(timeout=timeout_sec)
    except subprocess.TimeoutExpired:
        proc.kill()
        t.join(timeout=5)
        raise
    t.join(timeout=5)
    return proc.returncode if proc.returncode is not None else 1


def run_takserver_58_migration(pkg_path, log=None, status=None):
    """Worker: the whole 5.8 + PG18 migration as one indivisible operation.

    `log`/`status` let the normal Update button drive this into the log panel the
    TAK Server page already polls, instead of a second stream the user would have
    to know about. Defaults keep the standalone API route working.
    """
    _log = tak58_log if log is None else log
    _status = tak58_status if status is None else status
    def _say(m):
        _log.append(m)

    def fail(msg, wedged=False):
        _say(msg)
        if wedged:
            _say('')
            _say('*** THIS SERVER IS MID-UPGRADE AND TAK IS NOT RUNNING. ***')
            _say('The 5.8 package is installed but the database migration did not complete.')
            _say('Two ways forward, in order of preference:')
            _say('  1. Re-run the database migration:  sudo %s' % _TAK58_UPGRADE_DB_SH)
            _say('  2. Restore from the pre-migration backup taken at the start of this run')
            _say('     (see the snapshot path above). The PostgreSQL 15 cluster was left')
            _say('     intact by design and is still on disk.')
        _status.update({'running': False, 'complete': True, 'error': True})

    try:
        # 1. Pre-flight — refuse before touching anything.
        _say('Checking this server is ready to migrate…')
        pf = _tak_58_preflight()
        for w in pf.get('warnings', []):
            _say('  NOTE: %s' % w)
        if not pf.get('ready'):
            for b in pf.get('blockers', []):
                _say('  BLOCKED: %s' % b)
            return fail('Pre-flight failed — nothing was changed on this server.')
        f = pf.get('facts', {})
        _say('  PostgreSQL %s → %s, database %s, %s free.'
                   % (f.get('pg_running_major'), f.get('pg_target_major'),
                      _cotdb_fmt_bytes(f.get('data_bytes') or 0),
                      _cotdb_fmt_bytes(f.get('avail_bytes') or 0)))
        if f.get('pk_rewrite_expected'):
            _say('  This database still has cot_router.id as integer, so the 5.8 schema '
                       'update will rewrite that table in full. Expect a long window.')

        # 2. Backup — verified, not assumed. Refuse to continue without one.
        _say('')
        _say('Backing up before anything is changed…')
        bk = _tak_58_backup(plog=_tak58_log)
        if not bk.get('ok'):
            return fail('Backup failed — refusing to migrate without one. %s'
                        % (bk.get('error') or ''))
        _say('  Backup: %s' % bk.get('snapshot_path'))

        # 3. Stop TAK.
        _say('')
        _say('Stopping TAK Server…')
        subprocess.run(_sudo_wrap(['systemctl', 'stop', 'takserver']),
                       capture_output=True, timeout=300)

        # 4. Install the 5.8 package. After this line the box is mid-upgrade.
        _say('Installing %s …' % os.path.basename(pkg_path))
        if _distro_family() == 'rhel':
            cmd = 'dnf -y install ' + shlex.quote(pkg_path) + ' 2>&1'
        else:
            cmd = ('DEBIAN_FRONTEND=noninteractive apt-get install -y --allow-downgrades '
                   + shlex.quote(pkg_path) + ' 2>&1')
        rc = _tak_upgrade_apt_install_streamed(cmd, os.path.dirname(pkg_path) or '/tmp',
                                               tak58_log, timeout_sec=1800)
        # The package is EXPECTED to complain about pg15 and stop short — that is
        # the documented 5.8 behaviour, not an install failure. The database
        # script below is what finishes it, so a non-zero rc here is reported and
        # then superseded by whether upgrade-db.sh succeeds.
        if rc != 0:
            _say('  The package installer stopped short (exit %d). This is expected on a '
                       'PostgreSQL 15 server — 5.8 refuses to finish until the database is '
                       'migrated. Continuing to the database migration.' % rc)

        # 5. The vendor migration. Bare, per D1.
        _say('')
        _say('Migrating the database from PostgreSQL 15 to %d. This is the long part — do '
                   'not interrupt it. Duration scales with database size, and with whether the '
                   '5.8 schema update has to rewrite cot_router (see the note above).'
                   % TAK_PG_MAJOR)
        if not os.path.exists(_TAK58_UPGRADE_DB_SH):
            return fail('The 5.8 package did not provide %s — cannot migrate the database.'
                        % _TAK58_UPGRADE_DB_SH, wedged=True)
        rc = _tak58_run_upgrade_db(log=_log)
        # The script has no shebang and uses bashisms, so under dash it emits
        # stderr noise (`[: ==: unexpected operator`, `wc: unrecognized option`)
        # while still doing its job. Noise is NOT failure — only the exit code is.
        if rc != 0:
            return fail('The database migration failed (exit %d). See the output above.' % rc,
                        wedged=True)

        # The vendor script's exit code is NOT evidence that the schema updated — it
        # exits 0 even when SchemaManager failed to authenticate. Ask the database.
        _sv = _tak58_schema_version()
        if _sv is not None and _sv < _TAK58_MIN_SCHEMA_VERSION:
            _say('')
            _say('The database migrated but the 5.8 schema updates did not apply '
                 '(schema_version %d). Repairing…' % _sv)
            _tak58_heal_md5_scram(_say)
            _sv2 = _tak58_schema_version()
            if _sv2 is None or _sv2 < _TAK58_MIN_SCHEMA_VERSION:
                return fail('The 5.8 schema updates could not be applied (schema_version %s). '
                            'TAK Server 5.8 must NOT be run against a pre-5.8 schema — it will '
                            'appear healthy and behave incorrectly. See the output above.'
                            % (_sv2 if _sv2 is not None else 'unknown'), wedged=True)
            _say('  Schema updates applied — now at version %d.' % _sv2)
        elif _sv is None:
            _say('  WARNING: could not read schema_version to confirm the 5.8 schema updates '
                 'applied. Verify by hand before putting this server back in service.')

        # Finish the package. On Debian the 5.8 install DELIBERATELY exits non-zero on a
        # PG-15 box ("A pg15 install has been detected…"), so dpkg is left holding a
        # half-configured takserver even after the database migration succeeds and TAK
        # runs perfectly well. Nothing looks wrong until the NEXT apt operation on that
        # box reports "1 not fully installed or removed" and refuses — which is how this
        # was found: an uninstall on dev-4 could not purge the package (2026-09-02).
        # dpkg --configure -a is idempotent and a no-op when nothing is pending.
        if _distro_family() != 'rhel':
            _say('')
            _say('Finishing the package installation…')
            _cfg_rc = _run_dpkg_configure_a(_say, _log)
            if _cfg_rc != 0:
                _say('  WARNING: dpkg --configure -a returned %d. TAK Server may still be '
                     'running correctly, but the package is not fully registered — the next '
                     'apt operation on this server will report it. Run '
                     '`sudo dpkg --configure -a` and check the output.' % _cfg_rc)

        # 6. Start and verify it is actually SERVING — not merely "active".
        _say('')
        _say('Starting TAK Server…')
        subprocess.run(_sudo_wrap(['systemctl', 'start', 'takserver']),
                       capture_output=True, timeout=300)
        post = _tak_58_preflight()
        pf2 = post.get('facts', {})
        running = pf2.get('pg_running_major')
        if running != TAK_PG_MAJOR:
            return fail('The migration finished but PostgreSQL %s is still serving, not %d.'
                        % (running, TAK_PG_MAJOR), wedged=True)
        _say('  PostgreSQL %d confirmed serving.' % TAK_PG_MAJOR)
        _say('')
        _say('Migration complete. The PostgreSQL 15 cluster was left on disk and can be '
                   'removed once you are satisfied — it is your rollback until then.')
        _say('Backup kept at %s' % bk.get('snapshot_path'))
        _status.update({'running': False, 'complete': True, 'error': False})
    except Exception as e:
        fail('Unexpected error: %s' % str(e)[:400], wedged=True)


@app.route('/api/takserver/58-migrate', methods=['POST'])
@login_required
def takserver_58_migrate():
    """Start the guided 5.8 + PG18 migration. There is deliberately no way to run
    only half of it — see the module comment above."""
    if tak58_status.get('running'):
        return jsonify({'error': 'A migration is already in progress'}), 409
    # @login_required proves a session; it does not prove the person at the keyboard
    # meant to migrate a production database. Same contract as every uninstall route.
    _gate = _require_admin_password()
    if _gate is not None:
        return _gate
    try:
        cands = [f for f in os.listdir(UPLOAD_DIR) if f.endswith(('.deb', '.rpm'))]
    except Exception:
        cands = []
    pkgs = [f for f in cands if (_tak_artifact_version(f) or (0, 0)) >= TAK_GATE_BLOCK_FROM]
    if not pkgs:
        return jsonify({'error': 'Upload the TAK Server 5.8 package (.deb or .rpm) first.'}), 400
    pkg = os.path.join(UPLOAD_DIR, sorted(
        pkgs, key=lambda f: os.path.getmtime(os.path.join(UPLOAD_DIR, f)))[-1])
    tak58_log.clear()
    tak58_status.update({'running': True, 'complete': False, 'error': False})
    threading.Thread(target=run_takserver_58_migration, args=(pkg,), daemon=True).start()
    return jsonify({'success': True, 'package': os.path.basename(pkg)})


@app.route('/api/takserver/58-migrate/log')
@login_required
def takserver_58_migrate_log():
    idx = int(request.args.get('index', 0))
    return jsonify({'entries': tak58_log[idx:], 'total': len(tak58_log),
                    'running': tak58_status['running'],
                    'complete': tak58_status['complete'],
                    'error': tak58_status['error']})


# ── TAK Server 5.8 upgrade gate ─────────────────────────────────────────────
# TAK 5.8 ships a PostgreSQL 15->18 database migration. Installing the 5.8
# package on a PG-15 box through THIS path wedges TAK mid-upgrade: the package
# refuses to finish, TAK stays down, and nothing migrates the database.
#
# v10.2.0 W5: the gate STAYS. Its job changed rather than ended. The guided flow
# now exists (/api/takserver/58-migrate), so the message points there instead of
# saying "coming in a future release" — but the old update path is still exactly
# as dangerous as it always was, and deleting the gate because a better route
# exists would just re-open the wedge for anyone who uses the wrong button.
TAK_GATE_BLOCK_FROM = (5, 8)
TAK_GATE_MESSAGE = (
    'TAK Server 5.8+ requires a PostgreSQL 15 to 18 database migration, so it cannot go '
    'through the normal update - that path installs the package and stops, leaving TAK '
    'Server down. Use the "TAK Server 5.8 requires PostgreSQL 18" card at the top of this '
    'section instead: it backs up, upgrades and migrates as one operation.'
)
# First major.minor after "takserver" in the artifact name. Covers every shape
# we accept: takserver_5.7-RELEASE43_all.deb, takserver-5.8-RELEASE1.noarch.rpm,
# takserver-docker-5.4-RELEASE.zip, takserver-core_5.7-..., takserver-database-...
_TAK_VER_RE = re.compile(r'takserver[^0-9]*(\d+)\.(\d+)', re.I)


def _tak_artifact_version(filename):
    """(major, minor) parsed from an artifact filename, or None if unparseable."""
    m = _TAK_VER_RE.search(os.path.basename(str(filename or '')))
    if not m:
        return None
    try:
        return (int(m.group(1)), int(m.group(2)))
    except (TypeError, ValueError):
        return None


def _tak_target_version_gate(*filenames):
    """Return the STOP message if ANY artifact is >= 5.8, else None.

    Unparseable names are ALLOWED on purpose — an operator with an oddly named
    but legitimate 5.7 package must not be locked out of updating, and the gate
    is a guard rail rather than an authorisation boundary.

    settings['allow_tak_58'] (truthy, settings.json only, no UI) bypasses this so
    real 5.8 artifacts can be exercised on dev boxes without reverting the gate.
    """
    try:
        allow = bool(load_settings().get('allow_tak_58'))
    except Exception:
        allow = False
    for fn in filenames:
        ver = _tak_artifact_version(fn)
        if not ver or ver < TAK_GATE_BLOCK_FROM:
            continue
        if allow:
            print('[tak-gate] BYPASSED by allow_tak_58: permitting TAK %d.%d artifact %r'
                  % (ver[0], ver[1], os.path.basename(str(fn))), flush=True)
            return None
        return TAK_GATE_MESSAGE
    return None


@app.route('/api/takserver/update', methods=['POST'])
@login_required
def takserver_update():
    """Run TAK Server upgrade. Two-server: core first (local), then database (SSH to Server One)."""
    if not os.path.exists('/opt/tak'):
        return jsonify({'error': 'TAK Server not installed. Deploy TAK Server first.'}), 400
    settings = load_settings()

    # ── v10.2.0 W5: 5.8 goes through THIS button, not a second one ──────────
    # 5.8 needs a PostgreSQL 15->18 migration, which the plain package install
    # cannot do — it installs, refuses to finish, and leaves TAK down. That used
    # to be a refusal telling the operator to wait for a future release. It is
    # now a ROUTE: the same Update button detects a 5.8 artifact on a PG-15 box
    # and runs the guided migration instead of the plain upgrade, writing to the
    # same upgrade_log the page already polls. One button, one log, no parallel
    # path for a user to discover.
    #
    # The gate below still fires for anything the migration cannot handle
    # (container TAK, remote DB) — routing is not the same as always allowing.
    _pending = []
    try:
        _pending = [f for f in os.listdir(UPLOAD_DIR) if f.endswith(('.deb', '.rpm'))]
    except OSError:
        pass
    _is58 = any((_tak_artifact_version(f) or (0, 0)) >= TAK_GATE_BLOCK_FROM for f in _pending)
    if _is58 and not _tak_is_container():
        if upgrade_status['running']:
            return jsonify({'error': 'Update already in progress'}), 409
        _pf = _tak_58_preflight()
        if not _pf.get('ready'):
            return jsonify({'error': 'TAK Server 5.8 cannot be installed on this server yet: '
                                     + '; '.join(_pf.get('blockers') or ['pre-flight failed'])}), 400
        _pkg = os.path.join(UPLOAD_DIR, sorted(
            [f for f in _pending if (_tak_artifact_version(f) or (0, 0)) >= TAK_GATE_BLOCK_FROM],
            key=lambda f: os.path.getmtime(os.path.join(UPLOAD_DIR, f)))[-1])
        upgrade_log.clear()
        upgrade_status.update({'running': True, 'complete': False, 'error': False})
        threading.Thread(target=run_takserver_58_migration,
                         args=(_pkg,), kwargs={'log': upgrade_log, 'status': upgrade_status},
                         daemon=True).start()
        return jsonify({'success': True, 'migration': True,
                        'message': 'TAK Server 5.8 detected — running the guided upgrade '
                                   '(backup, install, database migration to PostgreSQL '
                                   '%d, restart) as one operation.' % TAK_PG_MAJOR})
    # v10.0.1: a container box must NEVER take the .deb/dpkg/apt upgrade path — it does not
    # upgrade the image and litters the host. Run the data-preserving container upgrade instead:
    # rebuild the image from the new takserver-docker-*.zip while KEEPING the DB volume + certs.
    if _tak_is_container():
        if upgrade_status['running']:
            return jsonify({'error': 'Update already in progress'}), 409
        _zips = [f for f in os.listdir(UPLOAD_DIR) if f.lower().endswith('.zip') and 'docker' in f.lower()]
        if not _zips:
            return jsonify({'error': 'Container upgrade: upload the new takserver-docker-*.zip bundle (not a .deb).'}), 400
        _zip = os.path.join(UPLOAD_DIR, sorted(_zips, key=lambda f: os.path.getmtime(os.path.join(UPLOAD_DIR, f)))[-1])
        _g = _tak_target_version_gate(_zip)
        if _g:
            return jsonify({'error': _g}), 400
        upgrade_log.clear()
        upgrade_status.update({'running': True, 'complete': False, 'error': False})
        threading.Thread(target=run_takserver_upgrade_container, args=(_zip,), daemon=True).start()
        return jsonify({'success': True})
    # RHEL/Rocky native: upgrade from the new takserver-*.noarch.rpm via dnf.
    if _distro_family() == 'rhel' or settings.get('pkg_mgr') == 'dnf':
        if upgrade_status['running']:
            return jsonify({'error': 'Update already in progress'}), 409
        _tak_cfg = _get_tak_deployment_config(settings)
        _all_rpms = sorted([f for f in os.listdir(UPLOAD_DIR) if f.endswith('.rpm')],
                           key=lambda f: os.path.getmtime(os.path.join(UPLOAD_DIR, f)), reverse=True)
        # v10.0.5: RHEL two-server (split) update — core (local dnf) + database rpm on Server One
        # (SSH dnf) + SchemaManager on Server One. Previously ALL RHEL boxes fell through to the
        # single-server path below, so a split update never touched the DB box.
        if _tak_cfg.get('mode') == 'two_server':
            _core_rpm = next((f for f in _all_rpms if 'core' in f.lower()), '')
            _db_rpm = next((f for f in _all_rpms if 'database' in f.lower()), '')
            if not _core_rpm or not _db_rpm:
                return jsonify({'error': 'Two-server update requires both takserver-core and takserver-database .noarch.rpm packages. Upload both.'}), 400
            _g = _tak_target_version_gate(_core_rpm, _db_rpm)
            if _g:
                return jsonify({'error': _g}), 400
            _s1 = _tak_cfg.get('server_one', {})
            if not _s1.get('host'):
                return jsonify({'error': 'Server One host not configured in deployment settings.'}), 400
            upgrade_log.clear()
            upgrade_status.update({'running': True, 'complete': False, 'error': False})
            threading.Thread(target=run_takserver_upgrade_two_server_rhel, args=(
                os.path.join(UPLOAD_DIR, _core_rpm), os.path.join(UPLOAD_DIR, _db_rpm), _s1, _tak_cfg,
            ), daemon=True).start()
            return jsonify({'success': True})
        _rpms = sorted([f for f in os.listdir(UPLOAD_DIR)
                        if f.endswith('.rpm') and '-database' not in f.lower() and '-core' not in f.lower()],
                       key=lambda f: os.path.getmtime(os.path.join(UPLOAD_DIR, f)), reverse=True)
        if not _rpms:
            return jsonify({'error': 'No takserver .rpm found. Upload the new takserver-*.noarch.rpm from tak.gov first (the single-server package, not core/database).'}), 400
        _g = _tak_target_version_gate(_rpms[0])
        if _g:
            return jsonify({'error': _g}), 400
        # external_db: pass the RDS block so the upgrade runs SchemaManager against the managed DB.
        _edb = _tak_cfg.get('external_db') if _tak_cfg.get('mode') == 'external_db' else None
        upgrade_log.clear()
        upgrade_status.update({'running': True, 'complete': False, 'error': False})
        threading.Thread(target=run_takserver_upgrade_rhel, args=(os.path.join(UPLOAD_DIR, _rpms[0]),),
                         kwargs={'external_db': _edb}, daemon=True).start()
        return jsonify({'success': True})
    if upgrade_status['running']:
        return jsonify({'error': 'Update already in progress'}), 409
    tak_cfg = _get_tak_deployment_config(settings)
    is_two_server = tak_cfg.get('mode') == 'two_server'
    pkg_files = sorted([f for f in os.listdir(UPLOAD_DIR) if f.endswith('.deb')],
        key=lambda f: os.path.getmtime(os.path.join(UPLOAD_DIR, f)), reverse=True)
    if not pkg_files:
        return jsonify({'error': 'No .deb package found. Upload the new TAK Server .deb from tak.gov first.'}), 400
    if is_two_server:
        core_pkg = next((f for f in pkg_files if 'core' in f.lower()), '')
        db_pkg = next((f for f in pkg_files if 'database' in f.lower()), '')
        if not core_pkg or not db_pkg:
            return jsonify({'error': 'Two-server update requires both takserver-core and takserver-database .deb packages. Upload both.'}), 400
        _g = _tak_target_version_gate(core_pkg, db_pkg)
        if _g:
            return jsonify({'error': _g}), 400
        s1 = tak_cfg.get('server_one', {})
        if not s1.get('host'):
            return jsonify({'error': 'Server One host not configured in deployment settings.'}), 400
        upgrade_log.clear()
        upgrade_status.update({'running': True, 'complete': False, 'error': False})
        threading.Thread(target=run_takserver_upgrade_two_server, args=(
            os.path.join(UPLOAD_DIR, core_pkg),
            os.path.join(UPLOAD_DIR, db_pkg),
            s1, tak_cfg
        ), daemon=True).start()
    else:
        single_pkgs = [f for f in pkg_files if '-database' not in f.lower() and '-core' not in f.lower()]
        if not single_pkgs:
            return jsonify({'error': 'Only split packages (core/database) found. For one-server update, upload the single takserver .deb. Remove the wrong files and upload the correct package.'}), 400
        _g = _tak_target_version_gate(single_pkgs[0])
        if _g:
            return jsonify({'error': _g}), 400
        upgrade_log.clear()
        upgrade_status.update({'running': True, 'complete': False, 'error': False})
        threading.Thread(target=run_takserver_upgrade, args=(os.path.join(UPLOAD_DIR, single_pkgs[0]),), daemon=True).start()
    return jsonify({'success': True})

@app.route('/api/takserver/update/log')
@login_required
def takserver_update_log():
    idx = int(request.args.get('index', 0))
    return jsonify({'entries': upgrade_log[idx:], 'total': len(upgrade_log),
        'running': upgrade_status['running'], 'complete': upgrade_status['complete'], 'error': upgrade_status['error']})

def _tak_upgrade_apt_install(cwd, pkg_name, upgrade_log, timeout_sec=600):
    """Run apt-get install for a local .deb with streamed output.

    subprocess.run(capture_output=True) buffers all stdout/stderr until exit, so a slow
    configure/postinst looks like a silent hang. stdbuf -oL line-buffers; a reader thread
    appends lines to upgrade_log so operators see where apt stalled if a timeout fires.
    """
    qn = shlex.quote(pkg_name)
    # v10.0.5 non-root: pass env via Popen instead of a literal `env` wrapper, so
    # `apt-get` is the direct command and resolves to the broker shim on PATH (root).
    _aenv = dict(os.environ, DEBIAN_FRONTEND='noninteractive', NEEDRESTART_MODE='l')
    cmd = f'stdbuf -oL -eL apt-get install -y ./{qn} 2>&1'
    proc = subprocess.Popen(
        cmd, shell=True, cwd=cwd, env=_aenv,
        stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1)
    if proc.stdout is None:
        return 1

    def _drain():
        for line in iter(proc.stdout.readline, ''):
            if line and 'NEEDRESTART' not in line:
                upgrade_log.append('  ' + line.rstrip('\n'))

    t = threading.Thread(target=_drain, daemon=True)
    t.start()
    try:
        proc.wait(timeout=timeout_sec)
    except subprocess.TimeoutExpired:
        proc.kill()
        try:
            proc.wait(timeout=15)
        except Exception:
            pass
        t.join(timeout=5)
        raise
    t.join(timeout=5)
    return proc.returncode if proc.returncode is not None else 1


# takserver .postinst chmod/chown targets; fallbacks if postinst is unreadable.
_TAK_POSTINST_EXPLICIT_SH_FALLBACK = (
    '/opt/tak/config/takserver-config.sh',
    '/opt/tak/messaging/takserver-messaging.sh',
)
# Paths that look like files (do not mkdir — postinst cp/install references these).
_TAK_POSTINST_SKIP_DIR_MK_SUFFIX = (
    '.xml', '.sql', '.conf', '.jks', '.pem', '.properties', '.jar', '.war', '.deb', '.rpm',
    '.pol', '.p12', '.crt', '.key', '.idx', '.policy',
)
_TAK_POSTINST_SH_GLOB_DIRS = (
    '/opt/tak/config',
    '/opt/tak/messaging',
    '/opt/tak/utils',
    '/opt/tak/api',
    '/opt/tak/cluster',
    '/opt/tak/retention',
)


def _tak_postinst_path_should_skip_mkdir(p):
    """True if p is almost certainly a file (postinst cp/install lines mention these — do not mkdir)."""
    pl = p.lower()
    if pl.endswith(_TAK_POSTINST_SKIP_DIR_MK_SUFFIX):
        return True
    if pl.endswith('.dist') or '.dist.' in os.path.basename(p):
        return True
    return False


def _tak_postinst_resolved_mitigation_paths():
    """Return (sh_paths, dir_paths) from takserver.postinst chmod/chown lines only (+ .sh fallbacks).

    Do not parse cp/install/mv — those reference many files; mkdir on them breaks dpkg.
    Do not mkdir /opt/tak/config/takserver-config here — an empty dir breaks postinst cp; see rmdir helper.
    """
    sh_paths = set(_TAK_POSTINST_EXPLICIT_SH_FALLBACK)
    dir_paths = set()
    pi = '/var/lib/dpkg/info/takserver.postinst'
    try:
        if os.path.isfile(pi):
            with open(pi, 'r', encoding='utf-8', errors='ignore') as f:
                lines = f.read().splitlines()
            for line in lines:
                if '#' in line:
                    line = line.split('#', 1)[0]
                if not any(k in line for k in ('chmod', 'chown')):
                    continue
                for m in re.finditer(r'/opt/tak/[A-Za-z0-9_./-]+', line):
                    p = m.group(0)
                    if p.endswith('.sh'):
                        sh_paths.add(p)
                    elif p.endswith(('.deb', '.rpm', '.jar', '.war')):
                        continue
                    elif _tak_postinst_path_should_skip_mkdir(p):
                        continue
                    elif p == '/opt/tak/config/takserver-config':
                        # Postinst populates via cp; empty pre-created dir breaks cp (see _tak_upgrade_remove_blocking_empty_takserver_config).
                        continue
                    else:
                        dir_paths.add(p)
    except OSError:
        pass
    return sorted(sh_paths), sorted(dir_paths)


def _sudo_test(path, flag):
    """True if a test on `path` succeeds (flag '-d','-f','-e'). v10.0.5 non-root:
    /opt/tak is world-traversable and its files are world-readable, so a plain
    os.path check works — the old `sudo test` failed (takwerx isn't in sudoers)
    and returned False for everything."""
    if flag == '-d':
        return os.path.isdir(path)
    if flag == '-f':
        return os.path.isfile(path)
    return os.path.exists(path)


def _tak_upgrade_remove_blocking_empty_takserver_config(ulog):
    """Remove empty /opt/tak/config/takserver-config if present.

    A prior workaround mkdir created an empty directory; postinst then fails with:
    cp: -r not specified; omitting directory '.../takserver-config'
    Real install unpacks/copies into that path — it must not exist as an empty infra-TAK placeholder.
    """
    p = '/opt/tak/config/takserver-config'
    try:
        # v10.0.5 non-root: check emptiness in Python (world-readable) + remove via the
        # broker-routed `rmdir` shim (the old literal `sudo bash -c` failed as takwerx).
        if os.path.isdir(p) and not os.listdir(p):
            r = subprocess.run(_sudo_wrap(['rmdir', p]), capture_output=True, text=True, timeout=15)
            if r.returncode == 0:
                ulog(f"  ✓ removed empty {p} (so postinst can populate — not a mkdir placeholder)")
    except Exception as e:
        ulog(f"  ⚠ could not clear empty {p}: {e}")


def _tak_upgrade_mitigate_takserver_postinst_config_sh(ulog):
    """Ensure dirs, named scripts, and *.sh globs exist so takserver postinst chmod/chown succeeds.

    Implemented in Python (not a single bash -c blob) so every step is logged and failures are visible.
    After a killed upgrade, dpkg --configure needs paths the .deb would normally unpack.

    Also invoked from _tak_upgrade_dpkg_configure_a so this always runs immediately before dpkg --configure -a.
    """
    ulog("Preparing /opt/tak paths expected by takserver postinst (partial-upgrade workaround)...")
    _tak_upgrade_remove_blocking_empty_takserver_config(ulog)
    sh_paths, dir_paths = _tak_postinst_resolved_mitigation_paths()
    placeholder = (
        '#!/bin/sh\n'
        '# infra-TAK: placeholder until package files are restored — run: apt reinstall takserver .deb\n'
        'exit 0\n'
    )
    # v10.0.5 non-root: literal `sudo mkdir/tee/chmod/bash` all fail (takwerx not in
    # sudoers). Route mkdir via the shim (_sudo_wrap), writes via _write_priv (perm sets
    # the +x), and do emptiness/glob checks in Python (world-readable).
    import glob as _glob
    try:
        for d in sorted(dir_paths):
            r = subprocess.run(_sudo_wrap(['mkdir', '-p', d]), capture_output=True, text=True, timeout=30)
            if r.returncode != 0:
                ulog(f"✗ mkdir -p {d} failed: {(r.stderr or r.stdout or '').strip()[:400]}")
            else:
                ulog(f"  ✓ mkdir -p {d}")
        for fpath in sorted(sh_paths):
            parent = os.path.dirname(fpath)
            subprocess.run(_sudo_wrap(['mkdir', '-p', parent]), capture_output=True, text=True, timeout=30)
            if _sudo_test(fpath, '-f'):
                continue
            try:
                _write_priv(fpath, placeholder, perm=0o755)
            except Exception as _we:
                ulog(f"✗ could not write {fpath}: {str(_we)[:200]}")
                continue
            ulog(f"  ✓ placeholder {os.path.basename(fpath)}")
        for d in _TAK_POSTINST_SH_GLOB_DIRS:
            subprocess.run(_sudo_wrap(['mkdir', '-p', d]), capture_output=True, text=True, timeout=30)
            if _glob.glob(os.path.join(d, '*.sh')):
                continue
            stub = os.path.join(d, '_infra_tak_placeholder_for_postinst.sh')
            try:
                _write_priv(stub, placeholder, perm=0o755)
                ulog(f"  ✓ {d}/*.sh glob placeholder")
            except Exception:
                pass
    except Exception as e:
        ulog(f"✗ Tak path preparation error: {e}")


def _run_dpkg_configure_a(ulog, upgrade_log, timeout_sec=3600):
    """Run dpkg --configure -a, streaming output. Returns exit code (0 = success)."""
    ulog("Running dpkg --configure -a...")
    # v10.0.5 non-root: drop literal `sudo` — `dpkg` is an ALWAYS-shim binary, so the
    # bare invocation routes through the broker (running as root). `sudo dpkg` failed.
    cmd = 'DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=l dpkg --configure -a 2>&1'
    proc = subprocess.Popen(
        cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1)
    if proc.stdout is None:
        ulog("✗ Could not start dpkg --configure -a")
        return 1

    def _drain():
        for line in iter(proc.stdout.readline, ''):
            if line and 'NEEDRESTART' not in line:
                upgrade_log.append('  ' + line.rstrip('\n'))

    t = threading.Thread(target=_drain, daemon=True)
    t.start()
    try:
        proc.wait(timeout=timeout_sec)
    except subprocess.TimeoutExpired:
        proc.kill()
        try:
            proc.wait(timeout=15)
        except Exception:
            pass
        t.join(timeout=5)
        ulog("✗ dpkg --configure -a timed out.")
        return 1
    t.join(timeout=5)
    return proc.returncode if proc.returncode is not None else 1


def _tak_upgrade_dpkg_configure_a(ulog, upgrade_log, pkg_path=None):
    """Ensure dpkg is in a clean state before apt-get install.

    First attempt: dpkg --configure -a.
    If that fails and pkg_path is set (the .deb we're about to install), re-unpack it
    with dpkg --unpack (restores all missing files without running postinst), then retry
    dpkg --configure -a. This handles the common case where a timed-out upgrade left
    files missing while dpkg still needs to configure the half-installed package.
    """
    ulog("Ensuring dpkg state is consistent...")
    rc = _run_dpkg_configure_a(ulog, upgrade_log)
    if rc == 0:
        ulog("✓ dpkg state OK")
        return True

    if not pkg_path or not os.path.isfile(pkg_path):
        ulog("✗ dpkg --configure -a failed and no .deb available for re-unpack.")
        return False

    ulog("dpkg --configure -a failed — re-unpacking .deb to restore missing files...")
    ulog(f"  dpkg --unpack {os.path.basename(pkg_path)}")
    try:
        rc2 = _tak_upgrade_apt_install_streamed(
            'dpkg --unpack ' + shlex.quote(pkg_path) + ' 2>&1',
            os.path.dirname(pkg_path), upgrade_log, timeout_sec=300)
    except subprocess.TimeoutExpired:
        ulog("✗ dpkg --unpack timed out.")
        return False
    if rc2 != 0:
        ulog(f"✗ dpkg --unpack failed (exit {rc2}).")
        return False
    ulog("✓ Files restored from .deb")

    ulog("Retrying dpkg --configure -a after re-unpack...")
    rc3 = _run_dpkg_configure_a(ulog, upgrade_log)
    if rc3 != 0:
        ulog("✗ dpkg --configure -a still failed after re-unpack. Manual intervention needed.")
        return False
    ulog("✓ dpkg state OK (after re-unpack)")
    return 'ALREADY_INSTALLED'


def _tak_upgrade_apt_install_streamed(cmd, cwd, upgrade_log, timeout_sec=600):
    """Run a shell command with line-buffered output streamed to upgrade_log. Returns exit code."""
    proc = subprocess.Popen(
        cmd, shell=True, cwd=cwd,
        stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1)
    if proc.stdout is None:
        return 1

    def _drain():
        for line in iter(proc.stdout.readline, ''):
            if line and 'NEEDRESTART' not in line:
                upgrade_log.append('  ' + line.rstrip('\n'))

    t = threading.Thread(target=_drain, daemon=True)
    t.start()
    try:
        proc.wait(timeout=timeout_sec)
    except subprocess.TimeoutExpired:
        proc.kill()
        try:
            proc.wait(timeout=15)
        except Exception:
            pass
        t.join(timeout=5)
        raise
    t.join(timeout=5)
    return proc.returncode if proc.returncode is not None else 1


SNAPSHOT_DIR = '/opt/tak/snapshots'

_SNAPSHOT_LABEL_RE = re.compile(r'^[A-Za-z0-9._-]+$')


def _validate_snapshot_label(label):
    """v0.9.12: defence against path traversal in snapshot routes.

    Reject anything that could escape SNAPSHOT_DIR. Returns (ok, safe_label_or_error).

    Defence in depth:
      1. Reject empty / non-str inputs.
      2. Reject reserved names ('.', '..').
      3. Whitelist regex — only [A-Za-z0-9._-]+. Forbids '/', '\\', whitespace,
         null bytes, and every shell metacharacter.
      4. realpath check — after joining, the resolved path must live strictly
         inside the resolved SNAPSHOT_DIR. Catches edge cases where a clever
         attacker bypasses the regex (e.g. symlink games on disk).
    """
    if not label or not isinstance(label, str):
        return False, 'label is required'
    if label in ('.', '..'):
        return False, 'invalid label'
    if not _SNAPSHOT_LABEL_RE.fullmatch(label):
        return False, 'label must match [A-Za-z0-9._-]+'
    try:
        snap_real = os.path.realpath(os.path.join(SNAPSHOT_DIR, label))
        base_real = os.path.realpath(SNAPSHOT_DIR)
    except Exception:
        return False, 'label resolves to invalid path'
    if not snap_real.startswith(base_real + os.sep) and snap_real != base_real:
        return False, 'label resolves outside SNAPSHOT_DIR'
    if snap_real == base_real:
        return False, 'invalid label'
    return True, label


def _tak_snapshot(label, plog=None):
    """Create a TAK Server snapshot at /opt/tak/snapshots/<label>/.

    Captures: installed TAK version, CoreConfig.xml, UserAuthenticationFile.xml,
    /etc/default/takserver, PostgreSQL cot dump, and /opt/tak/certs/files/.

    Returns (True, metadata_dict) on success, (False, error_str) on failure.
    Idempotent — if the label already exists it is overwritten.
    """
    import shutil as _shutil
    if plog is None:
        plog = lambda m: print(m, flush=True)

    snap_path = os.path.join(SNAPSHOT_DIR, label)
    plog(f"  snapshot [{label}]: creating at {snap_path}")

    try:
        _makedirs_priv(snap_path)  # /opt/tak/snapshots root-owned — broker mkdir
    except Exception as e:
        return False, f"Could not create snapshot dir: {e}"

    meta = {
        'label':      label,
        'taken_at':   datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
        'source':     'manual',
        'tak_version': None,
        'size_mb':    0,
    }

    # 1. TAK version — try dpkg (multiple package names) then rpm
    try:
        for _pkg in ('takserver', 'takserver-core', 'takserver-database'):
            _r = subprocess.run(
                f"dpkg -s {_pkg} 2>/dev/null | grep ^Version:",
                shell=True, capture_output=True, text=True, timeout=5)
            if _r.returncode == 0 and _r.stdout.strip():
                meta['tak_version'] = _r.stdout.strip().replace('Version:', '').strip()
                break
        if meta['tak_version'] is None:
            _r = subprocess.run("rpm -q takserver 2>/dev/null", shell=True, capture_output=True, text=True, timeout=5)
            if _r.returncode == 0 and _r.stdout.strip():
                _ver = _r.stdout.strip()
                if _ver.startswith('takserver-'):
                    _ver = _ver.split('-', 1)[1]
                _ver = _ver.replace('.noarch', '')
                if _ver:
                    meta['tak_version'] = _ver
    except Exception as e:
        plog(f"  snapshot: version probe failed: {e}")

    # 2. CoreConfig.xml
    cc_src = '/opt/tak/CoreConfig.xml'
    if os.path.exists(cc_src):
        try:
            subprocess.run(_sudo_wrap(['cp','-p',cc_src, os.path.join(snap_path,'CoreConfig.xml')]), capture_output=True, check=True)
            plog("  snapshot: CoreConfig.xml copied")
        except Exception as e:
            plog(f"  snapshot: CoreConfig copy failed: {e}")
    else:
        plog("  snapshot: CoreConfig.xml not found — skipping")

    # 2b. UserAuthenticationFile.xml — flat-file users (admin, webadmin, optional Phase 1A nodered).
    # Without this, restoring a snapshot loses any flat-file users added since the snapshot,
    # which breaks Phase 1A's nodered cert auth even though the cert files survive in certs/.
    uaf_src = '/opt/tak/UserAuthenticationFile.xml'
    if os.path.exists(uaf_src):
        try:
            subprocess.run(_sudo_wrap(['cp','-p',uaf_src, os.path.join(snap_path,'UserAuthenticationFile.xml')]), capture_output=True, check=True)
            plog("  snapshot: UserAuthenticationFile.xml copied")
        except Exception as e:
            plog(f"  snapshot: UserAuthenticationFile.xml copy failed: {e}")
    else:
        plog("  snapshot: UserAuthenticationFile.xml not found — skipping (flat-file auth not configured)")

    # 3. /etc/default/takserver (JVM heap)
    heap_src = '/etc/default/takserver'
    if os.path.exists(heap_src):
        try:
            subprocess.run(_sudo_wrap(['cp','-p',heap_src, os.path.join(snap_path,'takserver.default')]), capture_output=True, check=True)
            plog("  snapshot: takserver.default copied")
        except Exception as e:
            plog(f"  snapshot: takserver.default copy failed: {e}")

    # 4. PostgreSQL cot dump
    # In a two-server deployment the database lives on Server One — stream via SSH.
    # In a single-server deployment it runs locally as the postgres OS user.
    pg_dump_path = os.path.join(snap_path, 'cot.pgdump')
    plog("  snapshot: pg_dump starting — cot database (may take 30–90s for large databases)…")
    meta['db_dump'] = False   # set True only when a non-empty cot dump actually lands
    try:
        _snap_settings = load_settings()
        _snap_tak_cfg = _get_tak_deployment_config(_snap_settings)
        _snap_two_server = _snap_tak_cfg.get('mode') == 'two_server'
        _snap_s1 = _snap_tak_cfg.get('server_one', {})
        _snap_edb = _snap_tak_cfg.get('external_db', {}) if _snap_tak_cfg.get('mode') == 'external_db' else {}
        if _snap_edb.get('host'):
            # external_db / RDS: the DB is managed (no SSH, no local postgres) — dump over
            # TCP with the client pg_dump. Stream to a console-writable temp, then broker-cp
            # into the root-owned snapshot dir (same pattern as the two-server branch).
            # Previously this mode fell through to the local branch: non-root skipped
            # "deferred", root hard-failed (no local postgres OS user). PLAN-v10.0.6 §3.
            import shutil as _shu
            _eh = _snap_edb['host']
            _ep = int(_snap_edb.get('port') or 5432)
            _en = _snap_edb.get('name') or 'cot'
            _eu = _snap_edb.get('user') or 'martiuser'
            if not _shu.which('pg_dump'):
                plog("  snapshot: external-DB mode but no pg_dump client on this box — DB dump skipped "
                     "(managed-DB automated backups still apply; install postgresql client tools to capture dumps in snapshots)")
            else:
                plog(f"  snapshot: external-DB mode — pg_dump over TCP from {_eh}:{_ep}")
                import tempfile
                _fd, _tmp_dump = tempfile.mkstemp(prefix='cot-snap-', suffix='.pgdump')
                os.close(_fd)
                try:
                    _pg_env = dict(os.environ)
                    _pg_env['PGPASSWORD'] = _snap_edb.get('password') or ''
                    with open(_tmp_dump, 'wb') as _f:
                        r2 = subprocess.run(
                            ['pg_dump', '-Fc', '-h', _eh, '-p', str(_ep), '-U', _eu, '-d', _en],
                            stdout=_f, stderr=subprocess.PIPE, timeout=600, env=_pg_env)
                    if r2.returncode == 0 and os.path.getsize(_tmp_dump) > 0:
                        _cp = subprocess.run(_sudo_wrap(['cp', _tmp_dump, pg_dump_path]), capture_output=True, timeout=120)
                        if _cp.returncode == 0:
                            meta['db_dump'] = True
                            plog(f"  snapshot: cot pg_dump (external DB {_eh}) written ({os.path.getsize(_tmp_dump) // 1024} KB)")
                        else:
                            plog(f"  snapshot: pg_dump copy into snapshot FAILED: {(_cp.stderr or b'').decode()[:160]}")
                    else:
                        plog(f"  snapshot: external-DB pg_dump FAILED (check network path + client-vs-server version): {(r2.stderr or b'').decode()[:200]}")
                finally:
                    try: os.remove(_tmp_dump)
                    except Exception: pass
        elif _snap_two_server and _snap_s1.get('host'):
            plog("  snapshot: two-server mode — streaming pg_dump from Server One via SSH")
            _ssh_dump_cmd = 'sudo -u postgres pg_dump -Fc cot'
            _host = (_snap_s1.get('host') or '').strip()
            _user = (_snap_s1.get('ssh_user') or 'root').strip() or 'root'
            _port = int(_snap_s1.get('ssh_port') or 22)
            _key  = (_snap_s1.get('ssh_key_path') or '').strip() or None
            _ssh_parts = [
                'ssh', '-o', 'StrictHostKeyChecking=accept-new', '-o', 'BatchMode=yes',
                '-p', str(_port),
            ]
            if _key:
                _ssh_parts += ['-i', _key]
            _ssh_parts += [f'{_user}@{_host}', _ssh_dump_cmd]
            # v10.0.5 non-root: the snapshot dir is root-owned (broker mkdir), so the non-root
            # console can't open() a file inside it — a direct write here was the silent
            # [Errno 13] that left two-server snapshots with NO database. Stream the SSH dump to
            # a console-writable temp, then broker-cp it into the snapshot dir (cp is already
            # broker-routed above for CoreConfig). Identical behaviour as root. NB: don't stat
            # the dest — the root-owned dir isn't traversable by takwerx; trust the temp size + cp rc.
            import tempfile
            _fd, _tmp_dump = tempfile.mkstemp(prefix='cot-snap-', suffix='.pgdump')
            os.close(_fd)
            try:
                with open(_tmp_dump, 'wb') as _f:
                    r2 = subprocess.run(_ssh_parts, stdout=_f, stderr=subprocess.PIPE, timeout=300)
                if r2.returncode == 0 and os.path.getsize(_tmp_dump) > 0:
                    _cp = subprocess.run(_sudo_wrap(['cp', _tmp_dump, pg_dump_path]), capture_output=True, timeout=120)
                    if _cp.returncode == 0:
                        meta['db_dump'] = True
                        plog(f"  snapshot: cot pg_dump (remote) written ({os.path.getsize(_tmp_dump) // 1024} KB)")
                    else:
                        plog(f"  snapshot: pg_dump copy into snapshot FAILED: {(_cp.stderr or b'').decode()[:160]}")
                else:
                    plog(f"  snapshot: remote pg_dump FAILED: {(r2.stderr or b'').decode()[:200]}")
            finally:
                try: os.remove(_tmp_dump)
                except Exception: pass
        elif _broker_should_route() and _broker_available():
            # v10.0.8 (PLAN §B): non-root SINGLE-server — the broker writes the dump to disk
            # itself (broker pg_dump op), so the 32MB socket cap that forced the v10.0.5
            # "DB dump deferred" skip no longer applies. Honest warning path on failure.
            try:
                _sz = _pg_dump_priv(pg_dump_path, db='cot', timeout=600,
                                    container=(TAK_DB_CONTAINER if _tak_is_container() else None))
                if _sz > 0:
                    meta['db_dump'] = True
                    plog(f"  snapshot: cot pg_dump written via broker ({_sz // 1024} KB)")
                else:
                    plog("  snapshot: broker pg_dump produced an EMPTY dump — db_dump=False (config+certs captured)")
            except Exception as _pg_e:
                plog(f"  snapshot: broker pg_dump FAILED: {str(_pg_e)[:200]} — db_dump=False (config+certs captured)")
        else:
            with open(pg_dump_path, 'wb') as _f:
                r2 = subprocess.run(
                    'sudo -u postgres pg_dump -Fc cot',
                    shell=True, stdout=_f, stderr=subprocess.PIPE, timeout=300
                )
            if r2.returncode == 0 and os.path.getsize(pg_dump_path) > 0:
                meta['db_dump'] = True
                plog(f"  snapshot: cot pg_dump written ({os.path.getsize(pg_dump_path) // 1024} KB)")
            else:
                plog(f"  snapshot: pg_dump FAILED: {(r2.stderr or b'').decode()[:200]}")
                try: os.remove(pg_dump_path)
                except Exception: pass
    except Exception as e:
        plog(f"  snapshot: pg_dump exception: {e}")

    # 5. Certificates
    certs_src = '/opt/tak/certs/files'
    certs_dst = os.path.join(snap_path, 'certs')
    if os.path.isdir(certs_src):
        try:
            subprocess.run(_sudo_wrap(['rm','-rf',certs_dst]), capture_output=True)
            subprocess.run(_sudo_wrap(['cp','-rp',certs_src,certs_dst]), capture_output=True, check=True)
            plog("  snapshot: certs/ copied")
        except Exception as e:
            plog(f"  snapshot: certs copy failed: {e}")
    else:
        plog("  snapshot: /opt/tak/certs/files not found — skipping")

    # Compute total size
    try:
        total = 0
        for dirpath, _, filenames in os.walk(snap_path):
            for fn in filenames:
                try: total += os.path.getsize(os.path.join(dirpath, fn))
                except Exception: pass
        meta['size_mb'] = round(total / (1024 * 1024), 1)
    except Exception:
        pass

    # Persist to settings
    try:
        s = load_settings()
        snaps = s.get('tak_snapshots') or []
        # Remove any existing entry with same label
        snaps = [sn for sn in snaps if sn.get('label') != label]
        snaps.append(meta)
        # Keep most recent 50
        snaps.sort(key=lambda x: x.get('taken_at', ''), reverse=True)
        s['tak_snapshots'] = snaps[:50]
        save_settings(s)
    except Exception as e:
        plog(f"  snapshot: settings save failed: {e}")

    if not meta.get('db_dump'):
        plog(f"  ⚠ snapshot [{label}]: NO cot database dump captured — this snapshot restores "
             f"CoreConfig / UserAuth / certs ONLY, not the database. DB-level rollback is NOT available.")
    plog(f"  ✓ snapshot [{label}]: done ({meta['size_mb']} MB, version={meta['tak_version']}, "
         f"db_dump={'yes' if meta.get('db_dump') else 'NO'})")
    return True, meta


def _tak_rollback(label, plog=None):
    """Restore TAK Server from snapshot at /opt/tak/snapshots/<label>/.

    Steps:
      1. Validate snapshot exists and has a pg_dump
      2. systemctl stop takserver
      3. Restore CoreConfig.xml, UserAuthenticationFile.xml, takserver.default, certs/
      4. pg_restore --clean -d cot from snapshot
      5. systemctl start takserver

    Returns (True, None) on success, (False, error_str) on failure.
    """
    import shutil as _shutil
    if plog is None:
        plog = lambda m: print(m, flush=True)

    ok, label_or_err = _validate_snapshot_label(label)
    if not ok:
        return False, f"Invalid snapshot label: {label_or_err}"
    label = label_or_err
    snap_path = os.path.join(SNAPSHOT_DIR, label)
    if not os.path.isdir(snap_path):
        return False, f"Snapshot '{label}' not found at {snap_path}"

    plog(f"  rollback [{label}]: starting")

    # 1. Validate. os.path.exists is authoritative as root; on the non-root
    # console the root-owned snapshot dir may not be stat-able — confirm via a
    # broker `test -f` before declaring the dump missing (v10.0.8).
    pg_dump_path = os.path.join(snap_path, 'cot.pgdump')
    if not os.path.exists(pg_dump_path):
        _via_broker = (_broker_should_route() and _broker_available()
                       and subprocess.run(_sudo_wrap(['test', '-f', pg_dump_path]),
                                          capture_output=True, timeout=10).returncode == 0)
        if not _via_broker:
            return False, f"Snapshot '{label}' has no cot.pgdump — cannot restore database"

    # 2. Stop TAK Server
    plog("  rollback: stopping takserver…")
    subprocess.run(_tak_systemctl('stop'), shell=True, capture_output=True, timeout=60)  # v10.0.1: container-aware

    # 3. Restore CoreConfig.xml
    cc_src = os.path.join(snap_path, 'CoreConfig.xml')
    if os.path.exists(cc_src):
        try:
            subprocess.run(_sudo_wrap(['cp','-p',cc_src,'/opt/tak/CoreConfig.xml']), capture_output=True, check=True)
            plog("  rollback: CoreConfig.xml restored")
        except Exception as e:
            plog(f"  rollback: CoreConfig restore failed: {e}")

    # 3b. Restore UserAuthenticationFile.xml (flat-file users incl. optional Phase 1A nodered).
    uaf_src = os.path.join(snap_path, 'UserAuthenticationFile.xml')
    uaf_dst = '/opt/tak/UserAuthenticationFile.xml'
    if os.path.exists(uaf_src):
        try:
            subprocess.run(_sudo_wrap(['cp','-p',uaf_src,uaf_dst]), capture_output=True, check=True)
            # Match the ownership convention used elsewhere for /opt/tak files.
            subprocess.run(
                _sudo_wrap(['chown', ('1000:1000' if _tak_is_container() else 'tak:tak'), '/opt/tak/UserAuthenticationFile.xml']), capture_output=True, timeout=10
            )
            plog("  rollback: UserAuthenticationFile.xml restored")
        except Exception as e:
            plog(f"  rollback: UserAuthenticationFile.xml restore failed: {e}")
    else:
        plog("  rollback: snapshot has no UserAuthenticationFile.xml — leaving current file in place")

    # 4. Restore JVM heap settings
    heap_src = os.path.join(snap_path, 'takserver.default')
    if os.path.exists(heap_src):
        try:
            subprocess.run(_sudo_wrap(['cp','-p',heap_src,'/etc/default/takserver']), capture_output=True, check=True)
            plog("  rollback: takserver.default restored")
        except Exception as e:
            plog(f"  rollback: takserver.default restore failed: {e}")

    # 5. Restore certs
    certs_src = os.path.join(snap_path, 'certs')
    certs_dst = '/opt/tak/certs/files'
    if os.path.isdir(certs_src):
        try:
            subprocess.run(_sudo_wrap(['rm','-rf',certs_dst]), capture_output=True)
            subprocess.run(_sudo_wrap(['cp','-rp',certs_src,certs_dst]), capture_output=True, check=True)
            # Restore ownership (tak:tak) on certs
            subprocess.run(
                _sudo_wrap(['chown', '-R', ('1000:1000' if _tak_is_container() else 'tak:tak'), '/opt/tak/certs/files']), capture_output=True, timeout=15
            )
            plog("  rollback: certs/ restored")
        except Exception as e:
            plog(f"  rollback: certs restore failed: {e}")

    # 6. pg_restore
    # In two-server mode stream the dump to Server One and restore there.
    # In single-server mode restore into the local takserver-db container.
    #
    # v10.0.5 non-root: cot.pgdump lives in the root-owned snapshot dir (0600 from
    # pg_dump), so the non-root console can't open() it to feed pg_restore's stdin.
    # Stage a console-readable copy via the broker (cp + chown to the console uid,
    # inside /opt/tak/snapshots/), open THAT, and remove it afterwards. On root the
    # broker doesn't route, so _staged_dump stays the original path (opened directly).
    # v10.0.8: staging is now ONLY for the two-server SSH stream — the local restore
    # goes through the broker pg_restore op (the broker opens the dump as root and
    # feeds pg_restore itself; a staged copy pushed through the exec proxy would hit
    # the 32MB socket cap on any real database).
    _rb_settings = load_settings()
    _rb_tak_cfg  = _get_tak_deployment_config(_rb_settings)
    _rb_two_server = _rb_tak_cfg.get('mode') == 'two_server' and (_rb_tak_cfg.get('server_one', {}) or {}).get('host')
    _staged_dump = pg_dump_path
    if _rb_two_server and _broker_should_route() and _broker_available():
        _staged_dump = os.path.join(snap_path, '.cot.pgdump.staged')
        try:
            subprocess.run(_sudo_wrap(['cp', pg_dump_path, _staged_dump]), capture_output=True, check=True, timeout=120)
            subprocess.run(_sudo_wrap(['chown', f'{os.getuid()}:{os.getgid()}', _staged_dump]), capture_output=True, check=True, timeout=30)
        except Exception as _e_stage:
            plog(f"  rollback: could not stage cot.pgdump for restore: {_e_stage}")
            _staged_dump = pg_dump_path  # fall back; open() may still work as root
    plog("  rollback: restoring PostgreSQL cot database…")
    try:
        _rb_s1 = _rb_tak_cfg.get('server_one', {})
        if _rb_two_server:
            plog("  rollback: two-server mode — streaming pg_restore to Server One via SSH")
            _rb_host = (_rb_s1.get('host') or '').strip()
            _rb_user = (_rb_s1.get('ssh_user') or 'root').strip() or 'root'
            _rb_port = int(_rb_s1.get('ssh_port') or 22)
            _rb_key  = (_rb_s1.get('ssh_key_path') or '').strip() or None
            _rb_ssh  = ['ssh', '-o', 'StrictHostKeyChecking=accept-new', '-o', 'BatchMode=yes',
                        '-p', str(_rb_port)]
            if _rb_key:
                _rb_ssh += ['-i', _rb_key]
            _rb_remote_cmd = 'sudo -u postgres pg_restore --clean -d cot'
            _rb_ssh += [f'{_rb_user}@{_rb_host}', _rb_remote_cmd]
            with open(_staged_dump, 'rb') as _f:
                r2 = subprocess.run(_rb_ssh, stdin=_f, capture_output=True, timeout=300)
            if r2.returncode in (0, 1):
                stderr = (r2.stderr or b'').decode()[:200]
                if stderr:
                    plog(f"  rollback: pg_restore (remote) warnings (non-fatal): {stderr}")
                else:
                    plog("  rollback: pg_restore (remote) successful")
            else:
                plog(f"  rollback: remote pg_restore failed (exit {r2.returncode}): {(r2.stderr or b'').decode()[:200]}")
        elif _broker_should_route() and _broker_available():
            # v10.0.8 non-root single-server: broker pg_restore op — the broker
            # opens the dump as root and feeds pg_restore/docker-exec itself, so
            # nothing crosses the socket. Covers native (runuser postgres) AND
            # container TAK (docker exec takserver-db) via the container key.
            resp = _broker_request({'op': 'pg_restore', 'path': pg_dump_path, 'db': 'cot',
                                    'container': (TAK_DB_CONTAINER if _tak_is_container() else None),
                                    'timeout': 600}, timeout=630)
            if resp.get('ok') and resp.get('returncode') in (0, 1):
                stderr = (resp.get('stderr') or '')[:200]
                if stderr:
                    plog(f"  rollback: pg_restore warnings (non-fatal): {stderr}")
                else:
                    plog("  rollback: pg_restore successful")
            else:
                plog(f"  rollback: pg_restore failed (exit {resp.get('returncode')}): "
                     f"{(resp.get('error') or resp.get('stderr') or '')[:200]}")
        elif _tak_is_container():
            pg_container = TAK_DB_CONTAINER
            r = subprocess.run(
                _sudo_wrap(['docker', 'ps', '-q', '--filter', f'name={pg_container}']), capture_output=True, text=True, timeout=10
            )
            if (r.stdout or '').strip():
                r2 = subprocess.run(
                    _sudo_wrap(['docker', 'exec', '-i', pg_container, 'pg_restore', '-U', 'postgres', '--clean', '-d', 'cot']),
                    stdin=open(_staged_dump, 'rb'),
                    capture_output=True,
                    timeout=300
                )
                if r2.returncode in (0, 1):
                    stderr = (r2.stderr or b'').decode()[:400]
                    if stderr:
                        plog(f"  rollback: pg_restore warnings (non-fatal): {stderr[:200]}")
                    else:
                        plog("  rollback: pg_restore successful")
                else:
                    plog(f"  rollback: pg_restore failed (exit {r2.returncode}): {(r2.stderr or b'').decode()[:200]}")
            else:
                plog(f"  rollback: {pg_container} not running — skipping pg_restore")
        else:
            # v10.0.8: ROOT native single-server — restore directly via the local
            # postgres OS user. The old code only knew the takserver-db container
            # and silently SKIPPED the DB restore on native installs (the dump was
            # captured but never came back — the same class of gap as the non-root
            # "DB dump deferred" this release closes).
            with open(_staged_dump, 'rb') as _f:
                r2 = subprocess.run(['runuser', '-u', 'postgres', '--',
                                     'pg_restore', '--clean', '-d', 'cot'],
                                    stdin=_f, capture_output=True, timeout=600)
            if r2.returncode in (0, 1):
                stderr = (r2.stderr or b'').decode()[:400]
                if stderr:
                    plog(f"  rollback: pg_restore warnings (non-fatal): {stderr[:200]}")
                else:
                    plog("  rollback: pg_restore successful")
            else:
                plog(f"  rollback: pg_restore failed (exit {r2.returncode}): {(r2.stderr or b'').decode()[:200]}")
    except Exception as e:
        plog(f"  rollback: pg_restore exception: {e}")
    finally:
        # Remove the staged dump copy (broker-owned by the console uid now).
        if _staged_dump != pg_dump_path:
            try: subprocess.run(_sudo_wrap(['rm', '-f', _staged_dump]), capture_output=True, timeout=30)
            except Exception: pass

    # 7. Start TAK Server
    plog("  rollback: starting takserver…")
    subprocess.run(_tak_systemctl('start'), shell=True, capture_output=True, timeout=90)  # v10.0.1: container-aware

    # 8. Restart Node-RED so it resyncs mission state from the restored DB.
    # Without this, Node-RED keeps trying to manage missions that were wiped by
    # the rollback, causing NPEs in TAK Server's mission API on the next poll.
    try:
        r_nr = subprocess.run(
            _sudo_wrap(['docker', 'restart', 'nodered']), capture_output=True, text=True, timeout=30
        )
        if r_nr.returncode == 0:
            plog("  rollback: Node-RED restarted (mission state resynced)")
        else:
            plog("  rollback: Node-RED not running or restart skipped (non-fatal)")
    except Exception as _e_nr:
        plog(f"  rollback: Node-RED restart error (non-fatal): {_e_nr}")

    plog(f"  ✓ rollback [{label}]: complete")
    return True, None


# Snapshot/rollback log stream
_snapshot_log   = []
_snapshot_status = {'running': False, 'complete': False, 'error': False}

def _tak_setup_snapshot_schedule(plog=None):
    """v10.0.6: scheduled snapshots now run IN-PROCESS (see _tak_snapshot_scheduler) —
    the v0.9.3 systemd timer NEVER worked (4 broken layers: parsed a `-p` port the
    console unit doesn't have → bogus 2121; curled http on an https-only console; used
    a session cookie nothing ever created; and the endpoint is @login_required with no
    loopback bypass — it 401'd even when reachable). All it produced was a red
    takserver-snapshot.service in `systemctl --failed` (seen on test12).

    This function now just REMOVES the legacy units (idempotent, clears the failed
    state) — the in-process scheduler reads tak_snapshot_schedule live, so enable/
    disable/schedule changes need no setup step at all."""
    if plog is None:
        plog = lambda m: print(m, flush=True)
    try:
        _legacy = ['/etc/systemd/system/takserver-snapshot.service',
                   '/etc/systemd/system/takserver-snapshot.timer']
        if any(os.path.exists(p) for p in _legacy):
            subprocess.run(_sudo_wrap(['systemctl', 'disable', '--now', 'takserver-snapshot.timer']),
                           capture_output=True, timeout=10)
            subprocess.run(_sudo_wrap(['rm', '-f'] + _legacy), capture_output=True, timeout=10)
            subprocess.run(_sudo_wrap(['systemctl', 'daemon-reload']), capture_output=True, timeout=10)
            subprocess.run(_sudo_wrap(['systemctl', 'reset-failed', 'takserver-snapshot.service']),
                           capture_output=True, timeout=10)
            plog("  snapshot schedule: legacy systemd timer removed — scheduling is in-process now")
        cfg = (load_settings().get('tak_snapshot_schedule') or {})
        if cfg.get('enabled'):
            plog(f"  snapshot schedule: enabled ({cfg.get('frequency', 'daily')} at "
                 f"{int(cfg.get('hour', 2)):02d}:{int(cfg.get('minute', 0)):02d}, "
                 f"retention={int(cfg.get('retention', 7))}) — runs in-process")
        else:
            plog("  snapshot schedule: disabled")
        return True
    except Exception as e:
        plog(f"  snapshot schedule: error — {e}")
        return False


def _tak_snapshot_scheduler():
    """v10.0.6: in-process scheduled TAK snapshots (replaces the never-functional
    systemd timer — see _tak_setup_snapshot_schedule docstring). Daemon thread,
    one-minute tick; reads tak_snapshot_schedule live so UI changes apply without
    any restart. Catch-up semantics match the old timer's Persistent=true: if the
    console was down at HH:MM, the snapshot fires on the next tick that day. The
    occurrence is stamped BEFORE the run so a failing snapshot doesn't retry every
    minute. Prunes only `scheduled-*` snapshots beyond the retention count —
    manual and pre-update snapshots are never touched."""
    global _snapshot_status, _snapshot_log
    import time as _st
    _st.sleep(180)  # let _startup_migrations finish before the first tick
    while True:
        try:
            s = load_settings()
            cfg = s.get('tak_snapshot_schedule') or {}
            if not cfg.get('enabled') or not os.path.exists('/opt/tak'):
                _st.sleep(60)
                continue
            now = datetime.now()
            hour = max(0, min(23, int(cfg.get('hour', 2))))
            minute = max(0, min(59, int(cfg.get('minute', 0))))
            weekly = (cfg.get('frequency', 'daily') == 'weekly')
            occurrence = now.strftime('%Y-%m-%d')
            due = ((not weekly or now.weekday() == 5)                      # Sat for weekly
                   and (now.hour, now.minute) >= (hour, minute)
                   and cfg.get('last_scheduled_run') != occurrence
                   and not _snapshot_status.get('running'))
            if not due:
                _st.sleep(60)
                continue
            # Stamp first — a failing snapshot must not re-fire every minute all day.
            cfg['last_scheduled_run'] = occurrence
            s['tak_snapshot_schedule'] = cfg
            save_settings(s)
            label = f"scheduled-{now.strftime('%Y%m%d-%H%M%S')}"
            def plog(m):
                entry = f"[{datetime.now().strftime('%H:%M:%S')}] {m}"
                _snapshot_log.append(entry)
                print(f"[snapshot-scheduler] {m}", flush=True)
            _snapshot_log = []
            _snapshot_status = {'running': True, 'complete': False, 'error': False}
            plog(f"scheduled snapshot starting — {label}")
            ok, result = _tak_snapshot(label, plog)
            if ok:
                _snapshot_status = {'running': False, 'complete': True, 'error': False}
                try:
                    s2 = load_settings()
                    sn = s2.get('tak_snapshots') or []
                    for snap in sn:
                        if snap.get('label') == label:
                            snap['source'] = 'scheduled'
                    # Retention: newest N scheduled snapshots survive.
                    retention = max(1, min(90, int(cfg.get('retention', 7))))
                    scheduled = sorted(
                        [x for x in sn if x.get('source') == 'scheduled'
                         or str(x.get('label', '')).startswith('scheduled-')],
                        key=lambda x: x.get('taken_at', ''), reverse=True)
                    for victim in scheduled[retention:]:
                        v_ok, v_label = _validate_snapshot_label(victim.get('label', ''))
                        if not v_ok:
                            continue
                        subprocess.run(_sudo_wrap(['rm', '-rf', os.path.join(SNAPSHOT_DIR, v_label)]),
                                       capture_output=True, timeout=60)
                        sn = [x for x in sn if x.get('label') != v_label]
                        plog(f"retention: pruned old scheduled snapshot {v_label}")
                    s2['tak_snapshots'] = sn
                    save_settings(s2)
                except Exception as _pe:
                    plog(f"retention prune error (non-fatal): {str(_pe)[:120]}")
                plog("scheduled snapshot complete")
            else:
                _snapshot_status = {'running': False, 'complete': False, 'error': True}
                plog(f"scheduled snapshot FAILED: {result}")
        except Exception as _sched_e:
            print(f"[snapshot-scheduler] tick error (non-fatal): {str(_sched_e)[:200]}", flush=True)
        _st.sleep(60)


